#[test]
fn authored_profile_shaped_name_cannot_publish_authority_transition_receipts() {
    let mut function = FunctionDefinition::new(
        "roomMembers.invite",
        FunctionKind::Mutation,
        FunctionRuntime::IbexModule(IbexModule {
            source: "globalThis.__snapbackHandlers = { fakeInvite() { return null; } };".to_owned(),
            export: "fakeInvite".to_owned(),
        }),
    );
    function.authority_profile_dependence = vec![crate::manifest::AuthorityProfileIdentityV1 {
        id: "roomMembers".to_owned(),
        generation: "sha256:profile-generation".to_owned(),
    }];
    assert!(function.generated_authority_operation.is_none());

    let transition = crate::storage::AuthorityTransitionReceiptV1 {
        declaration: "roomMembers".to_owned(),
        predecessor: None,
        successor: Some(crate::storage::AuthorityMembershipStateV1 {
            role: "invited".to_owned(),
            status: crate::storage::AuthorityMembershipStatusV1::Invited,
        }),
        subject: "user_invited".to_owned(),
        scope: Some("rooms_01k9m4x7p2q8we5rt3yu6a10s".to_owned()),
        invalidation_disposition:
            crate::storage::AuthorityInvalidationDispositionV1::GlobalAuthorizationEpochAdvanced,
    };
    let commit = crate::storage::MutationCommit {
        output: MutationOutput {
            version: 1,
            changed_count: 1,
            result: Value::Null,
            authority_transitions: vec![transition.clone()],
            ctx_ledger: None,
            settlement_mint_observations: Vec::new(),
            settlement_time_observation: None,
            settlement_sequence_allocations: Vec::new(),
        },
        changes: Vec::new(),
        read_dependencies: Vec::new(),
        write_dependencies: Vec::new(),
        job_enqueues: Vec::new(),
        job_changes: Vec::new(),
        asset_changes: Vec::new(),
        sequence_allocations: Vec::new(),
        authorization: None,
        authority_transitions: vec![transition],
        network_egress: Default::default(),
    };
    let mut snapback = LocalSnapback::memory().expect("receipt-gate fixture");
    snapback.functions = FunctionManifest {
        functions: vec![function],
        ..FunctionManifest::default()
    };
    let (result, _) = snapback.record_mutation_commit(
        "roomMembers.invite",
        "test",
        None,
        "mutation-authored-fake".to_owned(),
        &MutationSettlement::default(),
        Ok(commit),
        false,
    );
    assert!(
        result
            .expect("the synthetic commit remains successful")
            .authority_transitions
            .is_empty(),
        "an authored mutation cannot publish receipts merely by matching a generated name",
    );
}

#[test]
fn raw_schema_apply_cannot_bypass_governed_complete_pair_activation() {
    let mut snapback = LocalSnapback::memory().expect("governed local fixture");
    let mut schema = SchemaManifest::default();
    schema.visibility_governance = Some(VisibilityGovernanceActivationV1 {
        schema_version: "snapback.visibility-governance-activation.v1".to_owned(),
        required: true,
        generation_inputs_hash: "sha256:inputs".to_owned(),
        visibility_authorization_program_digest: "sha256:program".to_owned(),
        override_baseline_digest: "sha256:overrides".to_owned(),
        table_policy_baseline_digest: "sha256:policies".to_owned(),
        quarantine_head_digest: "sha256:quarantine".to_owned(),
        fixture_profiles: Vec::new(),
        production_windows: Vec::new(),
    });

    let error = snapback
        .apply_schema(schema)
        .expect_err("raw schema application must not bypass complete-pair activation");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_TABLE_VISIBILITY_GOVERNANCE_REMOTE_CUSTODY_UNAVAILABLE"
    );
}

#[test]
fn replayed_mutation_commit_never_claims_dependency_capture() {
    let replay = MutationCommit {
        output: MutationOutput {
            version: 7,
            changed_count: 1,
            result: json!({"replayed": true}),
            authority_transitions: Vec::new(),
            ctx_ledger: None,
            settlement_mint_observations: Vec::new(),
            settlement_time_observation: None,
            settlement_sequence_allocations: Vec::new(),
        },
        changes: Vec::new(),
        read_dependencies: Vec::new(),
        write_dependencies: Vec::new(),
        job_enqueues: Vec::new(),
        job_changes: Vec::new(),
        asset_changes: Vec::new(),
        sequence_allocations: Vec::new(),
        authorization: None,
        authority_transitions: Vec::new(),
        network_egress: Default::default(),
    };

    let capture = MutationDependencyCapture::from_commit(&replay);
    assert!(capture.reads.is_empty());
    assert!(capture.writes.is_empty());
    assert!(matches!(
        capture.read_provenance,
        crate::conformance::DependencyProvenance::Incomplete
    ));
    assert!(matches!(
        capture.write_provenance,
        crate::conformance::DependencyProvenance::Incomplete
    ));
}

// @ref LLP 0146#d1-declarationobservation-conformance — conformance must use
// the declarations/schema from the immutable read-manifest snapshot that
// executed, even if a same-name function generation reloads before handoff.
// @ref LLP 0012#call-time-generation-binding — the selected function
// generation remains the authority for every fact derived from its execution.
#[test]
fn read_lane_conformance_is_bound_to_the_executing_generation() {
    let directory = tempfile::tempdir().expect("conformance generation fixture directory");
    let database_path = directory.path().join("conformance-generation.sqlite3");
    let mut snapback = LocalSnapback::open(&database_path).expect("file-backed fixture");
    let table = |name: &str| TableManifest {
        name: name.to_owned(),
        fields: Vec::new(),
        indexes: Vec::new(),
        syncable: true,
        permission_backing: false,
        permission_fields: None,
        search_indexes: Vec::new(),
        vector_indexes: Vec::new(),
        search_live_limits: None,
        membership: None,
        authority_profile: None,
        asset_sharing: None,
        visibility: None,
        history: None,
    };
    snapback
        .apply_schema(SchemaManifest {
            tables: vec![table("tableA"), table("tableB")],
            ..SchemaManifest::default()
        })
        .expect("apply two-table fixture schema");
    let manifest = |declared: &str| {
        let mut function = FunctionDefinition::new(
            "generationBoundQuery",
            FunctionKind::Query,
            FunctionRuntime::IbexModule(IbexModule {
                source: "globalThis.__snapbackHandlers = { async generationBoundQuery(ctx) { return await ctx.db.query('tableB').collect(); } };".to_owned(),
                export: "generationBoundQuery".to_owned(),
            }),
        );
        function.read_set_summary.tables = vec![declared.to_owned()];
        FunctionManifest {
            functions: vec![function],
            ..FunctionManifest::default()
        }
    };
    let diagnostics = snapback.load_functions(manifest("tableA"));
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "generation A must load: {diagnostics:?}"
    );
    let lane = snapback.read_lane();
    assert!(lane.available(), "file-backed fixture has a read lane");

    let (captured_tx, captured_rx) = std::sync::mpsc::channel();
    let (resume_tx, resume_rx) = std::sync::mpsc::channel();
    let query = std::thread::spawn(move || {
        BEFORE_QUERY_RESULT_HANDOFF_HOOK.with(|slot| {
            *slot.borrow_mut() = Some(Box::new(move || {
                captured_tx.send(()).expect("signal captured dependencies");
                resume_rx.recv().expect("resume generation-A handoff");
            }));
        });
        let input = HandlerInput::default();
        let authority = InvocationGate::prepare_admitted_dev_input(
            InvocationSource::LocalQuery,
            ServerProfile::Dev,
            &input,
            lane.admission.admit_dev().expect("admit read-lane query"),
        )
        .expect("prepare read-lane query authority");
        lane.invoke_query_prepared_generation_with_facts(
            "generationBoundQuery",
            input,
            authority,
            None,
        )
        .expect("generation-A query succeeds")
    });

    captured_rx
        .recv_timeout(Duration::from_secs(5))
        .expect("generation A captures tableB before reload");
    let diagnostics = snapback.load_functions(manifest("tableB"));
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "generation B must load while A is at handoff: {diagnostics:?}"
    );
    resume_tx.send(()).expect("release generation-A handoff");
    let (invocation, _facts, conformance) = query.join().expect("query thread joins");

    assert_eq!(conformance.missing_reads, vec!["tableB".to_owned()]);
    assert_eq!(conformance.extra_reads, vec!["tableA".to_owned()]);
    assert_eq!(
        conformance.read_provenance,
        crate::conformance::DependencyProvenance::Complete
    );
    let current_generation = snapback
        .conformance_for_invocation(
            "generationBoundQuery",
            &invocation.read_dependencies,
            &[],
            crate::conformance::DependencyProvenance::Complete,
            crate::conformance::DependencyProvenance::Complete,
        )
        .expect("generation B still defines the same function name");
    assert!(
        current_generation.missing_reads.is_empty(),
        "the former later-turn lookup would conceal generation A's under-declaration"
    );
}

#[test]
fn connected_client_witnesses_do_not_advance_the_durable_version() {
    let snapback = LocalSnapback::memory().expect("connected-client storage fixture");
    let before = snapback
        .durable_version()
        .expect("durable version before witness");
    let registry = snapback.connected_clients.clone();
    let now = Instant::now();
    registry
        .register_managed_websocket("user-1", "connection-1", "grant-1", 1, now)
        .expect("register transport witness");
    assert!(registry.has_fresh_client("user-1", now));
    registry.remove_grant("connection-1", "grant-1");
    assert_eq!(
        snapback
            .durable_version()
            .expect("durable version after witness"),
        before,
        "process-local connectivity observation must not write durable state"
    );
}

#[test]
fn media_command_binding_is_required_and_resolved_before_mutation_execution() {
    let binding: crate::manifest::MediaCommandBindingV1 = serde_json::from_value(json!({
        "format": "snapback.media-command-binding.v1",
        "identity": format!("sha256:{}", "a".repeat(64)),
        "command": { "id": "app:sendMedia", "name": "sendMedia" },
        "targetMutation": {
            "id": "fn:createPost",
            "name": "createPost",
            "implementationHash": format!("sha256:{}", "b".repeat(64)),
            "argsContractHash": format!("sha256:{}", "c".repeat(64)),
            "resultContractHash": format!("sha256:{}", "d".repeat(64))
        },
        "passthroughArgs": [],
        "media": {
            "input": "media",
            "intent": "postMedia",
            "intentPolicyHash": format!("sha256:{}", "e".repeat(64)),
            "mutationArg": "assetIds",
            "minItems": 0,
            "maxItems": 3,
            "kinds": ["image"]
        },
        "parentResultPath": ["_id"],
        "collection": {
            "name": "gallery",
            "generation": format!("sha256:{}", "f".repeat(64)),
            "ownerTable": "posts",
            "ownerField": "ownerId",
            "childTable": "_snapback_asset_collection_gallery"
        },
        "itemIdentityPlan": {
            "format": "snapback:asset-collection-item-id:v1",
            "operation": "append",
            "order": "input"
        },
        "sharing": { "name": "none", "kind": "none" },
        "taskProfile": { "concurrency": 3 }
    }))
    .expect("closed media binding");
    let mut unknown = serde_json::to_value(&binding).expect("binding value");
    unknown
        .as_object_mut()
        .expect("binding object")
        .insert("callback".to_owned(), json!("forbidden"));
    assert!(
        serde_json::from_value::<crate::manifest::MediaCommandBindingV1>(unknown).is_err(),
        "MediaCommandBindingV1 decode is closed"
    );
    let mut function = FunctionDefinition::new(
        "createPost",
        FunctionKind::Mutation,
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(MutationPlan {
            owner_write_checks: Vec::new(),
            steps: Vec::new(),
            return_value: None,
        })),
    );
    function.id = "fn:createPost".to_owned();
    function.media_command_bindings = vec![binding.clone()];

    let error = prepare_media_command_invocation(&function, &HandlerInput::default(), None, None)
        .expect_err("plain dispatch is command-only");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_MEDIA_COMMAND_BINDING_REQUIRED"
    );

    let invocation = crate::manifest::MediaCommandInvocationV1 {
        binding_identity: binding.identity.clone(),
        command_identity: binding.command.id.clone(),
        attempt_id: "attempt-1".to_owned(),
        items: Vec::new(),
        principals: Vec::new(),
    };
    let input = HandlerInput {
        args: json!({ "assetIds": [] }),
        ..HandlerInput::default()
    };
    let resolved =
        prepare_media_command_invocation(&function, &input, Some(invocation), Some("attempt-1"))
            .expect("exact carrier resolves before handler selection")
            .expect("resolved media command");
    assert_eq!(resolved.binding.identity, binding.identity);
}

fn opaque_structured_field_type() -> FieldType {
    let contract = crate::manifest::StoredStructuredContractV1 {
        version: crate::manifest::STORED_STRUCTURED_CONTRACT_VERSION_V1,
        descriptor: ResultValueContract::Object {
            fields: vec![ResultObjectFieldContract {
                name: "label".to_owned(),
                required: true,
                value: ResultValueContract::String { max_bytes: 64 },
            }],
            allow_extra: false,
        },
        encoding: crate::manifest::STORED_STRUCTURED_ENCODING_V1.to_owned(),
    };
    let contract_hash = crate::manifest::stored_structured_contract_hash(&contract).unwrap();
    FieldType::Structured {
        contract,
        contract_hash,
    }
}

fn pending_live_test_entry(
    lane: PendingLiveLane,
    work: PendingLiveWork,
    first_deferred_at: Instant,
    coverage_through: u64,
    trace_commit_versions: Vec<u64>,
    trace_queued_ms: Option<f64>,
) -> PendingLiveFanout {
    PendingLiveFanout {
        lane,
        work,
        changes: Vec::new(),
        force_replace: lane != PendingLiveLane::Data,
        frames: 1,
        coverage_through,
        first_deferred_at,
        trace_commit_versions,
        trace_queued_ms,
        generation: 0,
    }
}

// @ref LLP 0200#25-cancellation-fairness-and-bounded-staleness — a
// superseding refresh carries the oldest undelivered age and trace.
#[test]
fn pending_refresh_supersession_inherits_age_and_trace() {
    let mut scheduler = PendingLiveScheduler::default();
    let inherited_age = Instant::now()
        .checked_sub(Duration::from_secs(2))
        .expect("test age remains representable");
    scheduler.push(
        "sub-a".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Data,
            PendingLiveWork::Data,
            inherited_age,
            41,
            vec![41],
            Some(4.0),
        ),
    );
    scheduler.push(
        "sub-a".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Refresh,
            PendingLiveWork::Refresh,
            Instant::now(),
            42,
            vec![42],
            Some(8.0),
        ),
    );

    let pending = scheduler.entries.get("sub-a").expect("latest refresh");
    assert_eq!(pending.first_deferred_at, inherited_age);
    assert_eq!(pending.trace_commit_versions, vec![41, 42]);
    assert_eq!(pending.trace_queued_ms, Some(4.0));
}

// @ref LLP 0200#25-cancellation-fairness-and-bounded-staleness — queue
// position cannot be reset by continuous same-lane supersession.
#[test]
fn pending_data_lane_serves_oldest_inherited_age_after_supersession() {
    let mut scheduler = PendingLiveScheduler::default();
    let now = Instant::now();
    let older_age = now
        .checked_sub(Duration::from_secs(2))
        .expect("older test age remains representable");
    let newer_age = now
        .checked_sub(Duration::from_secs(1))
        .expect("newer test age remains representable");
    scheduler.push(
        "older".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Data,
            PendingLiveWork::Data,
            older_age,
            10,
            vec![10],
            Some(1.0),
        ),
    );
    scheduler.push(
        "newer".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Data,
            PendingLiveWork::Data,
            newer_age,
            20,
            vec![20],
            Some(2.0),
        ),
    );
    scheduler.push(
        "older".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Data,
            PendingLiveWork::Data,
            now,
            30,
            vec![30],
            Some(3.0),
        ),
    );

    assert_eq!(scheduler.peek().as_deref(), Some("older"));
    let served = scheduler.pop("older").expect("oldest inherited entry");
    assert_eq!(served.coverage_through, 30);
    assert_eq!(scheduler.peek().as_deref(), Some("newer"));
}

// @ref LLP 0200#25-cancellation-fairness-and-bounded-staleness — only the
// latest generation can execute after queued work is superseded.
#[test]
fn pending_superseded_queued_evaluation_runs_latest_at_most_once() {
    let mut scheduler = PendingLiveScheduler::default();
    scheduler.push(
        "sub-a".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Data,
            PendingLiveWork::Data,
            Instant::now(),
            1,
            vec![1],
            Some(1.0),
        ),
    );
    let replaced_generation = scheduler.entries["sub-a"].generation;
    scheduler.push(
        "sub-a".to_owned(),
        pending_live_test_entry(
            PendingLiveLane::Refresh,
            PendingLiveWork::Refresh,
            Instant::now(),
            2,
            vec![2],
            Some(2.0),
        ),
    );
    let latest_generation = scheduler.entries["sub-a"].generation;
    assert_ne!(latest_generation, replaced_generation);
    assert_eq!(scheduler.entries.len(), 1);

    assert_eq!(scheduler.peek().as_deref(), Some("sub-a"));
    let served = scheduler.pop("sub-a").expect("latest generation");
    assert_eq!(served.generation, latest_generation);
    assert_eq!(served.coverage_through, 2);
    assert!(matches!(served.work, PendingLiveWork::Refresh));
    assert!(scheduler.peek().is_none());
    assert!(scheduler.pop("sub-a").is_none());
}

fn install_live_memo_scheduler(snapback: &mut LocalSnapback) {
    snapback
        .install_live_fanout_coalescer(Arc::new(crate::live_coalesce::LiveFanoutCoalescer::new()));
    // The focused cases exercise the default-on arm even if the parent test
    // process was launched with the production A/B switch set.
    snapback.pending_live_fanout.evaluation_memo.disabled = false;
}

fn live_memo_input(connection_id: &str, args: Value, principal: &str) -> LiveSubscribeInput {
    LiveSubscribeInput {
        connection_id: connection_id.to_owned(),
        input: HandlerInput {
            args,
            auth: AuthInput {
                user_id: Some(principal.to_owned()),
                ..AuthInput::default()
            },
            ..HandlerInput::default()
        },
        authorization_namespace: None,
        supersedes: None,
        resume_from_token: None,
    }
}

fn queue_and_flush_live_memo_refresh(snapback: &mut LocalSnapback) {
    snapback.notify_live_subscriptions(&[]);
    assert!(
        snapback.flush_pending_live_fanout(),
        "the refresh queued scheduler work"
    );
}

fn live_memo_frames(snapback: &mut LocalSnapback, connection_id: &str) -> Vec<Value> {
    drain_live_stream_through_test_sink(snapback, connection_id)
        .into_iter()
        .map(|frame| serde_json::from_str(&frame).expect("live memo frame JSON"))
        .collect()
}

fn single_holder_live_memo_fixture(
    connection_id: &str,
    effect_fence: Option<crate::ephemeral::ConnectionEffectFence>,
) -> (LocalSnapback, String) {
    let mut snapback = live_limit_snapback();
    install_live_memo_scheduler(&mut snapback);
    let subscription = match effect_fence {
        Some(effect_fence) => {
            let authority = InvocationGate::prepare_authority(
                InvocationSource::LiveInitialQuery,
                AuthMode::Dev,
                ServerProfile::Test,
                0,
                0,
                &WireAuthorityFields::default(),
                ResolvedAppAuthority::DevImpersonation {
                    user_id: "principal-a".to_owned(),
                    roles: Vec::new(),
                    local_dev_only: true,
                },
            )
            .expect("prepare fenced memo authority");
            snapback
                .subscribe_live_prepared_with_invalidation(
                    "listItems",
                    live_memo_input(connection_id, json!({}), "principal-a"),
                    authority,
                    LiveInvalidationAdmission {
                        session_mode: false,
                        connection: None,
                        effect_fence: Some(effect_fence),
                    },
                )
                .expect("subscribe fenced memo holder")
        }
        None => snapback
            .subscribe_live(
                "listItems",
                live_memo_input(connection_id, json!({}), "principal-a"),
            )
            .expect("subscribe memo holder"),
    };
    queue_and_flush_live_memo_refresh(&mut snapback);
    let entry = snapback
        .pending_live_fanout
        .evaluation_memo
        .entries
        .values()
        .next()
        .expect("one real evaluation populated the memo");
    assert_eq!(
        entry.holders,
        BTreeSet::from([subscription.subscription_id.clone()])
    );
    assert_eq!(
        snapback.pending_live_fanout.evaluation_memo.entries.len(),
        1
    );
    (snapback, subscription.subscription_id)
}

#[test]
fn live_evaluation_memo_six_same_principal_subscriptions_execute_once_and_deliver_six() {
    let mut snapback = live_limit_snapback();
    snapback
        .invoke_mutation(
            "insertItem",
            HandlerInput {
                args: json!({ "value": "shared" }),
                ..HandlerInput::default()
            },
        )
        .expect("seed shared result");
    install_live_memo_scheduler(&mut snapback);
    let connections = (0..6)
        .map(|index| format!("memo-same-{index}"))
        .collect::<Vec<_>>();
    for connection_id in &connections {
        snapback
            .subscribe_live(
                "listItems",
                live_memo_input(connection_id, json!({}), "principal-a"),
            )
            .expect("subscribe identical observer");
    }
    let before = snapback.live_evaluation_stats.clone();
    let deliveries_before = snapback.live_delivery.total_deliveries;

    queue_and_flush_live_memo_refresh(&mut snapback);

    assert_eq!(
        snapback.live_evaluation_stats.evaluations_started - before.evaluations_started,
        6,
        "delivery remains one scheduler turn per subscription"
    );
    assert_eq!(
        snapback.live_evaluation_stats.evaluations_executed - before.evaluations_executed,
        1
    );
    assert_eq!(
        snapback.live_evaluation_stats.memo_misses - before.memo_misses,
        1
    );
    assert_eq!(
        snapback.live_evaluation_stats.memo_hits - before.memo_hits,
        5
    );
    assert_eq!(
        snapback.live_delivery.total_deliveries - deliveries_before,
        6
    );

    let result_bytes = connections
        .iter()
        .map(|connection_id| {
            let frames = live_memo_frames(&mut snapback, connection_id);
            assert_eq!(frames.len(), 1, "one delivery for {connection_id}");
            assert_eq!(frames[0]["kind"], "live_replace");
            serde_json::to_vec(&frames[0]["rows"]).expect("serialize delivered result rows")
        })
        .collect::<Vec<_>>();
    assert!(
        result_bytes
            .windows(2)
            .all(|pair| pair[0].as_slice() == pair[1].as_slice()),
        "every subscriber consumes byte-identical result rows"
    );
}

#[test]
fn live_evaluation_memo_same_key_executes_again_in_a_later_drain_cycle() {
    let mut snapback = live_limit_snapback();
    install_live_memo_scheduler(&mut snapback);
    for connection_id in ["memo-cycle-a", "memo-cycle-b"] {
        snapback
            .subscribe_live(
                "listItems",
                live_memo_input(connection_id, json!({}), "principal-a"),
            )
            .expect("subscribe cross-cycle observer");
    }

    queue_and_flush_live_memo_refresh(&mut snapback);
    let first_cycle = snapback.pending_live_fanout.drain_cycle;
    assert_eq!(
        snapback.pending_live_fanout.evaluation_memo.entries.len(),
        1
    );
    let before = snapback.live_evaluation_stats.clone();

    // No commit or other invalidation separates these refreshes. The second
    // idle-to-active transition alone must make the predecessor memo unusable.
    queue_and_flush_live_memo_refresh(&mut snapback);

    assert_ne!(snapback.pending_live_fanout.drain_cycle, first_cycle);
    assert_eq!(
        snapback.live_evaluation_stats.evaluations_executed - before.evaluations_executed,
        1,
        "the first same-key turn of the later drain cycle executes"
    );
    assert_eq!(
        snapback.live_evaluation_stats.memo_misses - before.memo_misses,
        1
    );
    assert_eq!(
        snapback.live_evaluation_stats.memo_hits - before.memo_hits,
        1,
        "sharing remains available within the later drain cycle"
    );
    assert_eq!(
        snapback.pending_live_fanout.evaluation_memo.entries.len(),
        1
    );
    assert!(
        snapback
            .pending_live_fanout
            .evaluation_memo
            .entries
            .keys()
            .all(|key| key.drain_cycle == snapback.pending_live_fanout.drain_cycle),
        "predecessor-cycle entries are retired at the next cycle boundary"
    );
}

