struct CounterRandom(AtomicU8);

impl CounterRandom {
    fn new() -> Self {
        Self(AtomicU8::new(1))
    }
}

impl RandomSource for CounterRandom {
    fn fill(&self, destination: &mut [u8]) -> Result<(), CryptoError> {
        destination.fill(self.0.fetch_add(1, Ordering::SeqCst));
        Ok(())
    }
}

#[test]
fn mixed_bundle_v2_pins_rows_and_registers_only_identity_live_children() {
    // @ref LLP 0264#d2-v1-default-write-posture-by-policy-kind — the mixed
    // bundle fixture writes an ordinary explicitly public table.
    let schema = SchemaManifest {
        app_id: "mixed-acceptance".to_owned(),
        schema_hash: Some("mixed-schema".to_owned()),
        tables: vec![TableManifest {
            name: "todos".to_owned(),
            fields: vec![FieldManifest {
                name: "title".to_owned(),
                field_type: FieldType::String,
                optional: false,
            }],
            indexes: Vec::new(),
            syncable: true,
            permission_backing: false,
            permission_fields: None,
            search_indexes: Vec::new(),
            vector_indexes: Vec::new(),
            search_live_limits: None,
            membership: None,
            authority_profile: None,
            asset_sharing: None,
            visibility: Some(crate::manifest::TableVisibilityV1::PublicRead),
            history: None,
        }],
        ..SchemaManifest::default()
    };
    let plan = QueryPlan {
        table_visibility: None,
        table: "todos".to_owned(),
        filters: Vec::new(),
        order: Vec::new(),
        limit: None,
        membership_filters: Vec::new(),
        indexed_by: None,
    };
    let mut live = FunctionDefinition::new(
        "liveTodos",
        FunctionKind::LiveQuery,
        FunctionRuntime::HostPlan(HandlerPlan::Query(plan.clone())),
    );
    live.auth_requirement = Some(AuthRequirement::Public);
    live.authority_independent = true;
    let mut plain = FunctionDefinition::new(
        "plainTodos",
        FunctionKind::Query,
        FunctionRuntime::HostPlan(HandlerPlan::Query(plan)),
    );
    plain.auth_requirement = Some(AuthRequirement::Public);
    plain.authority_independent = true;
    let insert = FunctionDefinition::new(
        "addTodo",
        FunctionKind::Mutation,
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(MutationPlan {
            owner_write_checks: Vec::new(),
            steps: vec![MutationStep::Insert {
                table: "todos".to_owned(),
                values: BTreeMap::from([("title".to_owned(), ValueExpr::Arg("title".to_owned()))]),
                bind_id_as: None,
            }],
            return_value: None,
        })),
    );
    let functions = FunctionManifest {
        app_id: "mixed-acceptance".to_owned(),
        bundle_hash: Some("mixed-functions".to_owned()),
        functions: vec![live, plain, insert],
        ..FunctionManifest::default()
    };
    let mut snapback = LocalSnapback::memory().expect("mixed memory fixture");
    snapback.apply_schema(schema).expect("mixed schema");
    assert!(
        snapback
            .load_functions(functions)
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error)
    );
    snapback
        .invoke_mutation(
            "addTodo",
            HandlerInput {
                args: json!({ "title": "one" }),
                ..HandlerInput::default()
            },
        )
        .expect("seed todo");
    let entry = crate::bundle::BundleRouteEntry {
        route: "/mixed".to_owned(),
        queries: vec![
            crate::bundle::BundleQuerySpec {
                function: "liveTodos".to_owned(),
                args: json!({}),
            },
            crate::bundle::BundleQuerySpec {
                function: "plainTodos".to_owned(),
                args: json!({}),
            },
        ],
        persist: None,
        register_group_eligible: false,
        mixed_group_eligible: true,
        mixed_profile: Some(crate::bundle::MixedRouteProfileV2 {
            format_version: 2,
            profile: "mixed-route.v2".to_owned(),
            normalized_composite_plan: json!({}),
            plan_hash: format!("sha256:{}", "a".repeat(64)),
        }),
    };
    let admission = snapback.admission.admit_dev().expect("dev admission");
    let authority = InvocationGate::prepare_admitted_authority(
        InvocationSource::HttpQuery,
        crate::manifest::AuthMode::Dev,
        ServerProfile::Dev,
        admission,
        &WireAuthorityFields::default(),
        ResolvedAppAuthority::Anonymous,
        None,
    )
    .expect("bundle authority");
    let response = snapback
        .evaluate_bundle(
            &entry,
            &BTreeMap::new(),
            "/mixed",
            &AuthInput::default(),
            &authority,
            Some(super::BundleRegisterTarget {
                connection_id: "mixed-connection".to_owned(),
                effect_fence: crate::ephemeral::ConnectionEffectFence::anonymous(
                    "mixed-stream",
                    "mixed-grant",
                ),
                invalidation_connection: None,
                authorization_namespaces: Vec::new(),
                mixed_children: Some(vec![
                    crate::bundle::MixedChildAdmissionV2 {
                        node_plan_hash: format!("sha256:{}", "1".repeat(64)),
                        live: true,
                    },
                    crate::bundle::MixedChildAdmissionV2 {
                        node_plan_hash: format!("sha256:{}", "2".repeat(64)),
                        live: false,
                    },
                ]),
            }),
        )
        .expect("mixed bundle");
    assert_eq!(response.format_version, Some(2));
    assert_eq!(response.profile.as_deref(), Some("mixed-route.v2"));
    assert_eq!(response.entries.len(), 2);
    assert_eq!(response.entries[0].rows, response.entries[1].rows);
    assert_eq!(
        response.entries[0].subscription_id.as_deref(),
        snapback.subscriptions.keys().next().map(String::as_str)
    );
    assert!(response.entries[1].subscription_id.is_none());
    assert_eq!(
        snapback.subscriptions.len(),
        1,
        "plain child owns no live state"
    );
    assert_eq!(
        snapback
            .subscriptions
            .values()
            .next()
            .map(|subscription| subscription.function.as_str()),
        Some("liveTodos"),
    );
    assert_eq!(
        serde_json::to_value(&response.entries[0].delivery).expect("live delivery"),
        json!({ "kind": "registered-live", "nodePlanHash": format!("sha256:{}", "1".repeat(64)) }),
    );
    assert_eq!(
        serde_json::to_value(&response.entries[1].delivery).expect("plain delivery"),
        json!({ "kind": "read-only", "nodePlanHash": format!("sha256:{}", "2".repeat(64)) }),
    );
    let aggregate = response.aggregate.expect("mixed aggregate");
    assert_eq!(
        (aggregate.live_children, aggregate.read_only_children),
        (1, 1)
    );
    assert_eq!(aggregate.weakest, "read-only");
}

// @ref LLP 0214#62-projection-rules — registered and mixed-bundle live
// children must receive the real session's claims in their first snapshot,
// not only after a retained invalidation rerun.
#[test]
fn bundled_live_first_snapshots_preserve_catalog_session_claims() {
    let mut snapback = retainable_sessions_snapback();
    snapback.admission = AdmissionController::from_mode_state(&settled_sessions_state())
        .expect("settled Sessions admission controller");
    let connection = install_test_invalidation(&mut snapback);

    let resolved = lease_session_authority().resolved().clone();
    let admission = snapback
        .admission
        .admit_for_mode(AuthMode::Sessions)
        .expect("parent route admission");
    let authority = snapback
        .prepare_resolved_authority(
            InvocationSource::HttpQuery,
            AuthMode::Sessions,
            ServerProfile::Test,
            admission,
            &WireAuthorityFields::default(),
            resolved,
            now_millis(),
        )
        .expect("prepare parent route authority with catalog claims");
    let route = |mixed: bool| crate::bundle::BundleRouteEntry {
        route: if mixed {
            "/claims-mixed".to_owned()
        } else {
            "/claims-registered".to_owned()
        },
        queries: vec![crate::bundle::BundleQuerySpec {
            function: "claimsSnapshot".to_owned(),
            args: json!({}),
        }],
        persist: None,
        register_group_eligible: !mixed,
        mixed_group_eligible: mixed,
        mixed_profile: mixed.then(|| crate::bundle::MixedRouteProfileV2 {
            format_version: 2,
            profile: "mixed-route.v2".to_owned(),
            normalized_composite_plan: json!({}),
            plan_hash: format!("sha256:{}", "c".repeat(64)),
        }),
    };
    let target = |connection_id: &str, instance: u64, mixed: bool| super::BundleRegisterTarget {
        connection_id: connection_id.to_owned(),
        effect_fence: crate::ephemeral::ConnectionEffectFence::session(
            "claims-stream",
            format!("claims-grant-{instance}"),
            "session_1",
            1,
        ),
        invalidation_connection: Some(connection.clone()),
        authorization_namespaces: vec![Some(QueryNamespace {
            client_store_id: "claims-store".to_owned(),
            query_key: "claimsSnapshot:{}".to_owned(),
            query_instance_id: instance,
        })],
        mixed_children: mixed.then(|| {
            vec![crate::bundle::MixedChildAdmissionV2 {
                node_plan_hash: format!("sha256:{}", "d".repeat(64)),
                live: true,
            }]
        }),
    };

    for (mixed, connection_id, instance) in [
        (false, "claims-registered", 601),
        (true, "claims-mixed", 602),
    ] {
        let entry = route(mixed);
        let response = snapback
            .evaluate_bundle(
                &entry,
                &BTreeMap::new(),
                &entry.route,
                &AuthInput::default(),
                &authority,
                Some(target(connection_id, instance, mixed)),
            )
            .expect("claims bundle first snapshot");
        assert_eq!(
            response.entries[0].rows,
            vec![json!({ "value": "lease@example.test" })],
            "{} first snapshot must contain claims",
            if mixed {
                "mixed-bundle"
            } else {
                "registered bundle"
            }
        );
    }
}

