#[test]
fn live_search_authority_fact_is_exactly_schema_public_read() {
    let search = SearchIndexManifestV1 {
        format_version: 1,
        name: "search_events".to_owned(),
        semantic_version: "events.live.v1".to_owned(),
        analyzer: SEARCH_ANALYZER.to_owned(),
        analyzer_tables_digest: crate::search::unicode17_generated::ANALYZER_TABLES_DIGEST
            .to_owned(),
        text_fields: BTreeMap::from([(
            "title".to_owned(),
            SearchTextFieldV1 {
                weight: 1,
                classification: SearchFieldClassV1::Public,
            },
        )]),
        field_classifications: BTreeMap::new(),
        equality_filters: Vec::new(),
        stored_fields: vec!["title".to_owned()],
        highlight_fields: Vec::new(),
        visibility: SearchVisibilityV1::PublicRead,
        tie_break: "score-desc-row-id-asc.v1".to_owned(),
        source_limits: Default::default(),
        query_limits: Default::default(),
        cursor_limits: Default::default(),
        maintenance_limits: Default::default(),
        live_limits: None,
    };
    let schema = SchemaManifest {
        tables: vec![TableManifest {
            name: "events".to_owned(),
            fields: vec![FieldManifest {
                name: "title".to_owned(),
                field_type: FieldType::String,
                optional: false,
            }],
            indexes: Vec::new(),
            search_indexes: vec![search],
            vector_indexes: Vec::new(),
            search_live_limits: None,
            syncable: false,
            permission_backing: false,
            permission_fields: None,
            membership: None,
            authority_profile: None,
            asset_sharing: None,
            visibility: None,
            history: None,
        }],
        ..SchemaManifest::default()
    };
    let mut function = FunctionDefinition::new(
        "live-search-events",
        FunctionKind::LiveQuery,
        FunctionRuntime::HostPlan(HandlerPlan::SearchQuery(SearchQueryPlanV1 {
            table: "events".to_owned(),
            index: "search_events".to_owned(),
            parser: SEARCH_PARSER.to_owned(),
            result_projection: "search-page-v1".to_owned(),
            required_capability: SEARCH_CAPABILITY.to_owned(),
            resource_arg: None,
        })),
    );
    function.auth_requirement = Some(crate::manifest::AuthRequirement::Public);
    function.authority_independent = true;
    function.required_capabilities = vec![
        "full_text_search_v1".to_owned(),
        "live_subscriptions".to_owned(),
        "live_full_text_search_v1".to_owned(),
        "args_contract_v1".to_owned(),
        "result_contract_v1".to_owned(),
    ];
    let args_contract = FunctionArgsContract {
        fields: vec![
            ResultObjectFieldContract {
                name: "query".to_owned(),
                required: true,
                value: ResultValueContract::PlatformSchemaRef {
                    authority: SchemaRefAuthority::Platform,
                    schema: crate::manifest::SCHEMA_REF_SEARCH_QUERY_AST_V1.to_owned(),
                },
            },
            ResultObjectFieldContract {
                name: "limit".to_owned(),
                required: false,
                value: ResultValueContract::Integer { min: 1, max: 50 },
            },
        ],
    };
    function.args_contract_hash =
        Some(crate::manifest::args_contract_hash(&args_contract).expect("args contract hashes"));
    function.args_contract = Some(args_contract);
    function.result_contract = crate::manifest::expected_search_result_contract(
        &schema.tables[0],
        &schema.tables[0].search_indexes[0],
    )
    .expect("schema derives the exact SearchItem contract");
    function.result_contract_hash = Some(
        crate::manifest::result_contract_hash(&function.result_contract)
            .expect("result contract hashes"),
    );

    for (label, mutate) in [
        ("empty", None),
        (
            "extra",
            Some(ResultObjectFieldContract {
                name: "extra".to_owned(),
                required: false,
                value: ResultValueContract::String { max_bytes: 16 },
            }),
        ),
        (
            "after",
            Some(ResultObjectFieldContract {
                name: "after".to_owned(),
                required: false,
                value: ResultValueContract::String { max_bytes: 2_048 },
            }),
        ),
    ] {
        let mut forged = function.clone();
        let contract = forged.args_contract.as_mut().expect("args contract");
        if let Some(field) = mutate {
            contract.fields.push(field);
        } else {
            contract.fields.clear();
        }
        forged.args_contract_hash =
            Some(crate::manifest::args_contract_hash(contract).expect("forged args hash"));
        assert_eq!(
            FunctionManifest {
                functions: vec![forged],
                ..FunctionManifest::default()
            }
            .validate_artifact()
            .expect_err("live search args near-miss must refuse")
            .diagnostic
            .code,
            "SNAPBACK_FUNCTION_ARGS_CONTRACT_INVALID",
            "{label}",
        );
    }

    let mut unknown_result = function.clone();
    unknown_result.result_contract = FunctionResultContract::Unknown;
    unknown_result.result_contract_hash = None;
    assert_eq!(
        FunctionManifest {
            functions: vec![unknown_result],
            ..FunctionManifest::default()
        }
        .validate_artifact()
        .expect_err("live search cannot retain an unknown result contract")
        .diagnostic
        .code,
        "SNAPBACK_HANDLER_RESULT_CONTRACT_INVALID",
    );
    let valid = FunctionManifest {
        functions: vec![function.clone()],
        ..FunctionManifest::default()
    };
    valid
        .validate_artifact()
        .expect("LiveQuery + SearchQuery is a structurally valid unpublished carrier");
    validate_function_schema_references(&valid, &schema)
        .expect("public-read binds authorityIndependent at pair activation");

    let mut wrong_result = valid.clone();
    let FunctionResultContract::Records { record, .. } =
        &mut wrong_result.functions[0].result_contract
    else {
        unreachable!();
    };
    let ResultValueContract::Object { fields, .. } = record else {
        unreachable!();
    };
    fields.retain(|field| field.name != "highlights");
    wrong_result.functions[0].result_contract_hash = Some(
        crate::manifest::result_contract_hash(&wrong_result.functions[0].result_contract)
            .expect("forged result hashes"),
    );
    wrong_result
        .validate_artifact()
        .expect("the forged row remains generically well-formed");
    assert_eq!(
        validate_function_schema_references(&wrong_result, &schema)
            .expect_err("schema pair must reject a weakened SearchItem contract")
            .diagnostic
            .code,
        "SNAPBACK_HANDLER_RESULT_CONTRACT_INVALID",
    );

    let mut omitted = valid.clone();
    omitted.functions[0].authority_independent = false;
    assert_eq!(
        validate_function_schema_references(&omitted, &schema)
            .expect_err("public-read live search must carry the exact fact")
            .diagnostic
            .code,
        "SNAPBACK_AUTHORITY_INDEPENDENT_INVALID",
    );

    let mut owner_schema = schema.clone();
    owner_schema.tables[0].search_indexes[0].visibility = SearchVisibilityV1::Owner {
        field: "title".to_owned(),
    };
    assert_eq!(
        validate_function_schema_references(&valid, &owner_schema)
            .expect_err("owner visibility cannot forge authority independence")
            .diagnostic
            .code,
        "SNAPBACK_AUTHORITY_INDEPENDENT_INVALID",
    );

    let routes = crate::bundle::RoutesManifest {
        format_version: crate::bundle::ROUTES_MANIFEST_FORMAT_VERSION,
        app: valid.app_id.clone(),
        routes: vec![crate::bundle::BundleRouteEntry {
            route: "/".to_owned(),
            queries: vec![crate::bundle::BundleQuerySpec {
                function: "live-search-events".to_owned(),
                args: serde_json::json!({ "query": {} }),
            }],
            persist: None,
            register_group_eligible: true,
            mixed_group_eligible: false,
            mixed_profile: None,
        }],
    };
    let route_error = LocalSnapback::validate_routes_manifest_against(&routes, &valid, &schema)
        .expect_err("a direct route artifact cannot opt live search into register mode");
    assert_eq!(
        route_error.diagnostic.code,
        "SNAPBACK_ROUTES_MANIFEST_INVALID"
    );
    assert!(route_error.diagnostic.message.contains("live-search child"));

    let mut inline = valid;
    inline.functions[0].public_inline = true;
    assert_eq!(
        inline
            .validate_artifact()
            .expect_err("search plans remain excluded from publicInline")
            .diagnostic
            .code,
        "SNAPBACK_PUBLIC_INLINE_INVALID",
    );
}

#[test]
fn live_search_skips_disjoint_table_commits_and_reruns_searched_table_commits() {
    use crate::search::types::{SearchClauseV1, SearchQueryAstV1, SearchTermV1};

    let search = SearchIndexManifestV1 {
        format_version: 1,
        name: "search_events".to_owned(),
        semantic_version: "events.live.matcher.v1".to_owned(),
        analyzer: SEARCH_ANALYZER.to_owned(),
        analyzer_tables_digest: crate::search::unicode17_generated::ANALYZER_TABLES_DIGEST
            .to_owned(),
        text_fields: BTreeMap::from([(
            "title".to_owned(),
            SearchTextFieldV1 {
                weight: 1,
                classification: SearchFieldClassV1::Public,
            },
        )]),
        field_classifications: BTreeMap::new(),
        equality_filters: Vec::new(),
        stored_fields: vec!["title".to_owned()],
        highlight_fields: Vec::new(),
        visibility: SearchVisibilityV1::PublicRead,
        tie_break: "score-desc-row-id-asc.v1".to_owned(),
        source_limits: Default::default(),
        query_limits: Default::default(),
        cursor_limits: Default::default(),
        maintenance_limits: Default::default(),
        live_limits: None,
    };
    let table =
        |name: &str, field: &str, search_indexes: Vec<SearchIndexManifestV1>| TableManifest {
            name: name.to_owned(),
            fields: vec![FieldManifest {
                name: field.to_owned(),
                field_type: FieldType::String,
                optional: false,
            }],
            indexes: Vec::new(),
            search_indexes,
            vector_indexes: Vec::new(),
            search_live_limits: None,
            syncable: false,
            permission_backing: false,
            authority_profile: None,
            permission_fields: None,
            membership: None,
            asset_sharing: None,
            visibility: Some(crate::manifest::TableVisibilityV1::PublicRead),
            history: None,
        };
    let mut snapback = LocalSnapback::memory().expect("memory snapback");
    snapback
        .db
        .schema_seed()
        .apply_schema(SchemaManifest {
            required_capabilities: vec![SEARCH_CAPABILITY.to_owned()],
            tables: vec![
                table("events", "title", vec![search]),
                table("audit", "message", Vec::new()),
            ],
            ..SchemaManifest::default()
        })
        .expect("search schema");

    let mut live_search = FunctionDefinition::new(
        "liveSearchEvents",
        FunctionKind::LiveQuery,
        FunctionRuntime::HostPlan(HandlerPlan::SearchQuery(SearchQueryPlanV1 {
            table: "events".to_owned(),
            index: "search_events".to_owned(),
            parser: SEARCH_PARSER.to_owned(),
            result_projection: "search-page-v1".to_owned(),
            required_capability: SEARCH_CAPABILITY.to_owned(),
            resource_arg: None,
        })),
    );
    live_search.auth_requirement = Some(AuthRequirement::Public);
    live_search.authority_independent = true;
    let insert = |name: &str, table: &str, field: &str| {
        FunctionDefinition::new(
            name,
            FunctionKind::Mutation,
            FunctionRuntime::HostPlan(HandlerPlan::Mutation(MutationPlan {
                owner_write_checks: Vec::new(),
                steps: vec![MutationStep::Insert {
                    table: table.to_owned(),
                    values: BTreeMap::from([(field.to_owned(), ValueExpr::Arg(field.to_owned()))]),
                    bind_id_as: None,
                }],
                return_value: None,
            })),
        )
    };
    // The capability is intentionally unpublished, so this unit fixture
    // installs the already-admitted runtime carrier directly rather than
    // forging a served capability claim through the artifact loader.
    snapback.functions = FunctionManifest {
        functions: vec![
            live_search,
            insert("insertEvent", "events", "title"),
            insert("insertAudit", "audit", "message"),
        ],
        ..FunctionManifest::default()
    };

    let query = SearchQueryAstV1 {
        all: vec![SearchClauseV1::Term(SearchTermV1 {
            value: "needle".to_owned(),
            field: None,
        })],
    };
    let established = snapback
        .subscribe_live(
            "liveSearchEvents",
            LiveSubscribeInput {
                connection_id: "search-conn".to_owned(),
                input: HandlerInput {
                    args: json!({ "query": query }),
                    ..HandlerInput::default()
                },
                authorization_namespace: None,
                supersedes: None,
                resume_from_token: None,
            },
        )
        .expect("live search subscribes");
    assert!(established.snapshot.expect("snapshot").rows.is_empty());

    let before = snapback.inspect().expect("inspect before").live_matcher;
    snapback
        .invoke_mutation(
            "insertAudit",
            HandlerInput {
                args: json!({ "message": "disjoint" }),
                ..HandlerInput::default()
            },
        )
        .expect("disjoint commit");
    let after_disjoint = snapback.inspect().expect("inspect disjoint").live_matcher;
    assert_eq!(after_disjoint.skip, before.skip + 1);
    assert_eq!(
        after_disjoint.conservative_fallback, before.conservative_fallback,
        "a disjoint table commit must skip before search execution"
    );
    assert!(snapback.drain_outbox("search-conn").is_empty());

    snapback
        .invoke_mutation(
            "insertEvent",
            HandlerInput {
                args: json!({ "title": "needle in a haystack" }),
                ..HandlerInput::default()
            },
        )
        .expect("searched-table commit");
    let after_event = snapback.inspect().expect("inspect event").live_matcher;
    assert_eq!(after_event.match_replace, after_disjoint.match_replace + 1);
    let frames = rqs_drained_envelopes(&mut snapback, "search-conn");
    assert_eq!(frames.len(), 1, "searched-table commit re-runs once");
    assert_eq!(frames[0]["kind"], "live_replace");
    assert_eq!(frames[0]["rows"].as_array().expect("rows").len(), 1);
}

#[test]
fn owner_vector_query_requires_authenticated_pair_authority() {
    let index = VectorIndexManifestV1 {
        format_version: 1,
        name: "by_embedding".to_owned(),
        semantic_version: "documents.embedding.v1".to_owned(),
        vector_field: "embedding".to_owned(),
        dimensions: 2,
        metric: VectorMetricV1::L2sq,
        distance_profile: VECTOR_DISTANCE_PROFILE_ID.to_owned(),
        ordering_profile: VECTOR_ORDERING_PROFILE_ID.to_owned(),
        field_classifications: BTreeMap::from([
            ("embedding".to_owned(), VectorFieldClassV1::Private),
            ("ownerId".to_owned(), VectorFieldClassV1::Private),
        ]),
        equality_filters: Vec::new(),
        stored_fields: Vec::new(),
        visibility: VectorVisibilityV1::Owner {
            field: "ownerId".to_owned(),
        },
        tie_break: VectorTieBreakV1::IdAsc,
        max_indexed_vectors_per_partition: 4,
        max_scalar_pairs: 8,
        maintenance_limits: VectorMaintenanceLimitsV1::default(),
    };
    let schema = SchemaManifest {
        tables: vec![TableManifest {
            name: "documents".to_owned(),
            fields: vec![
                FieldManifest {
                    name: "embedding".to_owned(),
                    field_type: FieldType::Vector { dimensions: 2 },
                    optional: false,
                },
                FieldManifest {
                    name: "ownerId".to_owned(),
                    field_type: FieldType::Principal,
                    optional: false,
                },
            ],
            indexes: Vec::new(),
            search_indexes: Vec::new(),
            vector_indexes: vec![index],
            search_live_limits: None,
            syncable: false,
            permission_backing: false,
            permission_fields: None,
            membership: None,
            authority_profile: None,
            asset_sharing: None,
            visibility: None,
            history: None,
        }],
        ..SchemaManifest::default()
    };
    let mut function = FunctionDefinition::new(
        "nearest-documents",
        FunctionKind::Query,
        FunctionRuntime::HostPlan(HandlerPlan::VectorQuery(VectorQueryPlanV1 {
            table: "documents".to_owned(),
            index: "by_embedding".to_owned(),
            distance_profile: VECTOR_DISTANCE_PROFILE_ID.to_owned(),
            result_projection: VECTOR_RESULT_PROJECTION.to_owned(),
            required_capability: VECTOR_CAPABILITY.to_owned(),
        })),
    );
    let index = &schema.tables[0].vector_indexes[0];
    let args = crate::manifest::expected_vector_args_contract(index);
    function.args_contract_hash =
        Some(crate::manifest::args_contract_hash(&args).expect("vector args contract hashes"));
    function.args_contract = Some(args);
    function.result_contract =
        crate::manifest::expected_vector_result_contract(&schema.tables[0], index)
            .expect("vector result contract derives");
    function.result_contract_hash = Some(
        crate::manifest::result_contract_hash(&function.result_contract)
            .expect("vector result contract hashes"),
    );

    for requirement in [AuthRequirement::Public, AuthRequirement::OptionalUser] {
        let mut forged = function.clone();
        forged.auth_requirement = Some(requirement);
        assert_eq!(
            validate_function_schema_references(
                &FunctionManifest {
                    functions: vec![forged],
                    ..FunctionManifest::default()
                },
                &schema,
            )
            .expect_err("owner vector query must not admit missing effective-user authority")
            .diagnostic
            .code,
            "SNAPBACK_VECTOR_QUERY_PLAN_INVALID",
        );
    }

    function.auth_requirement = Some(AuthRequirement::Authenticated);
    validate_function_schema_references(
        &FunctionManifest {
            functions: vec![function],
            ..FunctionManifest::default()
        },
        &schema,
    )
    .expect("authenticated owner vector query admits");
}

#[test]
fn maintenance_failures_are_counted_redacted_and_rate_limited() {
    let mut snapback = LocalSnapback::memory().expect("memory snapback");
    let sensitive = SnapbackError::error(
        "SNAPBACK_TEST_MAINTENANCE_CAUSE",
        "test",
        "room-secret must not be retained",
    );
    let initial_diagnostics = snapback.recent_diagnostics.len();

    snapback.record_maintenance_error(
        MaintenanceOperation::PermissionResolution,
        &sensitive,
        1_000,
    );
    snapback.record_maintenance_error(
        MaintenanceOperation::PermissionResolution,
        &sensitive,
        2_000,
    );
    snapback.record_maintenance_error(
        MaintenanceOperation::PermissionResolution,
        &sensitive,
        61_000,
    );
    snapback.record_maintenance_error(MaintenanceOperation::JournalPrune, &sensitive, 3_000);

    assert_eq!(snapback.maintenance.permission_resolution_failures, 3);
    assert_eq!(snapback.maintenance.journal_prune_failures, 1);
    assert_eq!(
        snapback.maintenance.last_permission_resolution_failure_ms,
        Some(61_000)
    );
    assert_eq!(
        snapback.maintenance.last_journal_prune_failure_ms,
        Some(3_000)
    );
    let maintenance = snapback
        .recent_diagnostics
        .iter()
        .skip(initial_diagnostics)
        .collect::<Vec<_>>();
    assert_eq!(maintenance.len(), 3, "one per rate-limit window and kind");
    assert_eq!(maintenance[0].details["failureCount"], 1);
    assert_eq!(maintenance[1].details["failureCount"], 3);
    assert_eq!(maintenance[2].details["failureCount"], 1);
    assert!(maintenance.iter().all(|diagnostic| {
        diagnostic.details["causeCode"] == "SNAPBACK_TEST_MAINTENANCE_CAUSE"
            && !diagnostic.message.contains("room-secret")
            && !diagnostic.details.to_string().contains("room-secret")
    }));

    let public: PublicInspect = snapback.inspect().expect("inspect").into();
    assert_eq!(public.maintenance, snapback.maintenance);
}

#[test]
fn embedded_ibex_generations_report_loaded_without_cli_unavailability_noise() {
    let mut snapback = LocalSnapback::memory().expect("memory snapback");
    snapback.force_ibex_cli_unavailable_for_test();

    let initial = snapback.inspect().expect("initial inspect");
    assert!(!initial.runtime.ibex_cli.available);
    assert_eq!(initial.runtime.ibex_cli.path, None);
    assert_eq!(initial.runtime.ibex_cli.version, None);
    assert!(initial.capability_gaps.iter().any(|gap| gap == "ibex_cli"));
    assert!(
        initial
            .recent_diagnostics
            .iter()
            .all(|diagnostic| { diagnostic.code != "SNAPBACK_IBEX_CLI_UNAVAILABLE" })
    );

    let manifest = FunctionManifest {
        bundle_hash: Some("embedded-generation-no-cli".to_owned()),
        functions: vec![FunctionDefinition::new(
            "embeddedQuery",
            FunctionKind::Query,
            FunctionRuntime::IbexModule(IbexModule {
                source: "globalThis.__snapbackHandlers = { async embeddedQuery() { return []; } };"
                    .to_owned(),
                export: "embeddedQuery".to_owned(),
            }),
        )],
        ..FunctionManifest::default()
    };
    for generation in 1..=2 {
        let diagnostics = snapback.load_functions(manifest.clone());
        assert_eq!(
            diagnostics
                .iter()
                .map(|diagnostic| diagnostic.code.as_str())
                .collect::<Vec<_>>(),
            vec!["SNAPBACK_IBEX_FUNCTIONS_LOADED"],
            "generation {generation} should report only the positive embedded load event"
        );
    }

    let inspected = snapback.inspect().expect("inspect loaded generations");
    assert!(!inspected.runtime.ibex_cli.available);
    assert!(
        inspected
            .recent_diagnostics
            .iter()
            .all(|diagnostic| { diagnostic.code != "SNAPBACK_IBEX_CLI_UNAVAILABLE" })
    );
    assert_eq!(
        inspected
            .recent_diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.code == "SNAPBACK_IBEX_FUNCTIONS_LOADED")
            .count(),
        2,
        "repeated real generation events remain distinct occurrences"
    );
}

/// Cross-seam capability-manifest parity
/// (issues/20260729-centralize-served-capability-manifest-composition.md):
/// the inspect seam and the RQS generation-identity seam must serve one
/// composition — the shared instance constructor plus the warm-VM
/// lifecycle override — for the same instance state. The generation seam
/// is checked by recomposing the digest from the inspect-served manifest
/// with the same non-capability components; a manifest divergence between
/// the seams breaks the digest equality.
#[test]
fn capability_manifest_is_identical_across_inspect_and_generation_seams() {
    let mut snapback = LocalSnapback::memory().expect("memory snapback");
    let inspected = snapback
        .inspect_core()
        .expect("inspect")
        .capability_manifest;
    // Both reporting seams reduce to the one helper composition.
    assert_eq!(
        inspected,
        snapback.served_capability_manifest(snapback.capability_gaps())
    );
    // Admission seams (preflight, ordinary function loading) compose the
    // same constructor from the same live facts: capability support must
    // match what inspect reports.
    let admission = crate::manifest::CapabilityManifest::local_v0_instance(
        snapback.capability_gaps(),
        crate::runtime::outbound_actions_enabled(),
    );
    assert_eq!(
        admission.supported_capabilities,
        inspected.supported_capabilities
    );
    // Generation seam: rebuild the digest from the inspect-served
    // manifest and the seam's other components; equality proves the
    // generation identity embeds exactly the manifest inspect serves.
    let digest = snapback.rqs_generation_digest().expect("generation digest");
    let capability_identity = crate::rqs_contract::sha256_identity(
        &serde_json::to_value(&inspected).expect("manifest serializes"),
    )
    .expect("capability identity");
    let functions_identity = crate::rqs_contract::sha256_identity(
        &serde_json::to_value(&snapback.functions).expect("functions serialize"),
    )
    .expect("functions identity");
    let schema_identity = snapback
        .db
        .schema()
        .schema_hash
        .clone()
        .unwrap_or_else(|| "absent".to_owned());
    let route_manifest_hash = snapback
        .routes_manifest_hash
        .clone()
        .unwrap_or_else(|| "absent".to_owned());
    let auth_mode = snapback.db.auth_mode_snapshot().expect("auth mode");
    let resume_config = crate::rqs::resume_config_identity(
        "caller-supplied-v0",
        auth_mode.state.active.as_str(),
        &route_manifest_hash,
    );
    let expected = crate::rqs::generation_digest(
        &format!("local:{}", env!("CARGO_PKG_VERSION")),
        &schema_identity,
        &functions_identity,
        &capability_identity,
        &resume_config,
    );
    assert_eq!(digest, expected);
}

#[test]
fn agent_safe_app_effective_envelopes_intersect_exact_function_reachability() {
    let mut snapback = LocalSnapback::memory().expect("memory publication projection");
    snapback
        .activate_agent_safe_operation_coverage(1)
        .expect("activate exact coverage");
    let candidate_manifest = || {
        let mut manifest = CapabilityManifest::local_v0_declared();
        manifest
            .supported_capabilities
            .push(crate::manifest::TargetCapabilityId::AgentSafeStorageV1);
        manifest.agent_safe.target = crate::agent_safe_publication::storage_target_candidate();
        manifest
    };

    let mut empty = candidate_manifest();
    snapback.project_agent_safe_app_effective(&mut empty);
    assert_eq!(
        empty.agent_safe.app_effective,
        crate::manifest::AgentSafeCapabilityFactsV1::missing(),
        "active coverage without a current mutation artifact stays Missing"
    );

    let host = FunctionDefinition::new(
        "hostMutation",
        FunctionKind::Mutation,
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(MutationPlan {
            owner_write_checks: Vec::new(),
            steps: Vec::new(),
            return_value: None,
        })),
    );
    let ibex = FunctionDefinition::new(
        "ibexMutation",
        FunctionKind::Mutation,
        FunctionRuntime::IbexModule(crate::manifest::IbexModule {
            source: "export function ibexMutation() {}".to_owned(),
            export: "ibexMutation".to_owned(),
        }),
    );
    let host_action = FunctionDefinition::new(
        "action",
        FunctionKind::Action,
        FunctionRuntime::HostPlan(HandlerPlan::Action(ActionPlan {
            steps: vec![
                ActionStep::RunMutation {
                    name: "hostMutation".to_owned(),
                    args: BTreeMap::new(),
                    bind_result_as: None,
                },
                ActionStep::RunMutation {
                    name: "ibexMutation".to_owned(),
                    args: BTreeMap::new(),
                    bind_result_as: None,
                },
            ],
            return_value: None,
        })),
    );
    snapback.functions.functions = vec![host, ibex, host_action];
    let mut reached = candidate_manifest();
    snapback.project_agent_safe_app_effective(&mut reached);
    let envelope = reached.agent_safe.app_effective.envelope;
    assert_eq!(
        envelope.ordinary_mutation.host_plan,
        crate::manifest::AgentSafeEnvelopeCoverageV1::Covered
    );
    assert_eq!(
        envelope.ordinary_mutation.ibex_buffered,
        crate::manifest::AgentSafeEnvelopeCoverageV1::Covered
    );
    assert_eq!(
        envelope.host_child_mutation.host_plan,
        crate::manifest::AgentSafeEnvelopeCoverageV1::Covered
    );
    assert_eq!(
        envelope.host_child_mutation.ibex_buffered,
        crate::manifest::AgentSafeEnvelopeCoverageV1::Covered
    );
    assert_eq!(
        reached
            .agent_safe
            .app_effective
            .forks
            .derived_deployment
            .egress,
        crate::manifest::AgentSafeForkEgressV1::Missing,
        "derived appEffective is canonical Missing"
    );
}

