#[test]
fn asset_host_plan_and_seed_derive_admission_from_the_restriction() {
    let mut snapback = asset_reference_snapback();
    let asset_id = asset_ready(&mut snapback, "user_a", b"plan-bytes");
    let plan_insert = |table: &str, field: &str, asset: &str| MutationPlan {
        owner_write_checks: Vec::new(),
        steps: vec![MutationStep::Insert {
            table: table.to_owned(),
            values: BTreeMap::from([
                (field.to_owned(), ValueExpr::Literal(json!(asset))),
                ("rowOwner".to_owned(), ValueExpr::AuthUserId),
            ]),
            bind_id_as: None,
        }],
        return_value: None,
    };
    let input_for = |user: &str| HandlerInput {
        auth: crate::manifest::AuthInput {
            user_id: Some(user.to_owned()),
            ..Default::default()
        },
        ..Default::default()
    };
    // Restricted field: the commit boundary derives the full admission.
    snapback
        .db
        .mutation_writes()
        .execute_mutation(
            &plan_insert("posts", "photo", &asset_id),
            &input_for("user_a"),
        )
        .expect("host plan with restriction commits");
    // Wrong owner fails closed.
    let error = snapback
        .db
        .mutation_writes()
        .execute_mutation(
            &plan_insert("posts", "photo", &asset_id),
            &input_for("user_b"),
        )
        .expect_err("foreign host plan refuses");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    // A restriction-less field is handler-attach-only on host plans.
    let error = snapback
        .db
        .mutation_writes()
        .execute_mutation(
            &plan_insert("drafts", "pic", &asset_id),
            &input_for("user_a"),
        )
        .expect_err("unrestricted host plan refuses");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_REF_UNVERIFIED");
    // Seeds run the same commit-boundary admission under system
    // authority: the restricted field admits, the unrestricted refuses.
    snapback
        .db
        .schema_seed()
        .seed(SeedData {
            tables: BTreeMap::from([(
                "posts".to_owned(),
                vec![serde_json::Map::from_iter([
                    ("title".to_owned(), json!("seeded")),
                    ("photo".to_owned(), json!(asset_id)),
                    ("rowOwner".to_owned(), json!("user_a")),
                ])],
            )]),
        })
        .expect("seed with restriction commits");
    let error = snapback
        .db
        .schema_seed()
        .seed(SeedData {
            tables: BTreeMap::from([(
                "drafts".to_owned(),
                vec![serde_json::Map::from_iter([
                    ("pic".to_owned(), json!(asset_id)),
                    ("rowOwner".to_owned(), json!("user_a")),
                ])],
            )]),
        })
        .expect_err("unrestricted seed refuses");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_REF_UNVERIFIED");
}

#[test]
fn asset_edges_follow_patch_clear_and_row_delete_in_the_same_changeset() {
    let mut snapback = asset_reference_snapback();
    let first = asset_ready(&mut snapback, "user_a", b"first-bytes");
    let second = asset_ready(&mut snapback, "user_a", b"second-bytes");
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_e".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(first))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: first.clone(),
            upload: None,
        }],
    )
    .expect("insert attaches");
    // Change: the old edge is removed and the new one committed together.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Patch {
            table: "posts".to_owned(),
            id: "post_e".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(second))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: second.clone(),
            upload: None,
        }],
    )
    .expect("patch re-attaches");
    let edges = asset_edges(&mut snapback, "posts", "post_e");
    assert_eq!(edges.len(), 1);
    assert_eq!(edges[0].asset_id, second);
    assert!(asset_receipt_events(&mut snapback, &first).contains(&"reference-removed".to_owned()));
    // Clear: writing null removes the edge with no new admission needed.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Patch {
            table: "posts".to_owned(),
            id: "post_e".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), Value::Null)]),
        }],
        Vec::new(),
    )
    .expect("clear commits");
    assert!(asset_edges(&mut snapback, "posts", "post_e").is_empty());
    // Row delete removes every edge for the row.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_f".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(second))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: second.clone(),
            upload: None,
        }],
    )
    .expect("insert attaches");
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Delete {
            table: "posts".to_owned(),
            id: "post_f".to_owned(),
        }],
        Vec::new(),
    )
    .expect("delete commits");
    assert!(asset_edges(&mut snapback, "posts", "post_f").is_empty());
}

fn asset_shared_intent() -> crate::manifest::AssetUploadIntentDefinition {
    let mut intent = asset_test_intent();
    intent.access = crate::manifest::AssetAccessPolicy {
        read: crate::assets::AssetReadAccessPolicy::ViaReferences,
    };
    intent
}

#[test]
fn asset_read_authorization_decides_only_through_sharing_declarations() {
    let mut snapback = asset_reference_snapback();
    snapback.load_functions(FunctionManifest {
        asset_upload_intents: vec![asset_shared_intent()],
        ..FunctionManifest::default()
    });
    let asset_id = asset_ready(&mut snapback, "user_a", b"shared-bytes");
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let outsider = asset_dev_authority(&snapback, "user_b", InvocationSource::HttpQuery);
    // Unreferenced: readable only by its owner, even under via-references.
    snapback
        .asset_record_inspect(&owner, &asset_id)
        .expect("owner reads");
    let error = snapback
        .asset_record_inspect(&outsider, &asset_id)
        .expect_err("unreferenced asset denies the outsider");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    // A reference on the mixed-table stand-in (no sharing declaration)
    // confers nothing, however visible its rows may otherwise be.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "drafts".to_owned(),
            id: "draft_1".to_owned(),
            values: serde_json::Map::from_iter([("pic".to_owned(), json!(asset_id))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: None,
        }],
    )
    .expect("handler attach into the undeclared table commits");
    let error = snapback
        .asset_record_inspect(&outsider, &asset_id)
        .expect_err("no sharing declaration = no bypass");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    // A public-read-shared reference grants with the edge commit and
    // revokes with its removal.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_s".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: None,
        }],
    )
    .expect("shared attach commits");
    snapback
        .asset_record_inspect(&outsider, &asset_id)
        .expect("grant arrives with the edge commit");
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Delete {
            table: "posts".to_owned(),
            id: "post_s".to_owned(),
        }],
        Vec::new(),
    )
    .expect("detach commits");
    let error = snapback
        .asset_record_inspect(&outsider, &asset_id)
        .expect_err("revoke arrives with the edge removal");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    // Owner-field sharing admits exactly the row's owner-field principal.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "owned".to_owned(),
            id: "owned_1".to_owned(),
            values: serde_json::Map::from_iter([
                ("ownerId".to_owned(), json!("user_b")),
                ("photo".to_owned(), json!(asset_id)),
            ]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: None,
        }],
    )
    .expect("owner-field attach commits");
    snapback
        .asset_record_inspect(&outsider, &asset_id)
        .expect("the owner-field principal reads");
    let stranger = asset_dev_authority(&snapback, "user_c", InvocationSource::HttpQuery);
    let error = snapback
        .asset_record_inspect(&stranger, &asset_id)
        .expect_err("a third principal stays denied");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
}

#[test]
fn asset_read_decision_pins_the_empty_edge_range_so_first_attachment_moves_it() {
    let mut snapback = asset_reference_snapback();
    snapback.load_functions(FunctionManifest {
        asset_upload_intents: vec![asset_shared_intent()],
        ..FunctionManifest::default()
    });
    let asset_id = asset_ready(&mut snapback, "user_a", b"wake-bytes");
    let schema = snapback.db.schema().clone();
    let captured = snapback
        .db
        .asset_reads()
        .read_decision_dependencies(&schema, Some("user_b"), &asset_id)
        .expect("decision");
    // The empty reverse-edge range is a first-class captured dependency.
    assert!(captured.iter().any(|dependency| {
        dependency.result_count == Some(0)
            && dependency.table.as_deref() == Some("_snapback_asset_reference_edges_v1")
    }));
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_w".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: None,
        }],
    )
    .expect("first attachment commits");
    let schema = snapback.db.schema().clone();
    let moved = snapback
        .db
        .asset_reads()
        .read_dependencies_moved(&schema, Some("user_b"), &asset_id, &captured)
        .expect("re-evaluation");
    assert!(
        moved,
        "the first attachment must move the pinned empty capture"
    );
}

#[test]
fn asset_membership_read_captures_ordinary_query_and_never_permission() {
    let mut snapback = asset_reference_snapback();
    snapback.load_functions(FunctionManifest {
        asset_upload_intents: vec![asset_shared_intent()],
        ..FunctionManifest::default()
    });
    let asset_id = asset_ready(&mut snapback, "user_a", b"membership-shared");
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "workspaces".to_owned(),
            id: "workspace_1".to_owned(),
            values: serde_json::Map::from_iter([("title".to_owned(), json!("One"))]),
        }],
        Vec::new(),
    )
    .expect("workspace commits");
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "workspace_files".to_owned(),
            id: "workspace_file_1".to_owned(),
            values: serde_json::Map::from_iter([
                ("workspaceId".to_owned(), json!("workspace_1")),
                ("photo".to_owned(), json!(asset_id.clone())),
            ]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: Some("avatarUpload".to_owned()),
        }],
    )
    .expect("membership-shared attachment commits");

    let schema = snapback.db.schema().clone();
    let captured = snapback
        .db
        .asset_reads()
        .read_decision_dependencies(&schema, Some("user_b"), &asset_id)
        .expect("denied membership decision captures its probe");
    assert!(
        captured
            .iter()
            .all(|dependency| dependency.kind != crate::storage::CapturedReadKind::Permission),
        "asset authorization must never emit the matcher/validator-dead Permission kind"
    );
    let membership = captured
        .iter()
        .find(|dependency| {
            dependency.kind == crate::storage::CapturedReadKind::Query
                && dependency.table.as_deref() == Some("workspace_members")
        })
        .expect("ordinary membership Query capture");
    assert_eq!(
        membership.result_count,
        Some(0),
        "empty-result probe is pinned"
    );
    let plan: QueryPlan = serde_json::from_value(
        membership
            .predicate
            .clone()
            .expect("membership Query carries its plan"),
    )
    .expect("membership predicate is a QueryPlan");
    assert_eq!(
        plan.filters
            .iter()
            .map(|filter| filter.field.as_str())
            .collect::<Vec<_>>(),
        vec!["userId", "workspaceId", "role"],
        "the capture binds principal, resource, and admitted roles"
    );
}

fn asset_live_input(connection_id: &str, user: &str, asset_id: &str) -> LiveSubscribeInput {
    LiveSubscribeInput {
        connection_id: connection_id.to_owned(),
        input: HandlerInput {
            args: json!({ "assetId": asset_id }),
            auth: crate::manifest::AuthInput {
                user_id: Some(user.to_owned()),
                ..crate::manifest::AuthInput::default()
            },
            ..HandlerInput::default()
        },
        authorization_namespace: None,
        supersedes: None,
        resume_from_token: None,
    }
}

fn asset_last_replace_rows(snapback: &mut LocalSnapback, connection_id: &str) -> Vec<Value> {
    let frames = rqs_drained_envelopes(snapback, connection_id);
    let replace = frames
        .iter()
        .rev()
        .find(|frame| frame["kind"] == "live_replace")
        .unwrap_or_else(|| panic!("no live_replace frame for {connection_id}: {frames:?}"));
    replace["rows"].as_array().cloned().unwrap_or_default()
}

#[test]
fn asset_record_live_projection_publishes_wakes_and_blanks_with_no_polling() {
    let mut snapback = asset_reference_snapback();
    snapback.load_functions(FunctionManifest {
        asset_upload_intents: vec![asset_shared_intent()],
        ..FunctionManifest::default()
    });
    // The owner subscribes to a pending asset and holds the pending row.
    let created = asset_upload(&mut snapback, "user_a", b"live-bytes", true);
    let asset_id = created.task.asset_id.clone();
    let attempt_id = created.task.attempt_id.clone();
    let established = snapback
        .subscribe_live(
            ASSET_RECORD_LIVE_FUNCTION,
            asset_live_input("conn-owner", "user_a", &asset_id),
        )
        .expect("owner subscribes to the reserved projection");
    let snapshot = established.snapshot.expect("initial rows");
    assert_eq!(snapshot.rows.len(), 1);
    assert_eq!(snapshot.rows[0]["availability"], "pending");
    assert!(established.resume.is_none(), "never RQS-eligible");

    // Publish: the durable transition reaches the subscriber with no
    // polling — the finalize itself fans out the frame.
    asset_finalize(&mut snapback, "user_a", &attempt_id, None).expect("publishes");
    let rows = asset_last_replace_rows(&mut snapback, "conn-owner");
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0]["availability"], "ready");

    // An outsider's subscription establishes blank (owner-only through
    // no edge), then the FIRST attachment wakes it — the pinned
    // empty-range capture moving through an ordinary app commit.
    let outsider = snapback
        .subscribe_live(
            ASSET_RECORD_LIVE_FUNCTION,
            asset_live_input("conn-b", "user_b", &asset_id),
        )
        .expect("outsider subscribes");
    assert_eq!(
        outsider.snapshot.expect("blank rows").rows.len(),
        0,
        "unreferenced assets blank for non-owners"
    );
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_live".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), json!(asset_id))]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: None,
        }],
    )
    .expect("first attachment commits");
    let rows = asset_last_replace_rows(&mut snapback, "conn-b");
    assert_eq!(rows.len(), 1, "the attachment wakes the blank subscriber");
    assert_eq!(rows[0]["availability"], "ready");

    // Revocation: removing the referencing row blanks the outsider at
    // the governed boundary, while the owner's view stays intact.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Delete {
            table: "posts".to_owned(),
            id: "post_live".to_owned(),
        }],
        Vec::new(),
    )
    .expect("detach commits");
    let rows = asset_last_replace_rows(&mut snapback, "conn-b");
    assert_eq!(rows.len(), 0, "edge removal blanks the live view");

    // Deletion blanks the owner too.
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    snapback.asset_delete(&owner, &asset_id).expect("delete");
    let rows = asset_last_replace_rows(&mut snapback, "conn-owner");
    assert_eq!(rows.len(), 0, "deletion blanks the record projection");
}

#[test]
fn asset_grant_commit_wakes_and_revoke_blanks_live_projection() {
    let mut snapback = asset_grant_snapback();
    let asset_id = asset_ready(&mut snapback, "owner", b"grant-live");
    let outsider = snapback
        .subscribe_live(
            ASSET_RECORD_LIVE_FUNCTION,
            asset_live_input("conn-grant", "recipient", &asset_id),
        )
        .expect("recipient subscribes blank");
    assert_eq!(outsider.snapshot.expect("initial rows").rows.len(), 0);
    let granted = invoke_asset_grant_mutation(
        &mut snapback,
        "grantAsset",
        "owner",
        json!({ "assetId": asset_id, "principal": "recipient", "state": "active" }),
    )
    .expect("grant commits");
    assert_eq!(
        asset_last_replace_rows(&mut snapback, "conn-grant").len(),
        1,
        "grant-only commit wakes the live projection"
    );
    invoke_asset_grant_mutation(
        &mut snapback,
        "revokeGrant",
        "owner",
        json!({ "grantId": granted.result["grantId"] }),
    )
    .expect("revoke commits");
    assert_eq!(
        asset_last_replace_rows(&mut snapback, "conn-grant").len(),
        0,
        "revoke publishes an empty replacement instead of leaving stale authority"
    );
}

/// LLP 0100 receipt witness: the removed member's `_snapback.myMemberships`
/// subscription drops the seat at the same authorization cut the
/// principal-addressed removal commits — the product-visible coherence of
/// one cut (0056's machinery, driven here by the NEW addressing mode
/// end to end through an authored JS mutation), while the absent-target
/// no-op delivers nothing.
#[test]
fn remove_principal_drops_the_seat_from_my_memberships_at_the_cut() {
    let mut snapback = my_memberships_snapback_with_removal();
    seed_membership_row(&mut snapback, "seat_owner", "chan1", "user_a", "owner");
    seed_membership_row(&mut snapback, "seat_b", "chan1", "user_b", "member");
    // Advance the storage head past the seeded row versions so the
    // membership planners' managed-version validation sees a
    // committed-history-consistent table.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "notes".to_owned(),
            id: "note_seed".to_owned(),
            values: serde_json::Map::from_iter([("body".to_owned(), json!("advance head"))]),
        }],
        Vec::new(),
    )
    .expect("head-advancing commit");

    let b = snapback
        .subscribe_live(
            MY_MEMBERSHIPS_LIVE_FUNCTION,
            memberships_live_input("conn-b", Some("user_b")),
        )
        .expect("target subscribes");
    assert_eq!(b.snapshot.expect("rows").rows.len(), 1, "one seat before");

    // The owner removes user_b through the principal-addressed command.
    let output = snapback
        .invoke_mutation(
            "ownerRemove",
            HandlerInput {
                args: json!({ "channelId": "chan1", "principal": "user_b" }),
                auth: crate::manifest::AuthInput {
                    user_id: Some("user_a".to_owned()),
                    principal: Some("user_a".to_owned()),
                    ..crate::manifest::AuthInput::default()
                },
                ..HandlerInput::default()
            },
        )
        .expect("owner removes member");
    assert_eq!(output.result, Value::Null, "the public result is null");

    let rows = asset_last_replace_rows(&mut snapback, "conn-b");
    assert_eq!(
        rows.len(),
        0,
        "the seat drops from myMemberships at the removal cut"
    );

    // The absent-target no-op delivers nothing further to the target.
    snapback
        .invoke_mutation(
            "ownerRemove",
            HandlerInput {
                args: json!({ "channelId": "chan1", "principal": "user_b" }),
                auth: crate::manifest::AuthInput {
                    user_id: Some("user_a".to_owned()),
                    principal: Some("user_a".to_owned()),
                    ..crate::manifest::AuthInput::default()
                },
                ..HandlerInput::default()
            },
        )
        .expect("absent-target no-op");
    let frames = rqs_drained_envelopes(&mut snapback, "conn-b");
    assert!(
        frames.iter().all(|frame| frame["kind"] != "live_replace"),
        "the no-op delivers no seat change: {frames:?}"
    );
}

/// The myMemberships fixture plus the LLP 0100 opt-in and an authored
/// removal mutation over the real ctx.membership bridge.
fn my_memberships_snapback_with_removal() -> LocalSnapback {
    let mut snapback = my_memberships_snapback();
    let schema_patch = {
        let mut schema = snapback.db.schema().clone();
        let membership = schema
            .tables
            .iter_mut()
            .find(|table| table.name == "channel_members")
            .and_then(|table| table.membership.as_mut())
            .expect("membership declaration");
        membership
            .transitions
            .push(crate::manifest::MembershipTransition {
                op: crate::manifest::MembershipOp::Remove,
                by: vec!["owner".to_owned()],
                target: crate::manifest::MembershipTarget::Other,
                from: None,
                to: None,
                fields: None,
            });
        membership.principal_addressed_writes =
            Some(crate::manifest::MembershipPrincipalAddressedWrites { remove: true });
        schema
    };
    snapback
        .db
        .schema_seed()
        .apply_schema(schema_patch)
        .expect("apply removal opt-in");
    let mut function = FunctionDefinition::new(
        "ownerRemove",
        FunctionKind::Mutation,
        FunctionRuntime::IbexModule(IbexModule {
            source: "globalThis.__snapbackHandlers = {\
                     async ownerRemove(ctx, args) {\
                       return await ctx.membership.channelSeats.removePrincipal(\
                         args.channelId, args.principal);\
                     } };"
                .to_owned(),
            export: "ownerRemove".to_owned(),
        }),
    );
    function.auth_requirement = Some(crate::manifest::AuthRequirement::Authenticated);
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![function],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "removal fixture must install: {diagnostics:?}"
    );
    snapback
}

