fn asset_primary_rendition(
    snapback: &mut LocalSnapback,
    asset_id: &str,
) -> crate::assets::AssetRenditionRecordV1 {
    snapback
        .db
        .asset_reads()
        .load_rendition_by_variant(asset_id, crate::assets::ASSET_RENDITION_PRIMARY)
        .expect("rendition")
        .expect("primary rendition")
}

/// The client record view (inspect + live projection) exposes rendition
/// summaries and the primary's media facts — the Lane-1 gap: without
/// them a client cannot obtain the ThumbHash the renderer ladder shows.
#[test]
fn asset_record_view_exposes_renditions_and_media_facts() {
    let fixture = crate::assets_image::fixtures::jpeg_with_gps_exif(48, 32, 6);
    let mut snapback = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, 64 * 1024);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("strip publishes");

    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let view = snapback
        .asset_record_inspect(&authority, &created.task.asset_id)
        .expect("authorized inspect");
    let renditions = view["renditions"].as_array().expect("rendition summaries");
    assert!(
        renditions.iter().any(|summary| {
            summary["variant"] == "primary"
                && summary["ready"] == true
                && summary["width"].as_u64() == Some(32)
                && summary["height"].as_u64() == Some(48)
        }),
        "primary summary with dimensions: {renditions:?}"
    );
    assert_eq!(view["media"]["placeholder"]["algo"], "thumbhash.v1");
    assert_eq!(view["media"]["mediaType"], "image/jpeg");
    assert!(
        view["media"]["dominantColor"]
            .as_str()
            .expect("dominant color")
            .starts_with('#')
    );
    // Never the physical side: no blob keys or staging identifiers.
    assert!(view.get("physicalKey").is_none());
    assert!(view["media"].get("stagingKey").is_none());
    // App-queryable integrity facts (LLP 0139 steal): digest + algorithm
    // + honest grade, on the asset projection of the inspect payload.
    let digest = view["digest"].as_str().expect("canonical digest");
    assert_eq!(digest.len(), 64, "raw lowercase-hex sha256: {digest}");
    assert_eq!(view["digestAlgorithm"], "sha256");
    assert_eq!(
        view["integrityGrade"],
        serde_json::to_value(crate::assets::AssetIntegrityGrade::EndToEndVerified)
            .expect("grade encodes"),
    );
}

/// A rendition landing moves the projection's delivery fingerprint even
/// though the asset row is unchanged — a subscriber hears about the
/// ThumbHash without polling.
#[test]
fn asset_record_projection_fingerprint_moves_when_renditions_land() {
    let fixture = crate::assets_image::fixtures::jpeg_with_gps_exif(48, 32, 6);
    let mut snapback = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, 64 * 1024);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);

    let fingerprint = |deps: &[crate::storage::CapturedReadDependency]| {
        deps.iter()
            .find(|dep| {
                dep.kind == crate::storage::CapturedReadKind::Row
                    && dep.table.as_deref() == Some(super::ASSET_RECORDS_LIVE_TABLE)
            })
            .and_then(|dep| dep.value.clone())
            .expect("synthetic record dependency")
    };
    let (pending_rows, pending_deps) = snapback
        .asset_record_projection(Some("user_a"), &created.task.asset_id)
        .expect("pending projection");
    assert_eq!(pending_rows.len(), 1, "owner sees the pending record");
    assert_eq!(
        pending_rows[0]["renditions"].as_array().map(Vec::len),
        Some(0),
        "no renditions before finalization"
    );

    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("strip publishes");
    let (ready_rows, ready_deps) = snapback
        .asset_record_projection(Some("user_a"), &created.task.asset_id)
        .expect("ready projection");
    assert_eq!(ready_rows.len(), 1);
    assert_eq!(
        ready_rows[0]["media"]["placeholder"]["algo"],
        "thumbhash.v1"
    );
    assert_ne!(
        fingerprint(&pending_deps),
        fingerprint(&ready_deps),
        "the rendition arrival moves the delivery fingerprint"
    );
}

#[test]
fn asset_finalize_strip_publishes_canonical_without_gps() {
    let fixture = crate::assets_image::fixtures::jpeg_with_gps_exif(48, 32, 6);
    let mut snapback = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, 64 * 1024);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("strip publishes");

    let rendition = asset_primary_rendition(&mut snapback, &created.task.asset_id);
    let facts = rendition.media_facts.clone().expect("media facts");
    assert_eq!(facts["locationPolicy"], "strip");
    assert_eq!(facts["orientationApplied"], 6);
    assert!(facts["capturedAt"].as_str().unwrap().contains("2026"));
    // Orientation 6 swaps the axes.
    assert_eq!(
        (facts["width"].as_u64(), facts["height"].as_u64()),
        (Some(32), Some(48))
    );
    assert_eq!(facts["placeholder"]["algo"], "thumbhash.v1");
    assert!(!facts["placeholder"]["value"].as_str().unwrap().is_empty());
    assert!(facts["dominantColor"].as_str().unwrap().starts_with('#'));

    let blob = snapback
        .db
        .asset_reads()
        .load_blob(&rendition.blob_id)
        .expect("blob");
    let blob = blob.expect("blob");
    let store = snapback.asset_store().expect("store");
    let canonical_bytes = std::fs::read(store.blob_path(&blob.physical_key).expect("blob path"))
        .expect("canonical object");
    assert_eq!(
        blob.canonicalization_policy,
        crate::assets::ASSET_CANONICALIZATION_STRIP_IMAGE_V1
    );
    assert_eq!(blob.byte_length as usize, canonical_bytes.len());
    // No EXIF survives in the deliverable canonical bytes.
    let stripped = crate::assets_image::extract_safe_exif(&canonical_bytes);
    assert_eq!(stripped.orientation, None);
    assert_eq!(stripped.captured_at, None);
    assert!(
        !canonical_bytes
            .windows(2)
            .any(|window| window == [0xFF, 0xE1]),
        "no APP1 segment in the canonical object"
    );
}

#[test]
fn asset_finalize_strip_vs_retain_blobs_differ_and_strip_dedups() {
    let fixture = crate::assets_image::fixtures::jpeg_with_gps_exif(24, 24, 1);

    let mut strip = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, 64 * 1024);
    let first = asset_upload(&mut strip, "user_a", &fixture, true);
    asset_finalize(&mut strip, "user_a", &first.task.attempt_id, None)
        .expect("first strip publishes");
    let second = asset_upload(&mut strip, "user_a", &fixture, true);
    asset_finalize(&mut strip, "user_a", &second.task.attempt_id, None)
        .expect("second strip publishes");
    let first_rendition = asset_primary_rendition(&mut strip, &first.task.asset_id);
    let second_rendition = asset_primary_rendition(&mut strip, &second.task.asset_id);
    assert_eq!(
        first_rendition.blob_id, second_rendition.blob_id,
        "strip dedups with strip: one canonical blob, two assets"
    );

    let mut retain = asset_image_snapback(crate::manifest::AssetLocationPolicy::Retain, 64 * 1024);
    let kept = asset_upload(&mut retain, "user_a", &fixture, true);
    asset_finalize(&mut retain, "user_a", &kept.task.attempt_id, None).expect("retain publishes");
    let kept_rendition = asset_primary_rendition(&mut retain, &kept.task.asset_id);
    let kept_blob = retain
        .db
        .asset_reads()
        .load_blob(&kept_rendition.blob_id)
        .expect("blob")
        .expect("blob");
    let strip_blob = strip
        .db
        .asset_reads()
        .load_blob(&first_rendition.blob_id)
        .expect("blob")
        .expect("blob");
    assert_eq!(
        kept_blob.canonicalization_policy,
        crate::assets::ASSET_CANONICALIZATION_NONE
    );
    assert_ne!(
        kept_blob.digest, strip_blob.digest,
        "strip and retain of one source can never alias"
    );
    let facts = kept_rendition.media_facts.expect("media facts");
    assert_eq!(facts["locationPolicy"], "retain");
    // The retain path still derives display facts from a bounded decode:
    // post-orientation dimensions, the versioned placeholder, dominant
    // color — the pipeline claim covers both location policies.
    assert_eq!(
        (facts["width"].as_u64(), facts["height"].as_u64()),
        (Some(24), Some(24))
    );
    assert_eq!(facts["placeholder"]["algo"], "thumbhash.v1");
    assert!(facts["dominantColor"].as_str().unwrap().starts_with('#'));
    // Retain evidence reaches the receipts too.
    let receipts = retain
        .db
        .asset_reads()
        .receipts_for_asset(&kept.task.asset_id, 64)
        .expect("receipts");
    assert!(receipts.iter().any(|receipt| {
        receipt.event == crate::assets::AssetReceiptEventV1::AssetReady
            && receipt.details["locationPolicy"] == "retain"
    }));
}

