#[test]
fn asset_finalize_strip_video_refuses_without_capability_or_classification() {
    // Defense in depth on a target without the video fact: even a
    // hand-built manifest cannot publish strip-declared video bytes.
    let mut snapback = LocalSnapback::memory().expect("memory snapback");
    snapback.set_asset_video_finalization_override(false);
    snapback.load_functions(FunctionManifest {
        asset_upload_intents: vec![asset_video_intent(
            crate::manifest::AssetLocationPolicy::Strip,
        )],
        ..FunctionManifest::default()
    });
    let fixture = crate::assets_video::fixtures::mp4_with_gps();
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    let error = asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect_err("strip-declared video cannot publish without the fact");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_ASSET_LOCATION_POLICY_UNSUPPORTED"
    );

    // Unclassifiable metadata refuses under strip — fail closed, never
    // silently retain — and rejects the asset deterministically.
    let mut snapback = asset_video_snapback(crate::manifest::AssetLocationPolicy::Strip);
    let mut unknown_payload = [0x11u8; 16].to_vec();
    unknown_payload.extend_from_slice(b"vendor mystery");
    let hostile = [
        crate::assets_video::fixtures::ftyp(),
        crate::assets_video::fixtures::boxed(b"uuid", &unknown_payload),
    ]
    .concat();
    let created = asset_upload(&mut snapback, "user_a", &hostile, true);
    let error = asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect_err("unclassifiable container refuses under strip");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_ASSET_VIDEO_STRIP_UNSUPPORTED"
    );
    let asset = snapback
        .db
        .asset_reads()
        .require_asset(&created.task.asset_id)
        .expect("asset");
    assert_eq!(
        asset.availability,
        crate::assets::AssetAvailability::Rejected
    );
}

#[test]
fn asset_finalize_strip_expansion_refuses() {
    // A low-quality source re-encodes at canonical quality to more
    // bytes than it arrived with; a bound between the two admits the
    // upload and refuses the canonical expansion.
    let source = crate::assets_image::fixtures::plain_jpeg_quality(64, 64, 10);
    let canonical = crate::assets_image::canonicalize_strip(
        &source,
        "image/jpeg",
        &crate::assets_image::ASSET_IMAGE_CEILINGS_LOCAL_V1,
    )
    .expect("fixture canonicalizes");
    assert!(
        canonical.canonical.len() > source.len(),
        "fixture must expand: {} -> {}",
        source.len(),
        canonical.canonical.len()
    );
    let bound = (source.len() + 1) as u64;
    let mut snapback = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, bound);
    let created = asset_upload(&mut snapback, "user_a", &source, true);
    let error = asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect_err("expansion refuses");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_ASSET_MEDIA_BOUNDS_EXCEEDED"
    );
}

#[test]
fn asset_finalize_strip_hostile_and_unsupported_reject_the_asset() {
    // Truncated image bytes: deterministic decode failure → rejected.
    let fixture = crate::assets_image::fixtures::plain_jpeg(32, 32);
    let truncated = &fixture[..fixture.len() / 2];
    let mut snapback = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, 64 * 1024);
    let created = asset_upload(&mut snapback, "user_a", truncated, true);
    let error = asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect_err("hostile bytes reject");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_IMAGE_DECODE_FAILED");
    let asset = snapback
        .db
        .asset_reads()
        .require_asset(&created.task.asset_id)
        .expect("asset");
    assert_eq!(
        asset.availability,
        crate::assets::AssetAvailability::Rejected
    );

    // A format with no strip canonicalization: structurally refused.
    let gif = b"GIF89a\x01\x00\x01\x00\x00\x00\x00;";
    let mut snapback = asset_image_snapback(crate::manifest::AssetLocationPolicy::Strip, 64 * 1024);
    let created = asset_upload(&mut snapback, "user_a", gif, true);
    let error = asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect_err("gif strip unsupported");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_ASSET_LOCATION_POLICY_UNSUPPORTED"
    );
}

#[test]
fn asset_finalize_crash_cuts_recover_via_publication_records() {
    let mut snapback = asset_test_snapback();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // Cut 1 — after `planned`, before the object put: the record is
    // re-drivable while its attempt stays current, and a re-driven
    // finalize completes from the same record.
    let created = asset_upload(&mut snapback, "user_a", b"cut-one", true);
    let error = snapback
        .asset_attempt_finalize_inner(
            &authority,
            crate::assets::AssetFinalizeRequestV1 {
                attempt_id: created.task.attempt_id.clone(),
                lifecycle_generation: 1,
                declared_digest: None,
            },
            Some(AssetFinalizeCrashPoint::AfterPlanned),
        )
        .expect_err("injected crash");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_TEST_CRASH");
    let report = snapback
        .asset_publication_maintain(now_millis())
        .expect("maintain");
    assert_eq!(report.condemned, 0, "a re-drivable planned record survives");
    let response = asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("re-drive completes from the planned record");
    assert_eq!(
        response.task.availability,
        crate::assets::AssetAvailability::Ready
    );

    // Cut 2 — after the acknowledged object put, before `staged`: the
    // attempt dies; recovery stages the verified object, condemns the
    // dead work, deletes the object, and retires the record in one pass.
    let created = asset_upload(&mut snapback, "user_a", b"cut-two", true);
    let error = snapback
        .asset_attempt_finalize_inner(
            &authority,
            crate::assets::AssetFinalizeRequestV1 {
                attempt_id: created.task.attempt_id.clone(),
                lifecycle_generation: 1,
                declared_digest: None,
            },
            Some(AssetFinalizeCrashPoint::AfterObjectPut),
        )
        .expect_err("injected crash");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_TEST_CRASH");
    let transfer = asset_dev_authority(&snapback, "user_a", InvocationSource::AssetTransfer);
    snapback
        .asset_attempt_cancel(
            &transfer,
            crate::assets::AssetAttemptCancelRequestV1 {
                attempt_id: created.task.attempt_id.clone(),
                lifecycle_generation: 1,
                discard_asset: false,
            },
        )
        .expect("the work dies");
    let report = snapback
        .asset_publication_maintain(now_millis())
        .expect("maintain");
    assert_eq!(report.staged, 1, "the acknowledged put staged on probe");
    assert_eq!(report.condemned, 1, "dead work condemned");
    assert_eq!(report.retired, 1, "condemned record retired");
    assert_eq!(report.objects_deleted, 1, "the orphan object deleted");

    // Cut 3 — after `staged`, before the publication transaction: same
    // dead-work resolution without the probe transition.
    let created = asset_upload(&mut snapback, "user_a", b"cut-three", true);
    let error = snapback
        .asset_attempt_finalize_inner(
            &authority,
            crate::assets::AssetFinalizeRequestV1 {
                attempt_id: created.task.attempt_id.clone(),
                lifecycle_generation: 1,
                declared_digest: None,
            },
            Some(AssetFinalizeCrashPoint::AfterStaged),
        )
        .expect_err("injected crash");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_TEST_CRASH");
    snapback
        .asset_attempt_cancel(
            &transfer,
            crate::assets::AssetAttemptCancelRequestV1 {
                attempt_id: created.task.attempt_id.clone(),
                lifecycle_generation: 1,
                discard_asset: false,
            },
        )
        .expect("the work dies");
    let report = snapback
        .asset_publication_maintain(now_millis())
        .expect("maintain");
    assert_eq!(report.condemned, 1);
    assert_eq!(report.retired, 1);
    assert_eq!(report.objects_deleted, 1);
}

#[test]
fn asset_publication_records_retire_after_the_retention_window() {
    let mut snapback = asset_test_snapback();
    let created = asset_upload(&mut snapback, "user_a", b"retained", true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None).expect("publishes");

    let now = now_millis();
    let report = snapback.asset_publication_maintain(now).expect("maintain");
    assert_eq!(
        report.retired, 0,
        "inside the retention window nothing retires"
    );

    let later = now + crate::assets::ASSET_PUBLICATION_RETENTION_MS + 1;
    let report = snapback
        .asset_publication_maintain(later)
        .expect("maintain");
    assert_eq!(
        report.retired, 1,
        "the committed record retires; the blob row is the evidence"
    );
    let blob_count: u64 = snapback.db.asset_reads().live_blob_count().expect("blobs");
    assert_eq!(blob_count, 1, "retirement never touches the blob");
}

// -----------------------------------------------------------------
// Bounded on-demand widths (LLP 0044 §Ceremony floor, 2026-08-01).
// -----------------------------------------------------------------

#[test]
fn asset_on_demand_width_materializes_once_and_refuses_honestly() {
    let mut snapback = asset_variant_snapback(
        crate::manifest::AssetLocationPolicy::Strip,
        vec![asset_variant("display", 192, false)],
    );
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None).expect("publishes");
    let asset_id = created.task.asset_id.clone();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // ?width=100 ladder-normalizes to w128 and materializes once.
    let outcome = snapback
        .asset_deliver(&authority, &asset_id, "primary", None, None, Some(100))
        .expect("width delivers");
    let crate::storage::AssetDeliveryOutcome::Content(first) = outcome else {
        panic!("expected content");
    };
    assert!(first.total_length > 0);
    let w128 = asset_rendition_for(&mut snapback, &asset_id, "w128")
        .expect("ladder rendition materialized");
    assert_eq!(w128.state, crate::assets::AssetRenditionState::Ready);
    assert_eq!(w128.media_facts.as_ref().unwrap()["width"], 128);

    // Second request serves the SAME rendition — materialized once.
    let again = snapback
        .asset_deliver(&authority, &asset_id, "primary", None, None, Some(100))
        .expect("width serves again");
    let crate::storage::AssetDeliveryOutcome::Content(second) = again else {
        panic!("expected content");
    };
    assert_eq!(second.total_length, first.total_length);
    let still = asset_rendition_for(&mut snapback, &asset_id, "w128").expect("still there");
    assert_eq!(
        still.rendition_id, w128.rendition_id,
        "no re-materialization"
    );

    // Above the declared ceiling: structured refusal, nothing made.
    let above = snapback
        .asset_deliver(&authority, &asset_id, "primary", None, None, Some(4096))
        .expect_err("above-ceiling width refuses");
    assert_eq!(above.diagnostic.code, "SNAPBACK_ASSET_WIDTH_ABOVE_CEILING");

    // Foreign caller: authorization precedes materialization — the
    // probe refuses and no ladder rendition appears.
    let outsider = asset_dev_authority(&snapback, "user_b", InvocationSource::HttpQuery);
    let denied = snapback
        .asset_deliver(&outsider, &asset_id, "primary", None, None, Some(64))
        .expect_err("outsider width refuses");
    assert_eq!(denied.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    assert!(
        asset_rendition_for(&mut snapback, &asset_id, "w64").is_none(),
        "unauthorized requests never materialize"
    );

    // With the image-finalization gate off, ?width refuses entirely.
    snapback.set_asset_image_finalization_override(false);
    let gated = snapback
        .asset_deliver(&authority, &asset_id, "primary", None, None, Some(64))
        .expect_err("gate-off width refuses");
    snapback.set_asset_image_finalization_override(true);
    assert_eq!(gated.diagnostic.code, "SNAPBACK_ASSET_WIDTH_UNSUPPORTED");
}

#[test]
fn asset_width_plan_owner_survives_put_window_and_condemned_plan_cannot_stage() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    let prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let plan = prepare.prepare().expect("render width");
    let plan_effect = authority
        .reserve_authorized_effect("width owner regression plan")
        .expect("reserve width plan");
    let put = snapback
        .asset_width_plan_with_authorized_effect(plan, plan_effect)
        .expect("commit proved width plan");
    let mut publication = put.publication_for_test().clone();
    let planned_key = publication.planned_key.clone();

    let in_flight = snapback
        .asset_publication_maintain(now_millis())
        .expect("maintenance overlaps width PUT window");
    assert_eq!(
        in_flight,
        super::AssetPublicationMaintenanceReport::default(),
        "the asset/variant owner keeps an objectless width plan re-drivable",
    );

    // Once the exact owner is gone, recovery may condemn the plan. A stale
    // in-memory PUT ticket must then fail its planned -> staged CAS instead of
    // resurrecting the condemned database row.
    snapback
        .db
        .asset_reads()
        .transition_deleted(&asset_id, now_millis())
        .expect("end width owner");
    assert!(
        !snapback
            .db
            .asset_maintenance()
            .publication_width_owner_live(&publication)
            .expect("owner liveness"),
        "the deleted source asset no longer owns width materialization",
    );
    snapback
        .db
        .asset_maintenance()
        .publication_condemn_not_redrivable(&mut publication, None, now_millis())
        .expect("recovery condemns ownerless width plan");

    let commit = put
        .put()
        .expect("the already-authorized idempotent PUT runs");
    let commit_effect = authority
        .reserve_authorized_effect("width owner regression staged CAS")
        .expect("reserve staged attempt");
    let error = snapback
        .asset_width_commit_with_authorized_effect(commit, commit_effect)
        .expect_err("a condemned width plan cannot advance to staged");
    assert_eq!(error.diagnostic.code, "SNAPBACK_ASSET_TRANSITION_INVALID");
    snapback
        .asset_store_obj()
        .expect("width store")
        .delete_blob(&planned_key)
        .expect("clean regression object");
}

#[test]
fn asset_concurrent_first_width_requests_converge_on_winner() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let rendition_events_before = asset_receipt_events(&mut snapback, &asset_id)
        .iter()
        .filter(|event| event.as_str() == "rendition-produced")
        .count();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    let first_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("first width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let second_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("concurrent width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let first_plan = first_prepare.prepare().expect("render first width");
    let second_plan = second_prepare.prepare().expect("render concurrent width");

    let first_effect = authority
        .reserve_authorized_effect("first concurrent width plan")
        .expect("reserve first width plan");
    let first_put = snapback
        .asset_width_plan_with_authorized_effect(first_plan, first_effect)
        .expect("commit first width plan");
    let second_effect = authority
        .reserve_authorized_effect("second concurrent width plan")
        .expect("reserve second width plan");
    let second_put = snapback
        .asset_width_plan_with_authorized_effect(second_plan, second_effect)
        .expect("concurrent request reuses the live width plan");
    assert_eq!(
        first_put.publication_for_test().publication_id,
        second_put.publication_for_test().publication_id,
        "concurrent first requests share one durable publication owner",
    );

    let first_commit = first_put.put().expect("first width PUT succeeds");
    let second_commit = second_put
        .put()
        .expect("concurrent width PUT is idempotent on the shared key");
    let first_commit_effect = authority
        .reserve_authorized_effect("first concurrent width commit")
        .expect("reserve first width commit");
    let winner = snapback
        .asset_width_commit_with_authorized_effect(first_commit, first_commit_effect)
        .expect("first request publishes the width rendition");
    let second_commit_effect = authority
        .reserve_authorized_effect("second concurrent width commit")
        .expect("reserve concurrent width commit");
    let loser = snapback
        .asset_width_commit_with_authorized_effect(second_commit, second_commit_effect)
        .expect("concurrent loser succeeds on the winner's rendition");

    assert_eq!(winner, "w128");
    assert_eq!(loser, winner);
    let rendition = asset_rendition_for(&mut snapback, &asset_id, &winner)
        .expect("winner rendition remains current");
    assert_eq!(rendition.state, crate::assets::AssetRenditionState::Ready);
    let events = asset_receipt_events(&mut snapback, &asset_id);
    assert_eq!(
        events
            .iter()
            .filter(|event| event.as_str() == "rendition-produced")
            .count(),
        rendition_events_before + 1,
        "the converged loser cannot publish a second rendition: {events:?}",
    );
}

#[test]
fn asset_staggered_width_planning_cohort_converges_on_first_rendition() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let rendition_events_before = asset_receipt_events(&mut snapback, &asset_id)
        .iter()
        .filter(|event| event.as_str() == "rendition-produced")
        .count();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // All three requests take the same stale preflight before w128 exists.
    let mut preflight = || match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("staggered width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let first_plan = preflight().prepare().expect("render first width");
    let second_plan = preflight().prepare().expect("render second width");
    let third_plan = preflight().prepare().expect("render third width");

    let first_effect = authority
        .reserve_authorized_effect("first staggered width plan")
        .expect("reserve first width plan");
    let first_put = snapback
        .asset_width_plan_with_authorized_effect(first_plan, first_effect)
        .expect("commit first width plan");
    let first_publication_id = first_put.publication_for_test().publication_id.clone();
    let first_commit = first_put.put().expect("first width PUT succeeds");
    let first_commit_effect = authority
        .reserve_authorized_effect("first staggered width commit")
        .expect("reserve first width commit");
    let winner = snapback
        .asset_width_commit_with_authorized_effect(first_commit, first_commit_effect)
        .expect("first request publishes the width rendition");

    // The second request plans after the first publication is terminal, so it
    // receives a fresh publication. The third request joins that open plan.
    let second_effect = authority
        .reserve_authorized_effect("second staggered width plan")
        .expect("reserve second width plan");
    let second_put = snapback
        .asset_width_plan_with_authorized_effect(second_plan, second_effect)
        .expect("commit second width plan");
    let third_effect = authority
        .reserve_authorized_effect("third staggered width plan")
        .expect("reserve third width plan");
    let third_put = snapback
        .asset_width_plan_with_authorized_effect(third_plan, third_effect)
        .expect("third request reuses second width plan");
    assert_ne!(
        second_put.publication_for_test().publication_id,
        first_publication_id,
        "a stale preflight after the winner commits receives a new publication",
    );
    assert_eq!(
        third_put.publication_for_test().publication_id,
        second_put.publication_for_test().publication_id,
        "the third request joins the second request's open publication",
    );

    let second_commit = second_put.put().expect("second width PUT succeeds");
    let third_commit = third_put
        .put()
        .expect("third width PUT is idempotent on the shared key");
    let second_commit_effect = authority
        .reserve_authorized_effect("second staggered width commit")
        .expect("reserve second width commit");
    let second = snapback
        .asset_width_commit_with_authorized_effect(second_commit, second_commit_effect)
        .expect("second request converges on the first rendition");
    let third_commit_effect = authority
        .reserve_authorized_effect("third staggered width commit")
        .expect("reserve third width commit");
    let third = snapback
        .asset_width_commit_with_authorized_effect(third_commit, third_commit_effect)
        .expect("third request converges through the condemned shared publication");

    assert_eq!(winner, "w128");
    assert_eq!(second, winner);
    assert_eq!(third, winner);
    let rendition = asset_rendition_for(&mut snapback, &asset_id, &winner)
        .expect("the first rendition remains current");
    assert_eq!(rendition.state, crate::assets::AssetRenditionState::Ready);
    let events = asset_receipt_events(&mut snapback, &asset_id);
    assert_eq!(
        events
            .iter()
            .filter(|event| event.as_str() == "rendition-produced")
            .count(),
        rendition_events_before + 1,
        "the staggered cohort publishes exactly one rendition: {events:?}",
    );
}

#[test]
fn asset_gc_retains_condemned_publication_until_last_width_put_resolves() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // A, B, and C all prepare before the width exists. A publishes w128;
    // staggered B and C then share a fresh stale publication P.
    let mut preflight = || match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("late-put width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let first_plan = preflight().prepare().expect("render first width");
    let second_plan = preflight().prepare().expect("render second width");
    let third_plan = preflight().prepare().expect("render third width");

    let first_effect = authority
        .reserve_authorized_effect("late-put first width plan")
        .expect("reserve first width plan");
    let first_put = snapback
        .asset_width_plan_with_authorized_effect(first_plan, first_effect)
        .expect("commit first width plan");
    let first_commit = first_put.put().expect("first width PUT succeeds");
    let first_commit_effect = authority
        .reserve_authorized_effect("late-put first width commit")
        .expect("reserve first width commit");
    snapback
        .asset_width_commit_with_authorized_effect(first_commit, first_commit_effect)
        .expect("first request publishes the width rendition");

    let second_effect = authority
        .reserve_authorized_effect("late-put second width plan")
        .expect("reserve second width plan");
    let second_put = snapback
        .asset_width_plan_with_authorized_effect(second_plan, second_effect)
        .expect("commit stale second width plan");
    let third_effect = authority
        .reserve_authorized_effect("late-put third width plan")
        .expect("reserve third width plan");
    let third_put = snapback
        .asset_width_plan_with_authorized_effect(third_plan, third_effect)
        .expect("third request joins the stale publication");
    let publication_id = second_put.publication_for_test().publication_id.clone();
    let planned_key = second_put.publication_for_test().planned_key.clone();
    assert_eq!(
        third_put.publication_for_test().publication_id,
        publication_id,
        "B and C hold PUT tickets for the same durable publication",
    );

    // B's PUT and commit converge on A and condemn P while C still holds the
    // sibling PUT ticket. GC must leave P and its object discoverable.
    let second_commit = second_put.put().expect("second width PUT succeeds");
    let second_commit_effect = authority
        .reserve_authorized_effect("late-put second width commit")
        .expect("reserve second width commit");
    snapback
        .asset_width_commit_with_authorized_effect(second_commit, second_commit_effect)
        .expect("second request converges and condemns the stale publication");
    let overlapping_gc = snapback
        .asset_publication_maintain(now_millis())
        .expect("GC overlaps the outstanding sibling PUT ticket");
    assert_eq!(
        overlapping_gc,
        super::AssetPublicationMaintenanceReport::default(),
        "GC cannot clean or retire P while C can still recreate its object",
    );
    assert!(
        snapback
            .db
            .asset_maintenance()
            .publication_records_in_state(crate::assets::AssetPublicationState::Condemned)
            .expect("read retained condemned publication")
            .iter()
            .any(|record| record.publication_id == publication_id),
        "the outstanding ticket keeps P discoverable",
    );

    // C's idempotent PUT and staged cut converge on A through retained P. Once
    // the commit ticket resolves, the next pass may delete and retire P.
    let third_commit = third_put
        .put()
        .expect("late sibling PUT remains idempotent on the retained object");
    let store = snapback.asset_store_obj().expect("width store");
    assert!(
        store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe recreated width object"),
        "P's object remains present until C resolves",
    );
    let third_commit_effect = authority
        .reserve_authorized_effect("late-put third width commit")
        .expect("reserve third width commit");
    let converged = snapback
        .asset_width_commit_with_authorized_effect(third_commit, third_commit_effect)
        .expect("late sibling converges through retained condemned publication");
    assert_eq!(converged, "w128");

    let cleanup_gc = snapback
        .asset_publication_maintain(now_millis())
        .expect("GC removes the released condemned object");
    assert_eq!(cleanup_gc.objects_deleted, 1);
    assert_eq!(cleanup_gc.retired, 1);
    assert!(
        !store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe cleaned late width object"),
        "no undiscoverable object remains after cleanup",
    );
}

#[test]
fn asset_publication_maintain_retains_torn_plan_during_active_width_put() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // A and C both prepare before the width exists. A publishes w128; C then
    // receives a fresh stale publication P whose exact width is no longer
    // re-drivable.
    let first_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("winner width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let mut stale_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("stale width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let first_plan = first_prepare.prepare().expect("render winner width");

    let (entered_tx, entered_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let gated_store: Arc<dyn crate::assets_store::AssetStore> = Arc::new(BlockFirstBlobHashStore {
        inner: stale_prepare.store_for_test(),
        entered: std::sync::Mutex::new(Some(entered_tx)),
        release: std::sync::Mutex::new(release_rx),
    });
    stale_prepare.replace_store_for_test(gated_store);
    let stale_plan = stale_prepare.prepare().expect("render stale width");

    let first_effect = authority
        .reserve_authorized_effect("torn-plan winner width plan")
        .expect("reserve winner width plan");
    let first_put = snapback
        .asset_width_plan_with_authorized_effect(first_plan, first_effect)
        .expect("commit winner width plan");
    let first_commit = first_put.put().expect("winner width PUT succeeds");
    let first_commit_effect = authority
        .reserve_authorized_effect("torn-plan winner width commit")
        .expect("reserve winner width commit");
    snapback
        .asset_width_commit_with_authorized_effect(first_commit, first_commit_effect)
        .expect("winner publishes the width rendition");

    let stale_effect = authority
        .reserve_authorized_effect("torn-plan stale width plan")
        .expect("reserve stale width plan");
    let stale_put = snapback
        .asset_width_plan_with_authorized_effect(stale_plan, stale_effect)
        .expect("commit stale width plan");
    let publication_id = stale_put.publication_for_test().publication_id.clone();
    let planned_key = stale_put.publication_for_test().planned_key.clone();

    // C completes its object PUT and pauses before verifying it. Replace the
    // bytes with a deterministic torn object so the earlier planned-record
    // cleanup arm would delete and condemn P if it ignored C's active lease.
    let stale_put_thread = std::thread::spawn(move || stale_put.put());
    entered_rx
        .recv()
        .expect("C reaches the post-PUT verifying hash");
    let store = snapback.asset_store_obj().expect("width store");
    store
        .delete_blob(&planned_key)
        .expect("replace completed PUT with torn bytes");
    store
        .put_blob_idempotent(&planned_key, b"torn-width-publication")
        .expect("write deterministic torn object");

    let retained = snapback
        .asset_publication_maintain(now_millis())
        .expect("maintenance overlaps active torn PUT");
    assert_eq!(
        retained,
        super::AssetPublicationMaintenanceReport::default(),
        "planned cleanup cannot delete or condemn under an active width PUT lease",
    );
    assert!(
        store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe retained torn object"),
        "the torn-PUT arm must leave the active ticket's object in place",
    );
    assert!(
        snapback
            .db
            .asset_maintenance()
            .publication_records_in_state(crate::assets::AssetPublicationState::Planned)
            .expect("read retained planned publication")
            .iter()
            .any(|record| record.publication_id == publication_id),
        "the active ticket keeps its planned publication discoverable",
    );

    release_tx.send(()).expect("release C's verifying hash");
    let verification_error = match stale_put_thread.join().expect("C put thread joins") {
        Ok(_) => panic!("the deterministic torn object cannot verify"),
        Err(error) => error,
    };
    assert_eq!(
        verification_error.diagnostic.code,
        "SNAPBACK_ASSET_STORE_UNAVAILABLE"
    );

    let cleaned = snapback
        .asset_publication_maintain(now_millis())
        .expect("maintenance resolves P after C drops its lease");
    assert_eq!(cleaned.condemned, 1);
    assert_eq!(cleaned.retired, 1);
}

#[test]
fn asset_expired_width_put_cannot_delete_sibling_committed_publication_blob() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // Both first-width requests preflight and render before w128 exists. C's
    // conditional PUT enters the remote seam and crosses its lease deadline;
    // B then joins the same still-planned P under a fresh lease.
    let mut late_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("late first-width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let winner_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("winner first-width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let (entered_tx, entered_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let inner = late_prepare.store_for_test();
    let blocked: Arc<dyn crate::assets_store::AssetStore> = Arc::new(ScriptedPublicationStore {
        inner: inner.clone(),
        blocked_put: std::sync::Mutex::new(Some((entered_tx, release_rx))),
        corrupt_blob_hash_call: None,
        blob_hash_calls: std::sync::atomic::AtomicU64::new(0),
    });
    late_prepare.replace_store_for_test(blocked);
    let late_plan = late_prepare.prepare().expect("render late width");
    let winner_plan = winner_prepare.prepare().expect("render winner width");
    let late_effect = authority
        .reserve_authorized_effect("expired committed-P late plan")
        .expect("reserve late width plan");
    let late_put = snapback
        .asset_width_plan_with_authorized_effect(late_plan, late_effect)
        .expect("commit shared width plan P");
    let publication_id = late_put.publication_for_test().publication_id.clone();
    let planned_key = late_put.publication_for_test().planned_key.clone();
    let late_thread = std::thread::spawn(move || late_put.put());
    entered_rx
        .recv()
        .expect("C enters the blocked conditional PUT");

    snapback_services::assets::asset_publication_expire_put_leases_for_test(&publication_id);
    assert_eq!(
        snapback_services::assets::asset_publication_put_lease_state(&publication_id),
        snapback_services::assets::AssetPublicationPutLeaseStateV1::ExpiredInFlight,
    );
    let winner_effect = authority
        .reserve_authorized_effect("expired committed-P winner plan")
        .expect("reserve winner width plan");
    let winner_put = snapback
        .asset_width_plan_with_authorized_effect(winner_plan, winner_effect)
        .expect("B joins C's still-planned publication");
    assert_eq!(
        winner_put.publication_for_test().publication_id,
        publication_id,
        "B and expired C share the exact publication P",
    );
    let winner_commit = winner_put.put().expect("B's PUT verifies");
    let winner_commit_effect = authority
        .reserve_authorized_effect("expired committed-P winner commit")
        .expect("reserve winner width commit");
    snapback
        .asset_width_commit_with_authorized_effect(winner_commit, winner_commit_effect)
        .expect("B commits P as the live w128 blob");
    assert!(
        inner
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe B's committed P"),
        "P exists at the committed cut",
    );

    // C now receives the idempotent existing-object result (the local seam's
    // analogue of S3 412). Its expired capability must refuse without
    // deleting the key whose durable state changed while it was blocked.
    release_tx.send(()).expect("release C's conditional PUT");
    let late_error = match late_thread.join().expect("C PUT thread joins") {
        Ok(_) => panic!("expired C must refuse after the remote PUT returns"),
        Err(error) => error,
    };
    assert_eq!(
        late_error.diagnostic.details["reason"],
        "publication-put-lease-expired"
    );
    assert!(
        inner
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe committed P after expired C returns"),
        "expired service tickets cannot delete a key now owned by a live blob",
    );
    asset_deliver_content(&mut snapback, "user_a", &asset_id, "w128", None)
        .expect("the winner's committed rendition remains deliverable");
}

#[test]
fn asset_runner_retains_active_width_put_then_bounded_expiry_reclaims_it() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // A, B, and C prepare before the width exists. A publishes w128; B and C
    // subsequently share a fresh stale publication P.
    let mut preflight = || match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("runner-race width preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let first_plan = preflight().prepare().expect("render first width");
    let second_plan = preflight().prepare().expect("render second width");
    let mut third_prepare = preflight();
    let (entered_tx, entered_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let gated_store: Arc<dyn crate::assets_store::AssetStore> = Arc::new(BlockFirstBlobHashStore {
        inner: third_prepare.store_for_test(),
        entered: std::sync::Mutex::new(Some(entered_tx)),
        release: std::sync::Mutex::new(release_rx),
    });
    third_prepare.replace_store_for_test(gated_store);
    let third_plan = third_prepare.prepare().expect("render third width");

    let first_effect = authority
        .reserve_authorized_effect("runner-race first width plan")
        .expect("reserve first width plan");
    let first_put = snapback
        .asset_width_plan_with_authorized_effect(first_plan, first_effect)
        .expect("commit first width plan");
    let first_commit = first_put.put().expect("first width PUT succeeds");
    let first_commit_effect = authority
        .reserve_authorized_effect("runner-race first width commit")
        .expect("reserve first width commit");
    snapback
        .asset_width_commit_with_authorized_effect(first_commit, first_commit_effect)
        .expect("first request publishes the width rendition");

    let second_effect = authority
        .reserve_authorized_effect("runner-race second width plan")
        .expect("reserve second width plan");
    let second_put = snapback
        .asset_width_plan_with_authorized_effect(second_plan, second_effect)
        .expect("commit stale second width plan");
    let third_effect = authority
        .reserve_authorized_effect("runner-race third width plan")
        .expect("reserve third width plan");
    let third_put = snapback
        .asset_width_plan_with_authorized_effect(third_plan, third_effect)
        .expect("third request joins stale publication");
    let publication_id = second_put.publication_for_test().publication_id.clone();
    let planned_key = second_put.publication_for_test().planned_key.clone();
    assert_eq!(
        third_put.publication_for_test().publication_id,
        publication_id,
        "B and C share the same condemned-work publication",
    );

    let second_commit = second_put.put().expect("second width PUT succeeds");
    let second_commit_effect = authority
        .reserve_authorized_effect("runner-race second width commit")
        .expect("reserve second width commit");
    snapback
        .asset_width_commit_with_authorized_effect(second_commit, second_commit_effect)
        .expect("B converges and enqueues production condemned cleanup");

    // C has completed the idempotent PUT and is blocked immediately before
    // hash verification. This is the S3 412/delete/hash race in deterministic
    // form. The production runner must retry rather than delete P.
    let third_put_thread = std::thread::spawn(move || third_put.put());
    entered_rx
        .recv()
        .expect("C reaches the post-PUT verifying hash");
    let store = snapback.asset_store_obj().expect("width store");
    assert!(
        store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe C's object before runner"),
        "C's PUT completed before the runner interleaving",
    );

    let runner_now = now_millis();
    let retained = snapback
        .asset_runner_tick(runner_now)
        .expect("production runner overlaps active C ticket");
    assert!(
        store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe lease-retained object"),
        "the production runner cannot delete before C verifies",
    );
    assert_eq!(retained.claimed, 1, "the production cleanup row is driven");
    assert_eq!(
        retained.completed, 0,
        "leased cleanup stays claimed for receipted work-lease re-drive",
    );

    // Force the monotonic deadline instead of sleeping five minutes. An
    // in-flight call becomes row-only uncertainty custody: the runner can
    // reclaim bytes, but it cannot make the late effect undiscoverable.
    snapback_services::assets::asset_publication_expire_put_leases_for_test(&publication_id);
    assert_eq!(
        snapback_services::assets::asset_publication_put_lease_state(&publication_id),
        snapback_services::assets::AssetPublicationPutLeaseStateV1::ExpiredInFlight,
    );
    let expired = snapback
        .asset_runner_tick(runner_now + crate::assets::ASSET_WORK_LEASE_MS + 1)
        .expect("runner re-drives after bounded lease expiry");
    assert_eq!(
        expired.leases_reclaimed, 1,
        "the deferred cleanup reclaims through the ordinary work lease",
    );
    assert_eq!(expired.completed, 1, "expired cleanup completes");
    assert!(
        !store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe reclaimed expired object"),
        "an expired PUT cannot pin condemned object bytes",
    );
    assert!(
        snapback
            .db
            .asset_maintenance()
            .publication_records_in_state(crate::assets::AssetPublicationState::Condemned)
            .expect("read expired in-flight owner")
            .iter()
            .any(|record| record.publication_id == publication_id),
        "the durable condemned row owns uncertainty until C returns",
    );

    release_tx.send(()).expect("release C's verifying hash");
    let lease_error = match third_put_thread.join().expect("C put thread joins") {
        Ok(_) => panic!("C crossing the lease deadline must fail closed"),
        Err(error) => error,
    };
    assert_eq!(
        lease_error.diagnostic.code,
        "SNAPBACK_ASSET_STORE_UNAVAILABLE"
    );
    assert_eq!(
        lease_error.diagnostic.details["reason"],
        "publication-put-lease-expired"
    );
    assert!(
        !store
            .exists(crate::assets_store::AssetObjectRef::Blob(&planned_key))
            .expect("probe post-expiry cleanup"),
        "the expired call leaves no object behind",
    );

    let retired = snapback
        .asset_publication_maintain(runner_now + crate::assets::ASSET_WORK_LEASE_MS + 2)
        .expect("retire objectless publication after uncertainty resolves");
    assert_eq!(retired.retired, 1);
}

#[test]
fn asset_stale_width_plan_converges_before_tight_quota_is_charged() {
    let mut snapback =
        asset_variant_snapback(crate::manifest::AssetLocationPolicy::Strip, Vec::new());
    let fixture = crate::assets_image::fixtures::plain_jpeg(200, 150);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None)
        .expect("publish width source");
    let asset_id = created.task.asset_id.clone();
    let settled_before = snapback
        .db
        .asset_reads()
        .accounting(&snapback.functions.app_id)
        .expect("read primary quota")
        .settled_bytes;
    let tight_quota = settled_before + crate::assets::ASSET_MIN_ACCOUNTING_UNIT_BYTES;
    snapback.set_asset_quota_override(tight_quota);
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // Both requests preflight while only the primary rendition consumes quota.
    let first_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("first tight-quota preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let second_prepare = match snapback
        .asset_width_preflight(&asset_id, 100)
        .expect("second tight-quota preflight")
    {
        AssetWidthPreflightV1::Proceed(ticket) => ticket,
        AssetWidthPreflightV1::AlreadyReady(_) => panic!("width is not materialized yet"),
    };
    let first_plan = first_prepare.prepare().expect("render first width");
    let second_plan = second_prepare.prepare().expect("render second width");

    let first_effect = authority
        .reserve_authorized_effect("first tight-quota width plan")
        .expect("reserve first width plan");
    let first_put = snapback
        .asset_width_plan_with_authorized_effect(first_plan, first_effect)
        .expect("commit first width plan");
    let first_commit = first_put.put().expect("first width PUT succeeds");
    let first_commit_effect = authority
        .reserve_authorized_effect("first tight-quota width commit")
        .expect("reserve first width commit");
    let winner = snapback
        .asset_width_commit_with_authorized_effect(first_commit, first_commit_effect)
        .expect("first request consumes the remaining quota");

    // The stale second preflight plans only after the first publication is
    // terminal. Serving the existing Ready rendition must not charge again.
    let second_effect = authority
        .reserve_authorized_effect("second tight-quota width plan")
        .expect("reserve second width plan");
    let second_put = snapback
        .asset_width_plan_with_authorized_effect(second_plan, second_effect)
        .expect("commit stale second width plan");
    let second_commit = second_put.put().expect("second width PUT succeeds");
    let second_commit_effect = authority
        .reserve_authorized_effect("second tight-quota width commit")
        .expect("reserve second width commit");
    let converged = snapback
        .asset_width_commit_with_authorized_effect(second_commit, second_commit_effect)
        .expect("existing rendition converges before quota settlement");

    assert_eq!(winner, "w128");
    assert_eq!(converged, winner);
    let accounting = snapback
        .db
        .asset_reads()
        .accounting(&snapback.functions.app_id)
        .expect("read tight-quota accounting");
    assert_eq!(
        accounting.settled_bytes, tight_quota,
        "the converged request adds no logical quota charge",
    );
}

// -----------------------------------------------------------------
// Strict delivery and the deletion/GC sweeps (tickets L1-09/L1-10).
// -----------------------------------------------------------------

fn asset_variant(key: &str, width: u64, required: bool) -> crate::manifest::AssetImageVariant {
    crate::manifest::AssetImageVariant {
        key: key.to_owned(),
        width,
        required,
    }
}

fn asset_rendition_for(
    snapback: &mut LocalSnapback,
    asset_id: &str,
    key: &str,
) -> Option<crate::assets::AssetRenditionRecordV1> {
    snapback
        .db
        .asset_reads()
        .load_rendition_by_variant(asset_id, key)
        .expect("rendition lookup")
}

#[test]
fn asset_variants_required_gate_ready_and_optionals_ride_the_runner() {
    let mut snapback = asset_variant_snapback(
        crate::manifest::AssetLocationPolicy::Strip,
        vec![
            asset_variant("thumb", 16, true),
            asset_variant("display", 48, false),
        ],
    );
    let fixture = crate::assets_image::fixtures::plain_jpeg(64, 48);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None).expect("publishes");
    let asset_id = created.task.asset_id.clone();

    // Required committed with `ready`, atomically — visible immediately.
    let thumb = asset_rendition_for(&mut snapback, &asset_id, "thumb")
        .expect("required thumb is ready with the asset");
    assert_eq!(thumb.state, crate::assets::AssetRenditionState::Ready);
    assert_eq!(thumb.media_facts.as_ref().unwrap()["width"], 16);

    // The optional enqueued transactionally with `ready` and is not
    // produced until the runner drives it.
    assert!(asset_rendition_for(&mut snapback, &asset_id, "display").is_none());
    let work = snapback
        .db
        .asset_reads()
        .work_rows(&asset_id)
        .expect("work rows");
    assert!(work.iter().any(|row| {
        row.kind == crate::assets::ASSET_WORK_KIND_IMAGE_VARIANT
            && row
                .params
                .as_ref()
                .is_some_and(|params| params["key"] == "display")
    }));

    let report = snapback
        .asset_runner_tick(now_millis())
        .expect("runner tick");
    assert!(report.completed >= 1);
    let display = asset_rendition_for(&mut snapback, &asset_id, "display")
        .expect("optional display produced by the runner");
    assert_eq!(display.state, crate::assets::AssetRenditionState::Ready);
    assert_eq!(display.media_facts.as_ref().unwrap()["width"], 48);

    // Delivery: by key, and the declarative best-≤-width selector.
    let by_key = asset_deliver_content(&mut snapback, "user_a", &asset_id, "thumb", None)
        .expect("thumb delivers");
    assert!(by_key.total_length > 0);
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let pick = |snapback: &mut LocalSnapback, bound: u64| match snapback
        .asset_deliver(&authority, &asset_id, "best", None, Some(bound), None)
        .expect("best delivers")
    {
        crate::storage::AssetDeliveryOutcome::Content(delivery) => delivery.content_type,
        other => panic!("unexpected outcome: {other:?}"),
    };
    // 48 admits the display; 20 admits only the thumb; 8 falls back to
    // the narrowest available.
    assert_eq!(pick(&mut snapback, 48), "image/jpeg");
    let best_48 = snapback
        .asset_deliver(&authority, &asset_id, "best", None, Some(48), None)
        .expect("best 48");
    let best_20 = snapback
        .asset_deliver(&authority, &asset_id, "best", None, Some(20), None)
        .expect("best 20");
    let best_8 = snapback
        .asset_deliver(&authority, &asset_id, "best", None, Some(8), None)
        .expect("best 8");
    let width_of = |outcome: &crate::storage::AssetDeliveryOutcome| match outcome {
        crate::storage::AssetDeliveryOutcome::Content(delivery) => delivery.total_length,
        other => panic!("unexpected outcome: {other:?}"),
    };
    assert!(
        width_of(&best_48) > width_of(&best_20),
        "48 picks the wider display"
    );
    assert_eq!(
        width_of(&best_20),
        width_of(&best_8),
        "8 falls back to the thumb"
    );

    // Required-variant receipt with lineage.
    let receipts = snapback
        .db
        .asset_reads()
        .receipts_for_asset(&asset_id, 64)
        .expect("receipts");
    assert!(receipts.iter().any(|receipt| {
        receipt.event == crate::assets::AssetReceiptEventV1::RenditionProduced
            && receipt.details["variantKey"] == "thumb"
            && receipt.details["required"] == true
    }));
}

#[test]
fn asset_variant_stale_recipe_run_cannot_replace_newer() {
    let mut snapback = asset_variant_snapback(
        crate::manifest::AssetLocationPolicy::Strip,
        vec![asset_variant("display", 48, false)],
    );
    let fixture = crate::assets_image::fixtures::plain_jpeg(64, 48);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None).expect("publishes");
    let asset_id = created.task.asset_id.clone();

    // A newer recipe generation already holds the pointer before the
    // enqueued v1 work drives.
    let newer = crate::assets::AssetRenditionRecordV1 {
        rendition_id: crate::assets::AssetFsStore::new_opaque_key(),
        asset_id: asset_id.clone(),
        variant_key: "display".to_owned(),
        blob_id: "synthetic-newer".to_owned(),
        state: crate::assets::AssetRenditionState::Ready,
        recipe: crate::assets::ASSET_RECIPE_IMAGE_VARIANT_V1.to_owned(),
        recipe_version: 2,
        media_facts: Some(serde_json::json!({ "width": 48 })),
        created_at_ms: now_millis(),
        updated_at_ms: now_millis(),
        failure: None,
    };
    snapback
        .db
        .asset_reads()
        .insert_rendition(&newer)
        .expect("newer rendition installs");

    let report = snapback
        .asset_runner_tick(now_millis())
        .expect("runner tick");
    assert!(
        report.completed >= 1,
        "the stale run settles as done, not retrying"
    );
    let current =
        asset_rendition_for(&mut snapback, &asset_id, "display").expect("pointer still present");
    assert_eq!(
        current.rendition_id, newer.rendition_id,
        "the stale run cannot replace"
    );

    // The runner's idempotent short-circuit caught the newer pointer
    // before rendering; the pointer-layer rule holds independently: a
    // v1 candidate against the v2 holder loses at the switch itself.
    let stale_candidate = crate::assets::AssetRenditionRecordV1 {
        rendition_id: crate::assets::AssetFsStore::new_opaque_key(),
        asset_id: asset_id.clone(),
        variant_key: "display".to_owned(),
        blob_id: "synthetic-stale".to_owned(),
        state: crate::assets::AssetRenditionState::Ready,
        recipe: crate::assets::ASSET_RECIPE_IMAGE_VARIANT_V1.to_owned(),
        recipe_version: 1,
        media_facts: None,
        created_at_ms: now_millis(),
        updated_at_ms: now_millis(),
        failure: None,
    };
    let outcome = snapback
        .db
        .asset_reads()
        .switch_variant_pointer_now(&stale_candidate)
        .expect("switch runs");
    assert_eq!(
        outcome,
        crate::assets::AssetVariantSwitchOutcome::StaleLoses
    );
    let still = asset_rendition_for(&mut snapback, &asset_id, "display").expect("pointer survives");
    assert_eq!(still.rendition_id, newer.rendition_id);
}

#[test]
fn asset_variant_quota_refusals_are_structured_and_never_gate_the_primary() {
    // Optional path: publish under a generous quota, then shrink it so
    // the runner's settlement refuses as a rendition failure while the
    // primary stays ready.
    let mut snapback = asset_variant_snapback(
        crate::manifest::AssetLocationPolicy::Strip,
        vec![asset_variant("display", 48, false)],
    );
    let fixture = crate::assets_image::fixtures::plain_jpeg(64, 48);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None).expect("publishes");
    let asset_id = created.task.asset_id.clone();
    snapback.set_asset_quota_override(crate::assets::ASSET_MIN_ACCOUNTING_UNIT_BYTES);
    let report = snapback
        .asset_runner_tick(now_millis())
        .expect("runner tick");
    assert!(
        report.completed >= 1,
        "quota refusal settles the work as done"
    );
    assert!(asset_rendition_for(&mut snapback, &asset_id, "display").is_none());
    let receipts = snapback
        .db
        .asset_reads()
        .receipts_for_asset(&asset_id, 64)
        .expect("receipts");
    assert!(receipts.iter().any(|receipt| {
        receipt.event == crate::assets::AssetReceiptEventV1::RenditionFailed
            && receipt.details["failure"] == "SNAPBACK_ASSET_QUOTA_EXCEEDED"
    }));
    let asset = snapback
        .db
        .asset_reads()
        .require_asset(&asset_id)
        .expect("asset");
    assert_eq!(asset.availability, crate::assets::AssetAvailability::Ready);

    // Required path: the whole publication refuses, pending for retry.
    let mut strict = asset_variant_snapback(
        crate::manifest::AssetLocationPolicy::Strip,
        vec![asset_variant("thumb", 16, true)],
    );
    strict.set_asset_quota_override(crate::assets::ASSET_MIN_ACCOUNTING_UNIT_BYTES * 2);
    let held = asset_upload(&mut strict, "user_a", &fixture, true);
    let refused = asset_finalize(&mut strict, "user_a", &held.task.attempt_id, None)
        .expect_err("required settlement must refuse");
    assert_eq!(refused.diagnostic.code, "SNAPBACK_ASSET_QUOTA_EXCEEDED");
    assert_eq!(refused.diagnostic.details["variantKey"], "thumb");
    let held_asset = strict
        .db
        .asset_reads()
        .require_asset(&held.task.asset_id)
        .expect("asset");
    assert_eq!(
        held_asset.availability,
        crate::assets::AssetAvailability::Pending,
        "quota can free later; the asset stays retry-eligible"
    );
    assert!(
        asset_rendition_for(&mut strict, &held.task.asset_id, "primary").is_none(),
        "nothing published: required renditions gate ready atomically"
    );
}

#[test]
fn asset_deletion_retires_variant_renditions_with_exact_refcounts() {
    let mut snapback = asset_variant_snapback(
        crate::manifest::AssetLocationPolicy::Strip,
        vec![asset_variant("thumb", 16, true)],
    );
    let fixture = crate::assets_image::fixtures::plain_jpeg(64, 48);
    let created = asset_upload(&mut snapback, "user_a", &fixture, true);
    asset_finalize(&mut snapback, "user_a", &created.task.attempt_id, None).expect("publishes");
    let asset_id = created.task.asset_id.clone();
    let thumb = asset_rendition_for(&mut snapback, &asset_id, "thumb").expect("thumb ready");

    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    snapback
        .asset_delete(&authority, &asset_id)
        .expect("deletes");

    let (thumb_after, live_refcount) = snapback
        .db
        .asset_reads()
        .rendition_and_refcount(&thumb.rendition_id, &thumb.blob_id)
        .expect("post-delete rows");
    assert_eq!(
        thumb_after.state,
        crate::assets::AssetRenditionState::Retired
    );
    assert_eq!(
        live_refcount, 0,
        "each rendition's blob reference decrements exactly once"
    );
}

#[test]
fn asset_issuance_resolves_public_immutable_to_the_stable_route() {
    // Author ruling 2026-08-16: public-immutable is the common delivery
    // profile, so issuance resolves it to the stable public route instead
    // of refusing — every issued-URL client projection renders it with no
    // special path. Only private-strict keeps the typed refusal.
    let mut snapback = asset_profile_snapback();
    let bytes = b"public-profile-bytes".to_vec();
    let asset_id = asset_ready_under_intent(&mut snapback, "user_a", &bytes, "publicUpload");
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    let issued = snapback
        .asset_signed_url_issue(
            &owner,
            &asset_id,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: Some("primary".to_owned()),
                ttl_ms: None,
                width_px: None,
            },
        )
        .expect("public issuance resolves");
    assert_eq!(issued.url, format!("/assets/public/{asset_id}/primary"));
    assert_eq!(issued.variant, "primary");
    assert!(
        issued.expires_at_ms > now_millis() + 365 * 24 * 60 * 60 * 1000,
        "synthetic expiry keeps refresh loops dormant"
    );
    assert!(
        !issued.url.contains("token"),
        "no bearer on the public route"
    );

    let strict_bytes = b"strict-profile-bytes".to_vec();
    let strict_id =
        asset_ready_under_intent(&mut snapback, "user_a", &strict_bytes, "strictUpload");
    let strict = snapback
        .asset_signed_url_issue(
            &owner,
            &strict_id,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: Some("primary".to_owned()),
                ttl_ms: None,
                width_px: None,
            },
        )
        .expect_err("private-strict keeps its typed refusal");
    assert_eq!(
        strict.diagnostic.code,
        "SNAPBACK_ASSET_DELIVERY_PROFILE_UNSUPPORTED"
    );
}

#[test]
fn asset_signed_url_issues_and_serves_as_a_bearer_until_ttl() {
    let mut snapback = asset_profile_snapback();
    let bytes = b"signed-profile-bytes".to_vec();
    let asset_id = asset_ready_under_intent(&mut snapback, "user_a", &bytes, "signedUpload");
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);

    // @ref LLP 0210#d2--issuance-defaults-and-typed-refusals — issuance
    // authorization hides both asset existence and declared variants.
    let foreign = asset_dev_authority(&snapback, "user_b", InvocationSource::HttpQuery);
    let unknown_request = || crate::assets::AssetSignedUrlIssueRequestV1 {
        variant: Some("secret-variant".to_owned()),
        ttl_ms: None,
        width_px: None,
    };
    let existing_denial = snapback
        .asset_signed_url_issue(&foreign, &asset_id, unknown_request())
        .expect_err("foreign issuance refuses before variant validation");
    let missing_denial = snapback
        .asset_signed_url_issue(&foreign, "asset_missing", unknown_request())
        .expect_err("missing asset refuses without becoming an existence oracle");
    assert_eq!(existing_denial, missing_denial);
    assert_eq!(existing_denial.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");
    assert!(existing_denial.diagnostic.details.get("variants").is_none());

    // TTL beyond the declared maximum and the unsignable `best`
    // selector refuse structurally.
    let over = snapback
        .asset_signed_url_issue(
            &owner,
            &asset_id,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: Some("primary".to_owned()),
                ttl_ms: Some(crate::assets::ASSET_SIGNED_URL_MAX_TTL_MS + 1),
                width_px: None,
            },
        )
        .expect_err("over-max ttl refuses");
    assert_eq!(over.diagnostic.code, "SNAPBACK_ASSET_TTL_INVALID");
    let best = snapback
        .asset_signed_url_issue(
            &owner,
            &asset_id,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: Some("best".to_owned()),
                ttl_ms: None,
                width_px: None,
            },
        )
        .expect_err("best is unsignable");
    assert_eq!(best.diagnostic.code, "SNAPBACK_ASSET_VARIANT_UNKNOWN");
    assert_eq!(
        best.diagnostic.details["variants"],
        serde_json::json!(["primary", "thumb"])
    );
    assert_eq!(best.diagnostic.details["requestedVariant"], "best");

    // A strict-profile asset does not issue.
    let strict_asset = asset_ready(&mut snapback, "user_a", b"strict-bytes");
    let wrong_profile = snapback
        .asset_signed_url_issue(
            &owner,
            &strict_asset,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: Some("primary".to_owned()),
                ttl_ms: None,
                width_px: None,
            },
        )
        .expect_err("strict assets do not issue signed URLs");
    assert_eq!(
        wrong_profile.diagnostic.code,
        "SNAPBACK_ASSET_DELIVERY_PROFILE_UNSUPPORTED"
    );

    // Issue, then serve with the bearer token and no authority at all —
    // that IS the profile's declared semantics.
    let issued = snapback
        .asset_signed_url_issue(
            &owner,
            &asset_id,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: Some("primary".to_owned()),
                ttl_ms: None,
                width_px: None,
            },
        )
        .expect("owner issuance");
    assert!(
        issued
            .url
            .starts_with(&format!("/assets/signed/{asset_id}/primary?token=v1."))
    );
    let defaulted = snapback
        .asset_signed_url_issue(
            &owner,
            &asset_id,
            crate::assets::AssetSignedUrlIssueRequestV1 {
                variant: None,
                ttl_ms: None,
                width_px: None,
            },
        )
        .expect("omitted variant defaults to primary");
    assert_eq!(defaulted.variant, "primary");
    assert!(
        defaulted
            .url
            .starts_with(&format!("/assets/signed/{asset_id}/primary?token=v1."))
    );
    let token = issued.url.split("token=").nth(1).expect("token").to_owned();
    let served = match snapback
        .asset_deliver_signed(&asset_id, "primary", &token, None)
        .expect("bearer serves")
    {
        crate::storage::AssetDeliveryOutcome::Content(delivery) => *delivery,
        other => panic!("expected content, got {other:?}"),
    };
    assert_eq!(asset_window_bytes(&served), bytes);
    assert!(served.cache_control.starts_with("private, max-age="));

    // Range requests ride the same lane; a tampered token is one
    // invalid class; an expired token is 401-shaped.
    let ranged = snapback
        .asset_deliver_signed(&asset_id, "primary", &token, Some("bytes=0-4"))
        .expect("ranged bearer serves");
    match ranged {
        crate::storage::AssetDeliveryOutcome::Content(delivery) => {
            assert!(delivery.partial);
            assert_eq!(delivery.window_length, 5);
        }
        other => panic!("expected partial content, got {other:?}"),
    }
    let mut tampered = token.clone();
    let last = tampered.pop().expect("token has a final character");
    // The 43-char base64url HMAC-SHA256 signature's final group carries
    // only two meaningful bits, so its value set is {A, Q, g, w}:
    // replacing it with a *fixed* character was a no-op one run in four
    // (the recurring "flake" — the untampered token validly served).
    // Swap to a guaranteed-different member of the set.
    tampered.push(if last == 'A' { 'Q' } else { 'A' });
    let invalid = snapback
        .asset_deliver_signed(&asset_id, "primary", &tampered, None)
        .expect_err("tampered token refuses");
    assert_eq!(invalid.diagnostic.code, "SNAPBACK_ASSET_SIGNATURE_INVALID");
    let expired_token = snapback
        .db
        .asset_reads()
        .mint_expired_signed_url_token(&asset_id)
        .expect("expired token minted");
    let expired = snapback
        .asset_deliver_signed(&asset_id, "primary", &expired_token, None)
        .expect_err("expired token refuses");
    assert_eq!(expired.diagnostic.code, "SNAPBACK_ASSET_SIGNATURE_EXPIRED");
}

#[test]
fn asset_signed_url_rotation_and_generation_moves_invalidate() {
    let mut snapback = asset_profile_snapback();
    let asset_id =
        asset_ready_under_intent(&mut snapback, "user_a", b"rotating-bytes", "signedUpload");
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let issue = |snapback: &mut LocalSnapback, owner: &PreparedAuthority| {
        snapback
            .asset_signed_url_issue(
                owner,
                &asset_id,
                crate::assets::AssetSignedUrlIssueRequestV1 {
                    variant: Some("primary".to_owned()),
                    ttl_ms: None,
                    width_px: None,
                },
            )
            .expect("issuance")
            .url
            .split("token=")
            .nth(1)
            .expect("token")
            .to_owned()
    };
    let token = issue(&mut snapback, &owner);

    // Rotation retires every key: the outstanding URL stops validating,
    // a fresh issuance works, and the rotation is receipted without an
    // asset id or key identity.
    snapback.asset_rotate_signing_key().expect("rotation");
    let rotated = snapback
        .asset_deliver_signed(&asset_id, "primary", &token, None)
        .expect_err("rotation invalidates outstanding URLs");
    assert_eq!(rotated.diagnostic.code, "SNAPBACK_ASSET_SIGNATURE_INVALID");
    let fresh = issue(&mut snapback, &owner);
    assert!(matches!(
        snapback
            .asset_deliver_signed(&asset_id, "primary", &fresh, None)
            .expect("fresh issuance serves"),
        crate::storage::AssetDeliveryOutcome::Content(_)
    ));

    // A lifecycle-generation move since issuance invalidates: the
    // signature binds the generation, and validation recomputes against
    // the current one.
    let stale_generation_token = snapback
        .db
        .asset_reads()
        .mint_stale_generation_signed_url_token(&asset_id)
        .expect("stale-generation token minted");
    let stale = snapback
        .asset_deliver_signed(&asset_id, "primary", &stale_generation_token, None)
        .expect_err("generation mismatch refuses");
    assert_eq!(stale.diagnostic.code, "SNAPBACK_ASSET_SIGNATURE_INVALID");

    // Deletion masks the alias entirely on the next request.
    let deleter = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    snapback.asset_delete(&deleter, &asset_id).expect("delete");
    let deleted = snapback
        .asset_deliver_signed(&asset_id, "primary", &fresh, None)
        .expect_err("deleted asset serves nothing");
    assert_eq!(deleted.diagnostic.code, "SNAPBACK_ASSET_UNKNOWN");
}

#[test]
fn asset_public_lane_serves_immutable_and_masks_everything_else() {
    let mut snapback = asset_profile_snapback();
    let bytes = b"public-profile-bytes".to_vec();
    let asset_id = asset_ready_under_intent(&mut snapback, "user_a", &bytes, "publicUpload");

    let served = match snapback
        .asset_deliver_public(&asset_id, "primary", None, None)
        .expect("public serves with no credential")
    {
        crate::storage::AssetDeliveryOutcome::Content(delivery) => *delivery,
        other => panic!("expected content, got {other:?}"),
    };
    assert_eq!(asset_window_bytes(&served), bytes);
    assert_eq!(served.cache_control, "public, max-age=31536000, immutable");
    assert!(served.etag.starts_with("\"r-"));
    let ranged = snapback
        .asset_deliver_public(&asset_id, "primary", Some("bytes=-5"), None)
        .expect("public suffix range serves");
    assert!(matches!(
        ranged,
        crate::storage::AssetDeliveryOutcome::Content(ref delivery) if delivery.partial
    ));

    // Everything non-servable is indistinguishable from unknown: a
    // strict asset, a pending public asset, and a deleted public asset
    // all mask — the public lane is never an existence oracle.
    let strict_asset = asset_ready(&mut snapback, "user_a", b"strict-bytes");
    let masked = snapback
        .asset_deliver_public(&strict_asset, "primary", None, None)
        .expect_err("strict asset masks on the public lane");
    assert_eq!(masked.diagnostic.code, "SNAPBACK_ASSET_UNKNOWN");
    let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let mut pending_request = asset_create_request(Some(4));
    pending_request.intent_id = "app:publicUpload".to_owned();
    pending_request.intent_policy_hash = "sha256:test-policy-publicUpload".to_owned();
    let pending = snapback
        .asset_attempt_create(&creator, pending_request)
        .expect("pending attempt");
    let masked_pending = snapback
        .asset_deliver_public(&pending.task.asset_id, "primary", None, None)
        .expect_err("pending masks on the public lane");
    assert_eq!(masked_pending.diagnostic.code, "SNAPBACK_ASSET_UNKNOWN");
    snapback.asset_delete(&creator, &asset_id).expect("delete");
    let masked_deleted = snapback
        .asset_deliver_public(&asset_id, "primary", None, None)
        .expect_err("delete stops future canonical access");
    assert_eq!(masked_deleted.diagnostic.code, "SNAPBACK_ASSET_UNKNOWN");

    // The declared-profile runtime gate reads the same facts the
    // manifest embeds.
    assert!(LocalSnapback::asset_delivery_profile_declared(
        "private-signed"
    ));
    assert!(LocalSnapback::asset_delivery_profile_declared(
        "public-immutable"
    ));
    assert!(!LocalSnapback::asset_delivery_profile_declared("cdn-magic"));
}

fn asset_deliver_content(
    snapback: &mut LocalSnapback,
    user: &str,
    asset_id: &str,
    variant: &str,
    range: Option<&str>,
) -> SnapbackResult<crate::storage::AssetDelivery> {
    let authority = asset_dev_authority(snapback, user, InvocationSource::HttpQuery);
    match snapback.asset_deliver(&authority, asset_id, variant, range, None, None)? {
        crate::storage::AssetDeliveryOutcome::Content(delivery) => Ok(*delivery),
        crate::storage::AssetDeliveryOutcome::Unsatisfiable { total_length } => {
            Err(SnapbackError::error(
                "TEST_UNSATISFIABLE",
                "assets",
                format!("unsatisfiable over {total_length}"),
            ))
        }
    }
}

fn asset_window_bytes(delivery: &crate::storage::AssetDelivery) -> Vec<u8> {
    delivery
        .store
        .read_chunk(
            crate::assets_store::AssetObjectRef::Blob(&delivery.blob_key),
            delivery.window_start,
            delivery.window_length as usize,
        )
        .expect("window reads")
}

#[test]
fn asset_delivery_serves_full_and_range_windows_with_strict_facts() {
    let mut snapback = asset_test_snapback();
    // The test intent accepts application/octet-stream, so the payload
    // stays unrecognized; the inline branch is covered at the unit
    // level (`forces_attachment_disposition`).
    let bytes: Vec<u8> = b"opaque-payload-window-bytes".to_vec();
    let asset_id = asset_ready(&mut snapback, "user_a", &bytes);

    let full = asset_deliver_content(&mut snapback, "user_a", &asset_id, "primary", None)
        .expect("full delivery");
    assert!(!full.partial);
    assert_eq!(full.total_length, bytes.len() as u64);
    assert_eq!(full.window_length, bytes.len() as u64);
    assert_eq!(full.content_type, "application/octet-stream");
    assert!(full.disposition.starts_with("attachment;"));
    assert!(full.disposition.contains("photo.bin"));
    assert!(full.etag.starts_with("\"r-"));
    assert_eq!(asset_window_bytes(&full), bytes);

    let range = asset_deliver_content(
        &mut snapback,
        "user_a",
        &asset_id,
        "primary",
        Some("bytes=2-5"),
    )
    .expect("range delivery");
    assert!(range.partial);
    assert_eq!(range.window_start, 2);
    assert_eq!(range.window_length, 4);
    assert_eq!(asset_window_bytes(&range), bytes[2..6].to_vec());

    let suffix = asset_deliver_content(
        &mut snapback,
        "user_a",
        &asset_id,
        "primary",
        Some("bytes=-4"),
    )
    .expect("suffix range");
    assert_eq!(suffix.window_start, bytes.len() as u64 - 4);
    assert_eq!(suffix.window_length, 4);

    // Syntactically valid but past the end: 416 with the total, per
    // RFC 9110; the outcome carries what the handler needs.
    let authority = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    match snapback
        .asset_deliver(
            &authority,
            &asset_id,
            "primary",
            Some("bytes=999999-"),
            None,
            None,
        )
        .expect("outcome resolves")
    {
        crate::storage::AssetDeliveryOutcome::Unsatisfiable { total_length } => {
            assert_eq!(total_length, bytes.len() as u64);
        }
        crate::storage::AssetDeliveryOutcome::Content(_) => {
            panic!("range past end must be unsatisfiable")
        }
    }

    // Unknown variants and unknown assets are 404-shaped; foreign
    // callers are denied by the read policy on every request.
    let missing = asset_deliver_content(&mut snapback, "user_a", &asset_id, "thumb", None)
        .expect_err("unknown variant refuses");
    assert_eq!(missing.diagnostic.code, "SNAPBACK_ASSET_VARIANT_UNKNOWN");
    let foreign = asset_deliver_content(&mut snapback, "user_b", &asset_id, "primary", None)
        .expect_err("foreign caller refuses");
    assert_eq!(foreign.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");

    let events = asset_receipt_events(&mut snapback, &asset_id);
    assert!(
        events.iter().filter(|e| *e == "delivery-admitted").count() >= 3,
        "every admitted request receipts: {events:?}"
    );
}

#[test]
fn asset_gc_retires_only_delivery_receipts_after_their_window() {
    let mut snapback = asset_test_snapback();
    let asset_id = asset_ready(&mut snapback, "user_a", b"receipt-retention");
    asset_deliver_content(&mut snapback, "user_a", &asset_id, "primary", None)
        .expect("full delivery");
    asset_deliver_content(
        &mut snapback,
        "user_a",
        &asset_id,
        "primary",
        Some("bytes=0-3"),
    )
    .expect("range delivery");

    let count_event = |snapback: &mut LocalSnapback, event: &str| {
        snapback
            .db
            .asset_reads()
            .receipt_count_for_asset_event(&asset_id, event)
            .expect("receipt count")
    };
    assert_eq!(count_event(&mut snapback, "delivery-admitted"), 2);
    assert_eq!(count_event(&mut snapback, "asset-ready"), 1);

    let report = snapback
        .asset_gc_sweep(now_millis() + crate::assets::ASSET_DELIVERY_RECEIPT_RETENTION_MS + 1)
        .expect("retention sweep");
    assert_eq!(report.delivery_receipts_purged, 2);
    assert_eq!(count_event(&mut snapback, "delivery-admitted"), 0);
    assert_eq!(
        count_event(&mut snapback, "asset-ready"),
        1,
        "lifecycle evidence is not part of delivery retention"
    );
}

#[test]
fn asset_delivery_forces_attachment_for_unrecognized_bytes_and_gates_readiness() {
    let mut snapback = asset_test_snapback();
    // No magic prefix: detection yields application/octet-stream, which
    // never serves inline (nosniff rides in the response headers).
    let asset_id = asset_ready(&mut snapback, "user_a", b"opaque-unrecognized-bytes");
    let delivery = asset_deliver_content(&mut snapback, "user_a", &asset_id, "primary", None)
        .expect("delivers");
    assert_eq!(delivery.content_type, "application/octet-stream");
    assert!(delivery.disposition.starts_with("attachment;"));
    assert!(delivery.disposition.contains("photo.bin"));

    // A pending asset has no deliverable bytes yet.
    let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let pending = snapback
        .asset_attempt_create(&creator, asset_create_request(Some(8)))
        .expect("pending attempt");
    let refused = asset_deliver_content(
        &mut snapback,
        "user_a",
        &pending.task.asset_id,
        "primary",
        None,
    )
    .expect_err("pending refuses");
    assert_eq!(refused.diagnostic.code, "SNAPBACK_ASSET_NOT_READY");
}

#[test]
fn asset_delete_cascade_is_exact_on_shared_and_unshared_blobs() {
    let mut snapback = asset_test_snapback();
    let shared_bytes = b"dedup-shared-window".to_vec();
    let asset_a = asset_ready(&mut snapback, "user_a", &shared_bytes);
    let asset_b = asset_ready(&mut snapback, "user_a", &shared_bytes);
    let asset_c = asset_ready(&mut snapback, "user_a", b"unshared-window");

    let settled_before = snapback
        .db
        .asset_reads()
        .accounting("local-app")
        .expect("accounting")
        .settled_bytes;

    // Deleting A: the shared blob keeps B's reference; B still delivers
    // through its own alias (URL identity under dedup).
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    snapback.asset_delete(&owner, &asset_a).expect("delete a");
    let (availability, blob_refs): (String, u64) = snapback
        .db
        .asset_reads()
        .post_delete_facts(&asset_a)
        .expect("post-delete facts");
    assert_eq!(availability, "deleted");
    // Two blobs remain (shared + unshared); assert the shared one
    // dropped to exactly one reference — the primary counted once.
    let _ = blob_refs;
    let shared_refs: u64 = snapback
        .db
        .asset_reads()
        .highest_live_refcount()
        .expect("shared refcount");
    assert_eq!(shared_refs, 1, "shared blob keeps exactly B's reference");
    asset_deliver_content(&mut snapback, "user_a", &asset_b, "primary", None)
        .expect("B still delivers after A's deletion");

    // Quota released at tombstone commit: settled usage dropped by
    // exactly A's charge (the minimum accounting unit here).
    let settled_after = snapback
        .db
        .asset_reads()
        .accounting("local-app")
        .expect("accounting")
        .settled_bytes;
    assert_eq!(
        settled_before - settled_after,
        crate::assets::ASSET_MIN_ACCOUNTING_UNIT_BYTES,
        "one charge released, primary counted exactly once"
    );

    // Deleting C zero-references its blob; the sweep condemns, deletes
    // the object, drops the row — and never touches the shared blob.
    snapback.asset_delete(&owner, &asset_c).expect("delete c");
    let far_future = now_millis() + crate::assets::ASSET_BLOB_RETENTION_MS + 1000;
    let report = snapback.asset_gc_sweep(far_future).expect("sweep");
    assert_eq!(report.blobs_condemned, 1);
    assert_eq!(report.blob_objects_deleted, 1);
    assert_eq!(report.blob_rows_removed, 1);
    asset_deliver_content(&mut snapback, "user_a", &asset_b, "primary", None)
        .expect("B survives blob GC of C");
    // Deletion denies the next request outright.
    let gone = asset_deliver_content(&mut snapback, "user_a", &asset_a, "primary", None)
        .expect_err("deleted asset serves nothing");
    assert_eq!(gone.diagnostic.code, "SNAPBACK_ASSET_UNKNOWN");
}

#[test]
fn asset_delete_refuses_foreign_callers_references_and_recovers_from_crash() {
    let mut snapback = asset_reference_snapback();
    let asset_id = asset_ready(&mut snapback, "user_a", b"referenced-bytes");

    // Foreign caller: denied before any cascade step.
    let foreign = asset_dev_authority(&snapback, "user_b", InvocationSource::HttpQuery);
    let refused = snapback
        .asset_delete(&foreign, &asset_id)
        .expect_err("foreign delete refuses");
    assert_eq!(refused.diagnostic.code, "SNAPBACK_ASSET_FORBIDDEN");

    // While a typed edge remains, explicit delete refuses.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Insert {
            table: "posts".to_owned(),
            id: "post_ref".to_owned(),
            values: serde_json::Map::from_iter([
                ("title".to_owned(), json!("holds a reference")),
                ("photo".to_owned(), json!(asset_id.clone())),
            ]),
        }],
        vec![crate::assets::AssetAttachmentAdmission {
            asset_id: asset_id.clone(),
            upload: Some("avatarUpload".to_owned()),
        }],
    )
    .expect("attach commits");
    let owner = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let referenced = snapback
        .asset_delete(&owner, &asset_id)
        .expect_err("referenced delete refuses");
    assert_eq!(referenced.diagnostic.code, "SNAPBACK_ASSET_REFERENCED");

    // Clearing the field removes the edge; a crash mid-cascade rolls
    // the whole transaction back — nothing half-deleted survives.
    asset_handler_commit(
        &mut snapback,
        "user_a",
        vec![crate::storage::BufferedWrite::Patch {
            table: "posts".to_owned(),
            id: "post_ref".to_owned(),
            values: serde_json::Map::from_iter([("photo".to_owned(), Value::Null)]),
        }],
        Vec::new(),
    )
    .expect("clear commits");
    let crashed = snapback
        .asset_delete_inner(&owner, &asset_id, true)
        .expect_err("injected crash");
    assert_eq!(crashed.diagnostic.code, "SNAPBACK_ASSET_TEST_CRASH");
    let (availability, rendition_state) = snapback
        .db
        .asset_reads()
        .availability_and_rendition_state(&asset_id)
        .expect("facts");
    assert_eq!(
        availability,
        json!("ready"),
        "crash rolled the cascade back"
    );
    assert_eq!(rendition_state, json!("ready"));

    // The retried delete completes and is idempotent thereafter.
    snapback.asset_delete(&owner, &asset_id).expect("delete");
    let again = snapback
        .asset_delete(&owner, &asset_id)
        .expect("idempotent delete");
    assert_eq!(again["availability"], json!("deleted"));
}

#[test]
fn asset_gc_reclaims_expired_attempts_pending_assets_orphans_and_tombstones() {
    let mut snapback = asset_test_snapback();
    let creator = asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let created = snapback
        .asset_attempt_create(&creator, asset_create_request(Some(16)))
        .expect("attempt");
    let store = snapback.asset_store().expect("store");
    // A stray staging file no attempt owns — a crash leftover.
    let orphan_key = crate::assets::AssetFsStore::new_opaque_key();
    std::fs::write(store.staging_path(&orphan_key).expect("path"), b"orphan")
        .expect("orphan written");

    let after_grace = now_millis()
        + crate::assets::ASSET_ATTEMPT_TTL_MS.max(crate::assets::ASSET_PENDING_GRACE_MS)
        + 1000;
    let report = snapback.asset_gc_sweep(after_grace).expect("sweep");
    assert_eq!(report.expired_attempts, 1, "overdue attempt expired");
    assert!(report.staging_orphans_removed >= 1, "orphan removed");
    assert_eq!(report.pending_reclaimed, 1, "pending asset reclaimed");
    let events = asset_receipt_events(&mut snapback, &created.task.asset_id);
    assert!(events.contains(&"attempt-expired".to_owned()));
    assert!(events.contains(&"gc-reclaimed".to_owned()));
    assert!(events.contains(&"asset-deleted".to_owned()));

    // Past tombstone retention, the rows purge; receipts remain.
    let after_retention = after_grace + crate::assets::ASSET_TOMBSTONE_RETENTION_MS + 1000;
    let report = snapback.asset_gc_sweep(after_retention).expect("sweep 2");
    assert_eq!(report.tombstones_purged, 1);
    let row_count: u64 = snapback
        .db
        .asset_reads()
        .record_count_by_id(&created.task.asset_id)
        .expect("count");
    assert_eq!(row_count, 0, "tombstone purged");
    assert!(
        !asset_receipt_events(&mut snapback, &created.task.asset_id).is_empty(),
        "receipts outlive the purged rows as evidence"
    );
}

#[test]
fn sessions_cold_start_stream_preflight_tracks_process_egress() {
    const CHILD_CASE: &str = "SNAPBACK_TEST_SESSIONS_STREAM_PREFLIGHT_CASE";

    if let Ok(case) = std::env::var(CHILD_CASE) {
        let outbound_enabled = case == "enabled";
        assert_eq!(
            crate::runtime::outbound_actions_enabled(),
            outbound_enabled,
            "child process must exercise its requested live egress fact"
        );

        let (schema, mut functions) = auth_artifact_pair(AuthMode::Sessions, 'd');
        let mut stream_action = FunctionDefinition::new(
            "streamRequiring",
            FunctionKind::Action,
            FunctionRuntime::HostPlan(HandlerPlan::Action(ActionPlan {
                steps: Vec::new(),
                return_value: None,
            })),
        );
        stream_action.required_capabilities = vec!["bounded_response_stream_v1".to_owned()];
        functions.functions.push(stream_action);
        let artifacts = StartupArtifacts {
            format_version: STARTUP_ARTIFACT_FORMAT_VERSION,
            schema,
            functions,
            seed: None,
        };

        let mut snapback = LocalSnapback::memory().expect("memory sessions preflight");
        let before = snapback
            .auth_database_mut()
            .auth_mode_snapshot()
            .expect("initial auth mode");
        let result = snapback.preflight_auth_artifacts(&artifacts, AuthMode::Sessions);

        if outbound_enabled {
            result.expect(
                    "an exact process with outbound actions enabled must admit the bounded stream requirement",
                );
        } else {
            let error = result.expect_err(
                    "an exact process with outbound actions disabled must refuse the bounded stream requirement",
                );
            assert_eq!(error.diagnostic.code, "SNAPBACK_CAPABILITY_UNSUPPORTED");
            assert_eq!(
                error.diagnostic.details["capability"],
                "bounded_response_stream_v1"
            );
        }
        assert_eq!(
            snapback
                .auth_database_mut()
                .auth_mode_snapshot()
                .expect("post-preflight auth mode"),
            before,
            "preflight must remain effectless in both capability arms"
        );
        assert!(
            snapback.function_kind("streamRequiring").is_none(),
            "preflight must not publish the candidate function"
        );
        return;
    }

    // Environment mutation is process-global. Exercise each live process
    // fact in its own child test process so this regression cannot race
    // unrelated tests that require the default-deny egress posture.
    //
    // @ref LLP 0058#complete-candidate-pair-preflight — both children
    // submit the same complete sessions pair before any effect.
    // @ref LLP 0076#target-contract — support is true iff that exact
    // child process enabled outbound actions.
    for outbound_enabled in [false, true] {
        let mut command =
            std::process::Command::new(std::env::current_exe().expect("current test binary"));
        command
            .arg("sessions_cold_start_stream_preflight_tracks_process_egress")
            .arg("--nocapture")
            .arg("--test-threads=1")
            .env(
                CHILD_CASE,
                if outbound_enabled {
                    "enabled"
                } else {
                    "disabled"
                },
            )
            .env_remove("SNAPBACK_OUTBOUND_ACTIONS");
        if outbound_enabled {
            command.env("SNAPBACK_OUTBOUND_ACTIONS", "1");
        }
        let output = command.output().expect("run isolated child test");
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            output.status.success() && stdout.contains("1 passed"),
            "{} child failed:\nstdout:\n{}\nstderr:\n{}",
            if outbound_enabled {
                "enabled"
            } else {
                "disabled"
            },
            stdout,
            stderr,
        );
    }
}

#[test]
fn network_one_half_update_uses_only_same_boot_preflighted_sibling() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("one-half.sqlite3");
    let (schema, functions) = auth_artifact_pair(AuthMode::Dev, 'a');
    let mut snapback = LocalSnapback::open(&path).unwrap();
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Dev,
            Some(schema),
            Some(functions.clone()),
            None,
        )
        .unwrap();
    snapback.commit_auth_provision(prepared, "test").unwrap();

    let (mut updated_schema, _) = auth_artifact_pair(AuthMode::Dev, 'b');
    // Keep the pair-level input identity equal to the loaded sibling.
    updated_schema.inputs_hash = functions.inputs_hash.clone();
    let prepared = snapback
        .prepare_auth_provision(EnsureAppMode::Dev, Some(updated_schema), None, None)
        .unwrap();
    let (outcome, _) = snapback.commit_auth_provision(prepared, "test").unwrap();
    assert_eq!(outcome.schema, "provisioned");
    assert_eq!(outcome.functions, "matched");
    drop(snapback);

    let mut reopened = LocalSnapback::open(&path).unwrap();
    let (another_schema, _) = auth_artifact_pair(AuthMode::Dev, 'c');
    let error = reopened
        .prepare_auth_provision(EnsureAppMode::Dev, Some(another_schema), None, None)
        .unwrap_err();
    assert_eq!(error.diagnostic.code, "SNAPBACK_CAPABILITY_UNSUPPORTED");
}

#[test]
fn authorization_reservation_data_and_auth_frontiers_share_one_snapshot() {
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("authorization-pair.sqlite3");
    let mut reader = LocalSnapback::open(&path).expect("open reader");
    reader
        .apply_schema(SchemaManifest {
            tables: vec![TableManifest {
                name: "permissions".to_owned(),
                fields: vec![FieldManifest {
                    name: "subject".to_owned(),
                    field_type: FieldType::String,
                    optional: false,
                }],
                indexes: Vec::new(),
                syncable: true,
                permission_backing: true,
                permission_fields: None,
                search_indexes: Vec::new(),
                vector_indexes: Vec::new(),
                search_live_limits: None,
                membership: None,
                authority_profile: None,
                asset_sharing: None,
                visibility: None,
                history: None,
            }],
            ..SchemaManifest::default()
        })
        .expect("apply permission schema");
    let baseline = reader
        .authorization_reservation_snapshot()
        .expect("baseline authorization pair");

    let (reached_tx, reached_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let _hook =
        crate::storage::set_storage_read_snapshot_debug_hook(&reader.db, reached_tx, release_rx);
    let lane = reader.read_lane();
    let writer = std::thread::spawn(move || {
        reached_rx
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("reader pins the predecessor data head");
        reader
            .db
            .schema_seed()
            .seed_with_authorization(SeedData {
                tables: BTreeMap::from([(
                    "permissions".to_owned(),
                    vec![Map::from_iter([
                        ("_id".to_owned(), json!("permission")),
                        ("subject".to_owned(), json!("user")),
                    ])],
                )]),
            })
            .expect("commit authorization-affecting write");
        let successor = reader
            .authorization_reservation_snapshot()
            .expect("successor authorization pair");
        release_tx.send(()).expect("release pinned reader");
        successor
    });

    let pinned = lane
        .authorization_reservation_snapshot_for_test()
        .expect("snapshot-bound authorization pair");
    let successor = writer.join().expect("writer joins");
    assert_eq!(pinned, baseline);
    assert_eq!(successor.0, baseline.0 + 1);
    assert_eq!(successor.1.incarnation, baseline.1.incarnation);
    assert_eq!(successor.1.epoch, baseline.1.epoch + 1);
    assert_eq!(
        lane.authorization_reservation_snapshot_for_test().unwrap(),
        successor
    );
}

fn sessions_activation_pair(
    bundle_marker: char,
    hide_rows: bool,
) -> (SchemaManifest, FunctionManifest) {
    let (mut schema, mut functions) = auth_artifact_pair(AuthMode::Sessions, 'a');
    schema.tables = vec![TableManifest {
        name: "items".to_owned(),
        fields: vec![FieldManifest {
            name: "value".to_owned(),
            field_type: FieldType::String,
            optional: false,
        }],
        indexes: Vec::new(),
        syncable: true,
        permission_backing: false,
        permission_fields: None,
        search_indexes: Vec::new(),
        vector_indexes: Vec::new(),
        search_live_limits: None,
        membership: None,
        authority_profile: None,
        asset_sharing: None,
        visibility: Some(crate::manifest::TableVisibilityV1::PublicRead),
        history: None,
    }];
    functions.bundle_hash = Some(format!(
        "{}{}",
        FUNCTION_V1_PREFIX,
        bundle_marker.to_string().repeat(64)
    ));
    functions.functions = vec![FunctionDefinition::new(
        "listItems",
        FunctionKind::LiveQuery,
        FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
            table_visibility: None,
            table: "items".to_owned(),
            filters: hide_rows
                .then(|| FilterExpr {
                    field: "value".to_owned(),
                    op: FilterOp::Eq,
                    value: ValueExpr::Literal(json!("never-visible")),
                })
                .into_iter()
                .collect(),
            order: Vec::new(),
            limit: None,
            membership_filters: Vec::new(),
            indexed_by: None,
        })),
    )];
    (schema, functions)
}

// @ref LLP 0081#4-execution-journaling-and-crash-recovery — no
//   pre-publication baseline replays through the raised floor: under a
//   successor-only publication an offline mutation whose read baseline
//   predates the floor receives the stable resync-before-replay
//   refusal; a dual-compatible publication keeps the ordinary rules.
#[test]
fn successor_only_publication_gates_stale_replay_baselines() {
    let build = |posture: crate::migration::CompatibilityPosture| {
        let (schema, functions, _plan) = projection_fixture(5);
        let mut snapback = LocalSnapback::memory().expect("memory replay fixture");
        snapback.apply_schema(schema).expect("apply schema");
        let diagnostics = snapback.load_functions(functions);
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "{diagnostics:?}"
        );
        snapback
            .invoke_mutation(
                "addAuthor",
                HandlerInput {
                    args: json!({ "slug": "ada", "name": "Ada" }),
                    ..HandlerInput::default()
                },
            )
            .expect("seed author");
        let row = snapback
            .db
            .query_reads_read()
            .query(
                &QueryPlan {
                    table_visibility: None,
                    table: "authors".to_owned(),
                    filters: Vec::new(),
                    membership_filters: Vec::new(),
                    order: Vec::new(),
                    limit: None,
                    indexed_by: None,
                },
                &HandlerInput::default(),
            )
            .expect("read author")
            .rows[0]
            .clone();
        let baseline = crate::manifest::ReadDependency {
            table: "authors".to_owned(),
            id: row["_id"].as_str().expect("id").to_owned(),
            version: row["_version"].as_u64().expect("version"),
        };
        crate::storage::publish_schema_transition_for_test(
            &mut snapback.db,
            posture,
            &"p".repeat(64),
        );
        (snapback, baseline, row)
    };
    // Same fixture with a pre-publication change to the row after the
    // baseline capture: the history the raised floor then erases.
    let build_with_interim = |posture: crate::migration::CompatibilityPosture| {
        let (schema, functions, _plan) = projection_fixture(5);
        let mut snapback = LocalSnapback::memory().expect("memory replay fixture");
        snapback.apply_schema(schema).expect("apply schema");
        let diagnostics = snapback.load_functions(functions);
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "{diagnostics:?}"
        );
        snapback
            .invoke_mutation(
                "addAuthor",
                HandlerInput {
                    args: json!({ "slug": "ada", "name": "Ada" }),
                    ..HandlerInput::default()
                },
            )
            .expect("seed author");
        let row = snapback
            .db
            .query_reads_read()
            .query(
                &QueryPlan {
                    table_visibility: None,
                    table: "authors".to_owned(),
                    filters: Vec::new(),
                    membership_filters: Vec::new(),
                    order: Vec::new(),
                    limit: None,
                    indexed_by: None,
                },
                &HandlerInput::default(),
            )
            .expect("read author")
            .rows[0]
            .clone();
        let baseline = crate::manifest::ReadDependency {
            table: "authors".to_owned(),
            id: row["_id"].as_str().expect("id").to_owned(),
            version: row["_version"].as_u64().expect("version"),
        };
        snapback
            .invoke_mutation(
                "renameAuthor",
                HandlerInput {
                    args: json!({ "id": baseline.id, "name": "Interim" }),
                    ..HandlerInput::default()
                },
            )
            .expect("interim rename before publication");
        crate::storage::publish_schema_transition_for_test(
            &mut snapback.db,
            posture,
            &"p".repeat(64),
        );
        (snapback, baseline, row)
    };

    // Successor-only: a pre-floor baseline whose row has since changed
    // is un-rebasable (the journal below the floor is gone) and
    // refuses, stable. The intervening change happens before
    // publication, so it is exactly the history the floor erased.
    let (mut snapback, baseline, row) =
        build_with_interim(crate::migration::CompatibilityPosture::SuccessorOnly);
    let error = snapback
        .invoke_mutation(
            "renameAuthor",
            HandlerInput {
                args: json!({ "id": baseline.id, "name": "Ada Lovelace" }),
                read_set: vec![baseline.clone()],
                ..HandlerInput::default()
            },
        )
        .expect_err("stale changed-row baseline must refuse under successor-only");
    assert_eq!(error.diagnostic.code, "SNAPBACK_MIGRATION_RESYNC_REQUIRED");
    assert_eq!(
        snapback
            .db
            .query_reads_read()
            .get("authors", row["_id"].as_str().expect("id"))
            .expect("read back")
            .expect("row survives")["name"],
        json!("Interim"),
        "the refused replay wrote nothing",
    );

    // Successor-only, untouched row: the pre-publication capture of a
    // row the migration did not change is byte-identical to a fresh
    // post-resync capture — it passes, or every compatible client's
    // post-resnapshot replay would refuse forever.
    let (mut snapback, baseline, row) =
        build(crate::migration::CompatibilityPosture::SuccessorOnly);
    snapback
        .invoke_mutation(
            "renameAuthor",
            HandlerInput {
                args: json!({ "id": baseline.id, "name": "Ada Lovelace" }),
                read_set: vec![baseline],
                ..HandlerInput::default()
            },
        )
        .expect("untouched-row baseline replays under successor-only");
    assert_eq!(
        snapback
            .db
            .query_reads_read()
            .get("authors", row["_id"].as_str().expect("id"))
            .expect("read back")
            .expect("row survives")["name"],
        json!("Ada Lovelace"),
    );

    // Dual-compatible: ordinary conflict rules apply — the unchanged
    // baseline validates and the replay commits.
    let (mut snapback, baseline, row) =
        build(crate::migration::CompatibilityPosture::DualCompatible);
    snapback
        .invoke_mutation(
            "renameAuthor",
            HandlerInput {
                args: json!({ "id": baseline.id, "name": "Ada Lovelace" }),
                read_set: vec![baseline],
                ..HandlerInput::default()
            },
        )
        .expect("dual-compatible replay admits");
    assert_eq!(
        snapback
            .db
            .query_reads_read()
            .get("authors", row["_id"].as_str().expect("id"))
            .expect("read back")
            .expect("row survives")["name"],
        json!("Ada Lovelace"),
    );
}

// @ref LLP 0093#mutation-wire-artifact-identity-amendment--2026-08-10 — a
//   finite v1 mutation carrying no read baseline must identify the build-time
//   schema generation before it can cross a successor-only migration floor.
#[test]
fn successor_only_publication_gates_blind_mutation_artifact_generation() {
    fn stage_blind(
        snapback: &mut LocalSnapback,
        id: &str,
        name: &str,
        expected_generation: Option<&ArtifactGeneration>,
        wire_version: Option<&str>,
    ) -> SnapbackResult<(
        crate::storage::AuthorizationCommitPreflight,
        StagedRecordedMutation,
    )> {
        let input = HandlerInput {
            args: json!({ "id": id, "name": name }),
            ..HandlerInput::default()
        };
        let authority = InvocationGate::prepare_dev_input(
            InvocationSource::LocalMutation,
            ServerProfile::Test,
            &input,
        )?;
        snapback.stage_recorded_authorization_mutation_with_wire_version(
            "renameAuthor",
            input,
            None,
            None,
            &[],
            "test",
            authority,
            expected_generation,
            None,
            MutationSettlement::default(),
            None,
            wire_version,
        )
    }

    let (schema, functions, _plan) = projection_fixture(5);
    let mut snapback = LocalSnapback::memory().expect("memory blind-write fixture");
    snapback.apply_schema(schema).expect("apply schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "{diagnostics:?}"
    );
    snapback
        .invoke_mutation(
            "addAuthor",
            HandlerInput {
                args: json!({ "slug": "ada", "name": "Ada" }),
                ..HandlerInput::default()
            },
        )
        .expect("seed author");
    let row = snapback
        .db
        .query_reads_read()
        .query(
            &QueryPlan {
                table_visibility: None,
                table: "authors".to_owned(),
                filters: Vec::new(),
                membership_filters: Vec::new(),
                order: Vec::new(),
                limit: None,
                indexed_by: None,
            },
            &HandlerInput::default(),
        )
        .expect("read author")
        .rows[0]
        .clone();
    let author_id = row["_id"].as_str().expect("author id").to_owned();
    let predecessor_schema_hash = "predecessor-schema-hash".to_owned();
    crate::storage::publish_schema_transition_for_test(
        &mut snapback.db,
        crate::migration::CompatibilityPosture::SuccessorOnly,
        &predecessor_schema_hash,
    );
    let active_schema_hash = snapback
        .db
        .latest_schema_transition()
        .expect("read transition")
        .expect("published transition")
        .body
        .successor_schema_hash;
    let generation = |schema_hash: String| ArtifactGeneration {
        schema_version: "snapback.v1".to_owned(),
        app_id: "migration-floor-test".to_owned(),
        schema_hash,
        bundle_hash: "bundle-build-hash".to_owned(),
        inputs_hash: "inputs-build-hash".to_owned(),
    };

    let error = match stage_blind(
        &mut snapback,
        &author_id,
        "missing identity",
        None,
        Some(crate::wire_version::WIRE_VERSION_V1),
    ) {
        Ok(_) => panic!("negotiated blind mutation must carry artifact identity"),
        Err(error) => error,
    };
    assert_eq!(error.diagnostic.code, "SNAPBACK_MIGRATION_UPGRADE_REQUIRED");

    let predecessor_generation = generation(predecessor_schema_hash);
    let error = match stage_blind(
        &mut snapback,
        &author_id,
        "predecessor identity",
        Some(&predecessor_generation),
        Some(crate::wire_version::WIRE_VERSION_V1),
    ) {
        Ok(_) => panic!("predecessor blind mutation must refuse at the floor"),
        Err(error) => error,
    };
    assert_eq!(error.diagnostic.code, "SNAPBACK_MIGRATION_UPGRADE_REQUIRED");
    assert_eq!(
        snapback
            .db
            .query_reads_read()
            .get("authors", &author_id)
            .expect("read back")
            .expect("author survives")["name"],
        json!("Ada"),
        "identity refusals happen before any write",
    );

    let successor_generation = generation(active_schema_hash);
    let (preflight, staged) = stage_blind(
        &mut snapback,
        &author_id,
        "successor identity",
        Some(&successor_generation),
        Some(crate::wire_version::WIRE_VERSION_V1),
    )
    .expect("active build identity stages");
    snapback
        .try_with_direct_authorization_write(preflight, move |snapback| {
            snapback.commit_staged_recorded_authorization_mutation(staged)
        })
        .expect("reserve successor write")
        .require_finalized()
        .expect("finalize successor write")
        .expect("record successor write")
        .0
        .expect("commit successor write");

    let (preflight, staged) = stage_blind(
        &mut snapback,
        &author_id,
        "legacy compatibility",
        None,
        None,
    )
    .expect("offerless legacy blind mutation remains compatible");
    snapback
        .try_with_direct_authorization_write(preflight, move |snapback| {
            snapback.commit_staged_recorded_authorization_mutation(staged)
        })
        .expect("reserve legacy write")
        .require_finalized()
        .expect("finalize legacy write")
        .expect("record legacy write")
        .0
        .expect("commit legacy write");
}

// @ref LLP 0081#6-compatibility-and-deployment-ordering — the
//   quarantined offline mutation SETTLES through resync-before-replay:
//   the stale-baseline replay is refused recording nothing (the id
//   stays fresh), the resynced replay of the same clientMutationId
//   settles exactly once, a duplicate of the settled form returns the
//   recorded result without reapplying, and the discarded stale form
//   can never double-apply after settlement. This witness drives the
//   same primitives the staged server path composes (the recorded-
//   result pre-check plus the idempotent executor).
#[test]
fn quarantined_offline_mutation_settles_through_resync_before_replay() {
    use crate::storage::ClientMutationIdentity;
    let (schema, functions, _plan) = projection_fixture(5);
    let mut snapback = LocalSnapback::memory().expect("memory settlement fixture");
    snapback.apply_schema(schema).expect("apply schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "{diagnostics:?}"
    );
    snapback
        .invoke_mutation(
            "addAuthor",
            HandlerInput {
                args: json!({ "slug": "ada", "name": "Ada" }),
                ..HandlerInput::default()
            },
        )
        .expect("seed author");
    let read_author = |snapback: &LocalSnapback| {
        snapback
            .db
            .query_reads_read()
            .query(
                &QueryPlan {
                    table_visibility: None,
                    table: "authors".to_owned(),
                    filters: Vec::new(),
                    membership_filters: Vec::new(),
                    order: Vec::new(),
                    limit: None,
                    indexed_by: None,
                },
                &HandlerInput::default(),
            )
            .expect("read author")
            .rows[0]
            .clone()
    };
    let row = read_author(&snapback);
    let author_id = row["_id"].as_str().expect("id").to_owned();
    let baseline = |row: &Value| crate::manifest::ReadDependency {
        table: "authors".to_owned(),
        id: row["_id"].as_str().expect("id").to_owned(),
        version: row["_version"].as_u64().expect("version"),
    };
    let rename_plan = MutationPlan {
        owner_write_checks: Vec::new(),
        steps: vec![MutationStep::Patch {
            table: "authors".to_owned(),
            id: ValueExpr::Arg("id".to_owned()),
            values: BTreeMap::from([("name".to_owned(), ValueExpr::Arg("name".to_owned()))]),
        }],
        return_value: None,
    };
    // The client-custodied offline mutation: captured pre-publication.
    let stale_input = HandlerInput {
        args: json!({ "id": author_id, "name": "Ada Lovelace" }),
        read_set: vec![baseline(&row)],
        ..HandlerInput::default()
    };
    let stale_identity = ClientMutationIdentity::new("cm-offline-1", "renameAuthor", &stale_input);

    // History the floor will erase: the row changes after the offline
    // capture and before publication, making the stale baseline
    // un-rebasable rather than merely old.
    snapback
        .invoke_mutation(
            "renameAuthor",
            HandlerInput {
                args: json!({ "id": author_id, "name": "Interim" }),
                ..HandlerInput::default()
            },
        )
        .expect("interim rename before publication");

    crate::storage::publish_schema_transition_for_test(
        &mut snapback.db,
        crate::migration::CompatibilityPosture::SuccessorOnly,
        &"p".repeat(64),
    );

    // 1. The stale-baseline replay refuses with the stable code and
    //    records nothing — the id is not poisoned by the refusal.
    let error = snapback
        .db
        .mutation_writes()
        .execute_mutation_idempotent(&rename_plan, &stale_input, &stale_identity)
        .expect_err("stale baseline refuses under successor-only");
    assert_eq!(error.diagnostic.code, "SNAPBACK_MIGRATION_RESYNC_REQUIRED");
    assert!(
        snapback
            .db
            .settlement_read()
            .client_mutation_result(&stale_identity)
            .expect("lookup")
            .is_none(),
        "a refused replay must not consume the client mutation id",
    );
    assert_eq!(read_author(&snapback)["name"], json!("Interim"));

    // 2. Resync-before-replay: the client takes a successor snapshot,
    //    re-baselines the SAME logical mutation under the SAME
    //    clientMutationId, and the replay settles.
    let resynced_row = read_author(&snapback);
    let resynced_input = HandlerInput {
        args: json!({ "id": author_id, "name": "Ada Lovelace" }),
        read_set: vec![baseline(&resynced_row)],
        ..HandlerInput::default()
    };
    let resynced_identity =
        ClientMutationIdentity::new("cm-offline-1", "renameAuthor", &resynced_input);
    let settled = snapback
        .db
        .mutation_writes()
        .execute_mutation_idempotent(&rename_plan, &resynced_input, &resynced_identity)
        .expect("resynced replay settles");
    assert_eq!(read_author(&snapback)["name"], json!("Ada Lovelace"));

    // 3. Exactly once: a duplicate of the settled form returns the
    //    recorded result (the staged server path's pre-check) and the
    //    row does not move.
    let version_after = read_author(&snapback)["_version"]
        .as_u64()
        .expect("version");
    let recorded = snapback
        .db
        .settlement_read()
        .client_mutation_result(&resynced_identity)
        .expect("recorded lookup")
        .expect("settled result is recorded");
    assert_eq!(recorded.version, settled.output.version);
    assert_eq!(
        read_author(&snapback)["_version"]
            .as_u64()
            .expect("version"),
        version_after,
        "the duplicate replay applied nothing",
    );

    // 4. The discarded stale form can never double-apply: after
    //    settlement, presenting the ORIGINAL payload under the same id
    //    refuses as a reused id, not a second application.
    let error = snapback
        .db
        .settlement_read()
        .client_mutation_result(&stale_identity)
        .expect_err("the stale form is refused after settlement");
    assert_eq!(error.diagnostic.code, "SNAPBACK_CLIENT_MUTATION_ID_REUSED");
    assert_eq!(read_author(&snapback)["name"], json!("Ada Lovelace"));
}

// @ref LLP 0081#4-execution-journaling-and-crash-recovery — the
//   publication consequence on retained live state: every subscription
//   is disposed with a clear-retained resync; no predecessor result or
//   retained row survives the boundary.
#[test]
fn publication_retires_live_subscriptions_with_clear_retained_resync() {
    let (schema, functions) = relational_live_fixture_functions(10);
    let mut snapback = LocalSnapback::memory().expect("memory publication fixture");
    snapback.apply_schema(schema).expect("apply schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "{diagnostics:?}"
    );
    snapback
        .subscribe_live(
            "booksWithAuthors",
            LiveSubscribeInput {
                connection_id: "conn-pub".to_owned(),
                input: HandlerInput {
                    auth: AuthInput {
                        user_id: Some("user-a".to_owned()),
                        ..AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
                authorization_namespace: None,
                supersedes: None,
                resume_from_token: None,
            },
        )
        .expect("subscribe");
    assert_eq!(snapback.subscriptions.len(), 1);

    snapback
        .retire_live_subscriptions_for_publication()
        .expect("retire for publication");
    assert!(
        snapback.subscriptions.is_empty(),
        "no subscription survives"
    );
    let envelopes = rqs_drained_envelopes(&mut snapback, "conn-pub");
    let resync = envelopes
        .iter()
        .find(|envelope| envelope["kind"] == "resync_required")
        .expect("resync envelope delivered");
    assert_eq!(resync["reason"], json!("schema_publication"));
    assert_eq!(resync["clear_retained"], json!(true));
}

// @ref LLP 0081#4-execution-journaling-and-crash-recovery — what
//   publishes with the storage is the staged generated-function and
//   schema identity set: publication refuses when the serving function
//   set does not bind against the successor schema.
#[test]
fn publication_refuses_a_function_set_that_does_not_bind_the_successor() {
    use crate::migration::{
        CompatibilityPosture, MIGRATION_APPROVAL_SCHEMA_VERSION, MIGRATION_PLAN_SCHEMA_VERSION,
        MigrationApprovalV1, MigrationAudienceV1, MigrationBackupRequirement, MigrationCeilings,
        MigrationConstants, MigrationExecutionStrategy, MigrationExpectedOutput, MigrationIntent,
        MigrationPlanArtifactV1, MigrationPlanBody, MigrationProof, MigrationProofMethod,
        RetainedWorkPosture, derive_intents, derive_plan_steps, new_operation_id,
    };
    let field = |name: &str, optional: bool| crate::manifest::FieldManifest {
        name: name.to_owned(),
        field_type: crate::manifest::FieldType::String,
        optional,
    };
    let schema_of = |fields: Vec<crate::manifest::FieldManifest>| SchemaManifest {
        tables: vec![crate::manifest::TableManifest {
            name: "notes".to_owned(),
            fields,
            indexes: Vec::new(),
            syncable: true,
            permission_backing: false,
            permission_fields: None,
            search_indexes: Vec::new(),
            vector_indexes: Vec::new(),
            search_live_limits: None,
            membership: None,
            authority_profile: None,
            asset_sharing: None,
            visibility: None,
            history: None,
        }],
        ..SchemaManifest::default()
    };
    let predecessor = schema_of(vec![field("body", false), field("extra", true)]);
    let successor = schema_of(vec![field("body", false)]);

    let mut snapback = LocalSnapback::memory().expect("memory fixture");
    snapback
        .apply_schema(predecessor.clone())
        .expect("apply schema");
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![FunctionDefinition::new(
            "listByExtra",
            FunctionKind::Query,
            FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
                table_visibility: None,
                table: "notes".to_owned(),
                filters: vec![FilterExpr {
                    field: "extra".to_owned(),
                    op: FilterOp::Eq,
                    value: ValueExpr::Literal(json!("x")),
                }],
                membership_filters: Vec::new(),
                order: Vec::new(),
                limit: None,
                indexed_by: None,
            })),
        )],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "{diagnostics:?}"
    );

    let intents = derive_intents(&predecessor, &successor).expect("derive intents");
    assert_eq!(
        intents,
        vec![MigrationIntent::RetireField {
            table: "notes".to_owned(),
            field: "extra".to_owned(),
        }],
    );
    let steps = derive_plan_steps(&predecessor, &successor, &intents).expect("derive steps");
    let identity = |schema: &SchemaManifest| {
        crate::storage::migration_executor::schema_identity(schema).expect("identity")
    };
    let artifact = MigrationPlanArtifactV1::seal(MigrationPlanBody {
        schema_version: MIGRATION_PLAN_SCHEMA_VERSION.to_owned(),
        app: snapback.migrate_app_id(),
        instance: "memory".to_owned(),
        target_profile_id: crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
        predecessor_schema_hash: identity(&predecessor),
        successor_schema_hash: identity(&successor),
        predecessor_generation: 1,
        steps,
        execution_strategy: MigrationExecutionStrategy::SingleTransaction,
        proof: MigrationProof {
            method: MigrationProofMethod::Full,
            bound: None,
        },
        ceilings: MigrationCeilings {
            max_affected_rows: 100,
            max_bytes: 1024 * 1024,
            max_writes: 100,
            max_barrier_downtime_ms: 60_000,
        },
        compatibility_posture: CompatibilityPosture::SuccessorOnly,
        retained_work_posture: RetainedWorkPosture::Empty,
        backup: MigrationBackupRequirement {
            required: false,
            checkpoint_label: None,
            rehearsal_required: false,
        },
        expected_output: MigrationExpectedOutput {
            schema_hash: identity(&successor),
            projection_generations: BTreeMap::new(),
        },
        constants: MigrationConstants {
            publication_timestamp_ms: 2_000_000_000_000,
            rollback_timestamp_ms: Some(2_000_000_000_001),
            values: BTreeMap::new(),
        },
        boundaries: Default::default(),
    })
    .expect("seal plan");
    let approve = |snapback: &mut LocalSnapback, artifact: &MigrationPlanArtifactV1| {
        let resolved = snapback.migrate_resolved_audience().expect("audience");
        MigrationApprovalV1 {
            schema_version: MIGRATION_APPROVAL_SCHEMA_VERSION.to_owned(),
            plan_digest: artifact.plan_digest.clone(),
            observation_digest: "0".repeat(64),
            policy_digest: "local-operator-policy-v1".to_owned(),
            audience: MigrationAudienceV1 {
                project_id: None,
                target_id: None,
                environment_id: None,
                deployment_id: None,
                release_id: None,
                database_id: resolved.database_id,
                stream_incarnation: resolved.stream_incarnation,
                activation_generation: resolved.activation_generation,
                target_profile_id: resolved.target_profile_id,
            },
            approver: "witness-operator".to_owned(),
            generator_is_approver: true,
            issued_at_ms: now_millis(),
            expires_at_ms: now_millis() + 86_400_000,
            operation_id: new_operation_id(),
        }
    };
    let approval = approve(&mut snapback, &artifact);
    let error = snapback
        .migrate_apply_artifact(&artifact, &approval, &successor)
        .expect_err("a function bound to the retired field must refuse publication");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_MIGRATION_PRECONDITION_FAILED"
    );
    assert!(
        error.diagnostic.message.contains("staged function set"),
        "{}",
        error.diagnostic.message
    );

    // With a successor-compatible function set the same plan publishes.
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![FunctionDefinition::new(
            "listNotes",
            FunctionKind::Query,
            FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
                table_visibility: None,
                table: "notes".to_owned(),
                filters: Vec::new(),
                membership_filters: Vec::new(),
                order: Vec::new(),
                limit: None,
                indexed_by: None,
            })),
        )],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "{diagnostics:?}"
    );
    // Reloading the staged pair rolled the activation generation, so
    // the earlier approval's audience is stale by design (§2): the same
    // plan publishes as a new operation under a fresh approval.
    let fresh = approve(&mut snapback, &artifact);
    let receipt = snapback
        .migrate_apply_artifact(&artifact, &fresh, &successor)
        .expect("a binding pair publishes");
    assert_eq!(receipt.state.kind(), "released");
    let rollback_error = snapback
        .migrate_rollback_artifact(&artifact, &fresh)
        .expect_err("a released artifact refuses fast rollback");
    snapback
        .telemetry
        .force_flush()
        .expect("flush migration lifecycle");
    assert_eq!(
        snapback
            .telemetry
            .event_outcomes_for_test("lifecycle", "migration_success", "point"),
        vec![(Some(200), None)]
    );
    assert_eq!(
        snapback
            .telemetry
            .event_outcomes_for_test("lifecycle", "migration_failure", "point"),
        vec![
            (
                Some(500),
                Some("SNAPBACK_MIGRATION_PRECONDITION_FAILED".to_owned())
            ),
            (Some(500), Some(rollback_error.diagnostic.code.clone())),
        ]
    );
    assert_eq!(
        snapback
            .telemetry
            .event_details_for_test("lifecycle", "migration_failure")[1]
            .as_ref()
            .and_then(|details| details.get("cause")),
        Some(&json!("rollback"))
    );

    let mut rollback_snapback = LocalSnapback::memory().expect("rollback lifecycle fixture");
    rollback_snapback
        .apply_schema(predecessor)
        .expect("apply rollback predecessor");
    let rollback_approval = approve(&mut rollback_snapback, &artifact);
    crate::storage::migration_executor::arm_migration_kill_point("released", 0);
    let published_held = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        rollback_snapback.migrate_apply_artifact(&artifact, &rollback_approval, &successor)
    }));
    crate::storage::migration_executor::disarm_migration_kill_point();
    assert!(published_held.is_err(), "fixture stops at published-held");
    rollback_snapback
        .migrate_rollback_artifact(&artifact, &rollback_approval)
        .expect("published-held artifact rolls back");
    rollback_snapback
        .telemetry
        .force_flush()
        .expect("flush successful rollback lifecycle");
    assert_eq!(
        rollback_snapback.telemetry.event_outcomes_for_test(
            "lifecycle",
            "migration_success",
            "point"
        ),
        vec![(Some(200), None)]
    );
    assert_eq!(
        rollback_snapback
            .telemetry
            .event_details_for_test("lifecycle", "migration_success")[0]
            .as_ref()
            .and_then(|details| details.get("cause")),
        Some(&json!("rollback"))
    );
}

// @ref LLP 0081#6-compatibility-and-deployment-ordering — the
//   ordering postures are proven, never inferred: a dual-compatible or
//   predeploy-compatible plan publishes only when the installed
//   predecessor artifact provably binds against the successor schema
//   (the generated-facts compatibility check), the old artifact keeps
//   serving across a predeploy publication, and an actually
//   incompatible predecessor refuses the declared ordering by name
//   with no DDL, publication, or transition event.
#[test]
fn compatibility_posture_ordering_is_proven_not_declared() {
    use crate::migration::{
        CompatibilityPosture, MIGRATION_APPROVAL_SCHEMA_VERSION, MIGRATION_PLAN_SCHEMA_VERSION,
        MigrationApprovalV1, MigrationAudienceV1, MigrationBackupRequirement, MigrationCeilings,
        MigrationConstants, MigrationExecutionStrategy, MigrationExpectedOutput,
        MigrationPlanArtifactV1, MigrationPlanBody, MigrationProof, MigrationProofMethod,
        RetainedWorkPosture, derive_intents, derive_plan_steps, new_operation_id,
    };
    let field = |name: &str, optional: bool| crate::manifest::FieldManifest {
        name: name.to_owned(),
        field_type: crate::manifest::FieldType::String,
        optional,
    };
    let schema_of = |fields: Vec<crate::manifest::FieldManifest>| SchemaManifest {
        tables: vec![crate::manifest::TableManifest {
            name: "notes".to_owned(),
            fields,
            indexes: Vec::new(),
            syncable: true,
            permission_backing: false,
            permission_fields: None,
            search_indexes: Vec::new(),
            vector_indexes: Vec::new(),
            search_live_limits: None,
            membership: None,
            authority_profile: None,
            asset_sharing: None,
            visibility: None,
            history: None,
        }],
        ..SchemaManifest::default()
    };
    let predecessor = schema_of(vec![field("body", false), field("extra", true)]);
    let successor = schema_of(vec![field("body", false)]);
    let identity = |schema: &SchemaManifest| {
        crate::storage::migration_executor::schema_identity(schema).expect("identity")
    };
    let list_function = |name: &str, filter_extra: bool| {
        FunctionDefinition::new(
            name,
            FunctionKind::Query,
            FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
                table_visibility: None,
                table: "notes".to_owned(),
                filters: filter_extra
                    .then(|| FilterExpr {
                        field: "extra".to_owned(),
                        op: FilterOp::Eq,
                        value: ValueExpr::Literal(json!("x")),
                    })
                    .into_iter()
                    .collect(),
                membership_filters: Vec::new(),
                order: Vec::new(),
                limit: None,
                indexed_by: None,
            })),
        )
    };
    let sealed = |snapback: &LocalSnapback, posture: CompatibilityPosture| {
        let intents = derive_intents(&predecessor, &successor).expect("derive intents");
        let steps = derive_plan_steps(&predecessor, &successor, &intents).expect("derive steps");
        MigrationPlanArtifactV1::seal(MigrationPlanBody {
            schema_version: MIGRATION_PLAN_SCHEMA_VERSION.to_owned(),
            app: snapback.migrate_app_id(),
            instance: "memory".to_owned(),
            target_profile_id: crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            predecessor_schema_hash: identity(&predecessor),
            successor_schema_hash: identity(&successor),
            predecessor_generation: 1,
            steps,
            execution_strategy: MigrationExecutionStrategy::SingleTransaction,
            proof: MigrationProof {
                method: MigrationProofMethod::Full,
                bound: None,
            },
            ceilings: MigrationCeilings {
                max_affected_rows: 100,
                max_bytes: 1024 * 1024,
                max_writes: 100,
                max_barrier_downtime_ms: 60_000,
            },
            compatibility_posture: posture,
            retained_work_posture: RetainedWorkPosture::Empty,
            backup: MigrationBackupRequirement {
                required: false,
                checkpoint_label: None,
                rehearsal_required: false,
            },
            expected_output: MigrationExpectedOutput {
                schema_hash: identity(&successor),
                projection_generations: BTreeMap::new(),
            },
            constants: MigrationConstants {
                publication_timestamp_ms: 2_000_000_000_000,
                rollback_timestamp_ms: None,
                values: BTreeMap::new(),
            },
            boundaries: Default::default(),
        })
        .expect("seal plan")
    };
    let approve = |snapback: &mut LocalSnapback, artifact: &MigrationPlanArtifactV1| {
        let resolved = snapback.migrate_resolved_audience().expect("audience");
        MigrationApprovalV1 {
            schema_version: MIGRATION_APPROVAL_SCHEMA_VERSION.to_owned(),
            plan_digest: artifact.plan_digest.clone(),
            observation_digest: "0".repeat(64),
            policy_digest: "local-operator-policy-v1".to_owned(),
            audience: MigrationAudienceV1 {
                project_id: None,
                target_id: None,
                environment_id: None,
                deployment_id: None,
                release_id: None,
                database_id: resolved.database_id,
                stream_incarnation: resolved.stream_incarnation,
                activation_generation: resolved.activation_generation,
                target_profile_id: resolved.target_profile_id,
            },
            approver: "witness-operator".to_owned(),
            generator_is_approver: true,
            issued_at_ms: now_millis(),
            expires_at_ms: now_millis() + 86_400_000,
            operation_id: new_operation_id(),
        }
    };
    let build = |compatible_functions: bool| {
        let mut snapback = LocalSnapback::memory().expect("memory posture fixture");
        snapback
            .apply_schema(predecessor.clone())
            .expect("apply schema");
        let diagnostics = snapback.load_functions(FunctionManifest {
            functions: vec![list_function("listNotes", !compatible_functions)],
            ..FunctionManifest::default()
        });
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "{diagnostics:?}"
        );
        snapback
    };

    for posture in [
        CompatibilityPosture::DualCompatible,
        CompatibilityPosture::PredeployCompatible,
    ] {
        // Proven: the installed predecessor artifact never references
        // the retired field, so the declared ordering publishes and the
        // OLD artifact keeps serving against successor storage.
        let mut snapback = build(true);
        let artifact = sealed(&snapback, posture);
        let approval = approve(&mut snapback, &artifact);
        let receipt = snapback
            .migrate_apply_artifact(&artifact, &approval, &successor)
            .unwrap_or_else(|error| panic!("{posture:?} proven ordering publishes: {error:?}"));
        assert_eq!(receipt.state.kind(), "released");
        let transition = snapback
            .db
            .latest_schema_transition()
            .expect("read transition")
            .expect("transition recorded");
        assert_eq!(transition.body.compatibility_posture, posture);
        snapback
            .invoke_query("listNotes", HandlerInput::default())
            .unwrap_or_else(|error| {
                panic!("{posture:?}: the predecessor artifact keeps serving: {error:?}")
            });

        // Unproven: the installed artifact reads the retired field —
        // the declared ordering refuses by name, with no publication.
        let mut snapback = build(false);
        let artifact = sealed(&snapback, posture);
        let approval = approve(&mut snapback, &artifact);
        let error = snapback
            .migrate_apply_artifact(&artifact, &approval, &successor)
            .expect_err("an unproven ordering must refuse");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_MIGRATION_PRECONDITION_FAILED"
        );
        let expected_fragment = match posture {
            CompatibilityPosture::DualCompatible => "dual-compatible ordering is unproven",
            CompatibilityPosture::PredeployCompatible => {
                "predeploy-compatible ordering is unproven"
            }
            CompatibilityPosture::SuccessorOnly => unreachable!(),
        };
        assert!(
            error.diagnostic.message.contains(expected_fragment),
            "{}",
            error.diagnostic.message
        );
        assert!(
            snapback
                .db
                .latest_schema_transition()
                .expect("read transition")
                .is_none(),
            "a refused ordering publishes nothing",
        );
        assert!(
            snapback
                .db
                .schema()
                .table("notes")
                .expect("table")
                .field("extra")
                .is_some(),
            "a refused ordering issues no DDL",
        );
    }
}

// @ref LLP 0081#7-target-safety-backup-and-secrets — the
//   restore-derived rehearsal: a plan requiring one refuses production
//   apply without a consumed fresh rehearsal receipt; the rehearsal
//   executes only against the isolated target its binding names (never
//   production); its journal/receipt are marked rehearsal; and the
//   production admission consumes the receipt while still executing
//   the original plan against production — the rehearsal receipt never
//   substitutes for the production apply receipt.
#[test]
fn restore_derived_rehearsal_gates_production_apply() {
    use crate::migration::{
        CompatibilityPosture, MIGRATION_APPROVAL_SCHEMA_VERSION, MIGRATION_PLAN_SCHEMA_VERSION,
        MigrationApprovalV1, MigrationAudienceV1, MigrationBackupRequirement, MigrationCeilings,
        MigrationConstants, MigrationExecutionStrategy, MigrationExpectedOutput,
        MigrationPlanArtifactV1, MigrationPlanBody, MigrationProof, MigrationProofMethod,
        MigrationRehearsalBindingV1, MigrationRehearsalPlanV1, RetainedWorkPosture, derive_intents,
        derive_plan_steps, new_operation_id,
    };
    let field = |name: &str, optional: bool| crate::manifest::FieldManifest {
        name: name.to_owned(),
        field_type: crate::manifest::FieldType::String,
        optional,
    };
    let schema_of = |fields: Vec<crate::manifest::FieldManifest>| SchemaManifest {
        tables: vec![crate::manifest::TableManifest {
            name: "notes".to_owned(),
            fields,
            indexes: Vec::new(),
            syncable: true,
            permission_backing: false,
            permission_fields: None,
            search_indexes: Vec::new(),
            vector_indexes: Vec::new(),
            search_live_limits: None,
            membership: None,
            authority_profile: None,
            asset_sharing: None,
            visibility: None,
            history: None,
        }],
        ..SchemaManifest::default()
    };
    let predecessor = schema_of(vec![field("body", false), field("extra", true)]);
    let successor = schema_of(vec![field("body", false)]);
    let identity = |schema: &SchemaManifest| {
        crate::storage::migration_executor::schema_identity(schema).expect("identity")
    };
    let instance = || {
        let mut snapback = LocalSnapback::memory().expect("memory rehearsal fixture");
        snapback
            .apply_schema(predecessor.clone())
            .expect("apply schema");
        snapback
    };
    let sealed = |snapback: &LocalSnapback| {
        let intents = derive_intents(&predecessor, &successor).expect("derive intents");
        let steps = derive_plan_steps(&predecessor, &successor, &intents).expect("derive steps");
        MigrationPlanArtifactV1::seal(MigrationPlanBody {
            schema_version: MIGRATION_PLAN_SCHEMA_VERSION.to_owned(),
            app: snapback.migrate_app_id(),
            instance: "memory".to_owned(),
            target_profile_id: crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            predecessor_schema_hash: identity(&predecessor),
            successor_schema_hash: identity(&successor),
            predecessor_generation: 1,
            steps,
            execution_strategy: MigrationExecutionStrategy::SingleTransaction,
            proof: MigrationProof {
                method: MigrationProofMethod::Full,
                bound: None,
            },
            ceilings: MigrationCeilings {
                max_affected_rows: 100,
                max_bytes: 1024 * 1024,
                max_writes: 100,
                max_barrier_downtime_ms: 60_000,
            },
            compatibility_posture: CompatibilityPosture::SuccessorOnly,
            retained_work_posture: RetainedWorkPosture::Empty,
            backup: MigrationBackupRequirement {
                required: false,
                checkpoint_label: None,
                rehearsal_required: true,
            },
            expected_output: MigrationExpectedOutput {
                schema_hash: identity(&successor),
                projection_generations: BTreeMap::new(),
            },
            constants: MigrationConstants {
                publication_timestamp_ms: 2_000_000_000_000,
                rollback_timestamp_ms: None,
                values: BTreeMap::new(),
            },
            boundaries: Default::default(),
        })
        .expect("seal plan")
    };
    let approve = |snapback: &mut LocalSnapback, artifact: &MigrationPlanArtifactV1| {
        let resolved = snapback.migrate_resolved_audience().expect("audience");
        MigrationApprovalV1 {
            schema_version: MIGRATION_APPROVAL_SCHEMA_VERSION.to_owned(),
            plan_digest: artifact.plan_digest.clone(),
            observation_digest: "0".repeat(64),
            policy_digest: "local-operator-policy-v1".to_owned(),
            audience: MigrationAudienceV1 {
                project_id: None,
                target_id: None,
                environment_id: None,
                deployment_id: None,
                release_id: None,
                database_id: resolved.database_id,
                stream_incarnation: resolved.stream_incarnation,
                activation_generation: resolved.activation_generation,
                target_profile_id: resolved.target_profile_id,
            },
            approver: "witness-operator".to_owned(),
            generator_is_approver: true,
            issued_at_ms: now_millis(),
            expires_at_ms: now_millis() + 86_400_000,
            operation_id: new_operation_id(),
        }
    };

    let mut production = instance();
    let artifact = sealed(&production);
    let approval = approve(&mut production, &artifact);

    // (a) Production apply without a rehearsal receipt refuses.
    let error = production
        .migrate_apply_artifact(&artifact, &approval, &successor)
        .expect_err("a rehearsal-required plan gates production apply");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_MIGRATION_REHEARSAL_REQUIRED"
    );

    // The restore-derived isolated instance (the local profile's
    // byte-copy restore stands in for LLP 0072's backup manifest).
    let mut isolated = instance();
    let isolated_id = isolated
        .migrate_resolved_audience()
        .expect("isolated audience")
        .database_id;
    let rehearsal = MigrationRehearsalPlanV1::seal(
        artifact.plan_digest.clone(),
        MigrationRehearsalBindingV1 {
            source_backup_identity: "backup-witness-1".to_owned(),
            isolated_database_id: isolated_id,
            restore_epoch_ms: 1_000,
            target_profile_id: crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
        },
    )
    .expect("seal rehearsal");

    // (b) The rehearsal cannot target production: executing it on any
    // database but the bound isolated target refuses.
    let production_approval = approve(&mut production, &artifact);
    let error = production
        .migrate_rehearse_artifact(&artifact, &production_approval, &successor, &rehearsal)
        .expect_err("a rehearsal must not execute against production");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_MIGRATION_REHEARSAL_INVALID"
    );

    // (c) Against the bound restore-derived target it executes, marked.
    let isolated_approval = approve(&mut isolated, &artifact);
    let rehearsal_receipt = isolated
        .migrate_rehearse_artifact(&artifact, &isolated_approval, &successor, &rehearsal)
        .expect("rehearsal executes against its restore-derived target");
    assert!(
        rehearsal_receipt.rehearsal,
        "the receipt is marked rehearsal"
    );
    assert_eq!(rehearsal_receipt.state.kind(), "released");
    assert!(rehearsal_receipt.completed_at_ms > 0);

    // (e) A rehearsal receipt for a different plan refuses production.
    let mut doctored = rehearsal_receipt.clone();
    doctored.plan_digest = "0".repeat(64);
    let error = production
        .migrate_apply_artifact_with_rehearsal_receipt(
            &artifact,
            &approval,
            &successor,
            Some(&doctored),
        )
        .expect_err("a cross-plan rehearsal receipt refuses");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_MIGRATION_REHEARSAL_INVALID"
    );

    // (f) A stale rehearsal receipt refuses under the freshness policy.
    let mut stale = rehearsal_receipt.clone();
    stale.completed_at_ms = 1;
    let error = production
        .migrate_apply_artifact_with_rehearsal_receipt(
            &artifact,
            &approval,
            &successor,
            Some(&stale),
        )
        .expect_err("an over-age rehearsal receipt refuses");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_MIGRATION_REHEARSAL_INVALID"
    );

    // (d) Consuming the fresh receipt, production apply still executes
    // the ORIGINAL plan against production, and its receipt is its
    // own — unmarked, a different operation — never the rehearsal's.
    let fresh_approval = approve(&mut production, &artifact);
    let production_receipt = production
        .migrate_apply_artifact_with_rehearsal_receipt(
            &artifact,
            &fresh_approval,
            &successor,
            Some(&rehearsal_receipt),
        )
        .expect("production apply consumes the rehearsal receipt");
    assert!(!production_receipt.rehearsal);
    assert_eq!(production_receipt.state.kind(), "released");
    assert_ne!(
        production_receipt.operation_id, rehearsal_receipt.operation_id,
        "the rehearsal receipt never substitutes for the production apply receipt",
    );
}

// @ref LLP 0081#4-execution-journaling-and-crash-recovery — publication
//   fires LLP 0053's activation obligations for auth-scoped state, not
//   a generic resync: under Sessions authorities, an auth-scoped live
//   subscription crossing a publication gets a durable Delete
//   obligation raised with the publication witness, a terminal-delete
//   resolution with acknowledgement semantics, the projected obligation
//   frame, and an authenticated scope retirement.
#[test]
fn publication_fires_durable_dispositions_for_auth_scoped_subscriptions() {
    let (schema, functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, functions);
    let connection = install_test_invalidation(&mut snapback);
    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "publication-authz".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(97)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("auth-scoped subscribe under sessions");
    let scope = snapback
        .subscriptions
        .get(&subscribed.subscription_id)
        .and_then(|subscription| subscription.authorization.as_ref())
        .map(|authorization| authorization.scope_id.clone())
        .expect("subscription is auth-scoped");
    // Start from an empty queue so the drained frames below are exactly
    // the publication consequence.
    let _ = drain_live_stream_through_test_sink(&mut snapback, "publication-authz");

    snapback
        .retire_live_subscriptions_for_publication()
        .expect("publication retirement under auth-scoped subscription");

    assert!(
        snapback.subscriptions.is_empty(),
        "no subscription survives the publication"
    );
    // The durable consequence is the obligation frame — never the
    // unscoped generic resync.
    let frames = drain_live_stream_through_test_sink(&mut snapback, "publication-authz");
    let envelopes: Vec<Value> = frames
        .iter()
        .map(|frame| serde_json::from_str(frame).expect("frame parses"))
        .collect();
    assert!(
        envelopes
            .iter()
            .all(|envelope| envelope["kind"] != "resync_required"),
        "auth-scoped retirement must not substitute a generic resync: {envelopes:?}"
    );
    let invalidation = envelopes
        .iter()
        .find(|envelope| envelope["kind"] == "authorization_invalidation")
        .expect("durable obligation frame delivered");
    assert_eq!(
        invalidation["obligation"]["maxDisposition"],
        json!("delete"),
        "retained rows are cleared by durable disposition: {invalidation}"
    );
    assert_eq!(
        invalidation["resolution"]["kind"],
        json!("terminalDelete"),
        "the terminal resolution rides the same frame: {invalidation}"
    );
    assert!(
        invalidation["resolution"]["ackToken"].is_string(),
        "the resolution carries acknowledgement semantics: {invalidation}"
    );
    // The scope retirement is durable and authenticated: the registry
    // holds no live projection for the retired scope.
    let retired_projection = snapback
        .auth_invalidation
        .as_ref()
        .expect("invalidation installed")
        .obligations
        .projection(&scope);
    assert!(
        retired_projection.is_none(),
        "a retired scope keeps no live obligation projection"
    );
}

// @ref LLP 0081#6-compatibility-and-deployment-ordering — the
//   posture-aware attest handshake: after a successor-only publication,
//   a client attesting the predecessor schema artifact receives the
//   stable upgrade-required refusal, while the successor pair still
//   attests matched.
#[test]
fn attest_refuses_predecessor_artifacts_after_successor_only_publication() {
    let (schema, functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, functions);
    let active = snapback
        .db
        .auth_mode_snapshot()
        .expect("snapshot")
        .state
        .active_deployment
        .expect("active deployment");
    let pair = |schema_hash: &str| super::EnsureAppPairIdentity {
        schema: super::EnsureAppSchemaIdentity {
            artifact_kind: "schemaManifest".to_owned(),
            schema_version: active.schema_version.clone(),
            app_id: active.app_id.clone(),
            schema_hash: schema_hash.to_owned(),
            inputs_hash: active.inputs_hash.clone(),
        },
        functions: super::EnsureAppFunctionIdentity {
            artifact_kind: "functionManifest".to_owned(),
            schema_version: active.schema_version.clone(),
            app_id: active.app_id.clone(),
            bundle_hash: active.bundle_hash.clone(),
            inputs_hash: active.inputs_hash.clone(),
        },
    };
    // Craft a format-valid predecessor hash distinct from the active one.
    let predecessor_hash = {
        let mut hash = active.schema_hash.clone();
        let flipped = if hash.ends_with('0') { "1" } else { "0" };
        hash.truncate(hash.len() - 1);
        hash.push_str(flipped);
        hash
    };
    crate::storage::publish_schema_transition_for_test(
        &mut snapback.db,
        crate::migration::CompatibilityPosture::SuccessorOnly,
        &predecessor_hash,
    );

    let error = snapback
        .attest_app(EnsureAppMode::Sessions, pair(&predecessor_hash))
        .expect_err("predecessor artifacts must refuse after successor-only publication");
    assert_eq!(error.diagnostic.code, "SNAPBACK_MIGRATION_UPGRADE_REQUIRED");

    // The admitted ordering under dual-compatible: the same predecessor
    // attest is ADMITTED during the window — old and new artifacts are
    // both valid, so the answer is an unmatched attest, not the
    // upgrade-required refusal (LLP 0081 §6).
    {
        let (schema, functions) = sessions_activation_pair('b', false);
        let mut dual = settled_sessions_activation_snapback(schema, functions);
        let active = dual
            .db
            .auth_mode_snapshot()
            .expect("snapshot")
            .state
            .active_deployment
            .expect("active deployment");
        let dual_pair = |schema_hash: &str| super::EnsureAppPairIdentity {
            schema: super::EnsureAppSchemaIdentity {
                artifact_kind: "schemaManifest".to_owned(),
                schema_version: active.schema_version.clone(),
                app_id: active.app_id.clone(),
                schema_hash: schema_hash.to_owned(),
                inputs_hash: active.inputs_hash.clone(),
            },
            functions: super::EnsureAppFunctionIdentity {
                artifact_kind: "functionManifest".to_owned(),
                schema_version: active.schema_version.clone(),
                app_id: active.app_id.clone(),
                bundle_hash: active.bundle_hash.clone(),
                inputs_hash: active.inputs_hash.clone(),
            },
        };
        let dual_predecessor_hash = {
            let mut hash = active.schema_hash.clone();
            let flipped = if hash.ends_with('0') { "1" } else { "0" };
            hash.truncate(hash.len() - 1);
            hash.push_str(flipped);
            hash
        };
        crate::storage::publish_schema_transition_for_test(
            &mut dual.db,
            crate::migration::CompatibilityPosture::DualCompatible,
            &dual_predecessor_hash,
        );
        let outcome = dual
            .attest_app(EnsureAppMode::Sessions, dual_pair(&dual_predecessor_hash))
            .expect("dual-compatible admits the predecessor attest during the window");
        assert!(
            !outcome.matched,
            "the predecessor pair is admitted, not active"
        );
    }

    // The successor (active) pair still attests, matched.
    let outcome = snapback
        .attest_app(EnsureAppMode::Sessions, pair(&active.schema_hash))
        .expect("active pair attests");
    assert!(outcome.matched, "the successor pair stays matched");
}

fn settled_sessions_activation_snapback(
    schema: SchemaManifest,
    predecessor_functions: FunctionManifest,
) -> LocalSnapback {
    let mut snapback = LocalSnapback::memory().expect("memory activation fixture");
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            Some(schema),
            Some(predecessor_functions.clone()),
            Some(crate::manifest::SeedData {
                tables: BTreeMap::from([(
                    "items".to_owned(),
                    vec![serde_json::Map::from_iter([(
                        "value".to_owned(),
                        json!("predecessor-visible"),
                    )])],
                )]),
            }),
        )
        .expect("preflight initial complete sessions pair");
    let (_, pending) = snapback
        .commit_auth_provision(prepared, "test")
        .expect("stage initial sessions pair");
    assert_eq!(
        pending.mode_state,
        crate::auth::mode::AuthModeStatus::PendingRestart
    );
    let readiness = AuthProgramReadiness::new(true, true, true, true, true, true, true);
    let settled = snapback
        .auth_database_mut()
        .consume_sessions_auth_mode_with_functions(&readiness, &predecessor_functions)
        .expect("consume initial sessions pair");
    snapback
        .synchronize_auth_mode_admission(&settled)
        .expect("publish settled sessions admission");
    let diagnostics = snapback.publish_preflighted_functions(
        predecessor_functions,
        41,
        DiagnosticBoundary::Attached,
    );
    assert!(
        diagnostics.iter().all(|diagnostic| !matches!(
            diagnostic.severity,
            crate::diagnostic::DiagnosticSeverity::Error
                | crate::diagnostic::DiagnosticSeverity::Fatal
        )),
        "initial sessions functions must publish: {diagnostics:?}"
    );
    snapback
}

fn scoped_live_authority(snapback: &mut LocalSnapback) -> PreparedAuthority {
    let random = CounterRandom::new();
    let now_ms = now_millis();
    let service_fences = snapback.service_authority_fences.clone();
    let (resolved, service_publication) = {
        let db = snapback.auth_database_mut();
        db.auth_catalog()
            .insert_human_user_for_test("activation-owner", now_ms)
            .expect("create activation owner");
        db.create_agent_principal(
            "activation-agent",
            now_ms,
            &crate::storage::auth_agents::AgentRegistration {
                display_name: Some("Activation agent".to_owned()),
                operator_contact: None,
                registration_provenance: r#"{"source":"activation-test"}"#.to_owned(),
                owner_user_id: Some("activation-owner".to_owned()),
            },
        )
        .expect("create activation agent");
        let credential = db
            .issue_initial_agent_credential("activation-agent", now_ms, &random)
            .expect("issue activation credential");
        db.auth_catalog()
            .insert_activation_live_grant_for_test(now_ms)
            .expect("create activation grant");
        let token = db
            .mint_scoped_token(
                &credential.secret,
                "activation-grant",
                Some(60_000),
                now_ms,
                &random,
            )
            .expect("mint activation token");
        let resolved = db
            .resolve_scoped_token(&token.secret, now_ms)
            .expect("resolve activation token");
        let publication = service_fences
            .register(resolved.service_authority_witness(), now_ms, Instant::now())
            .expect("register activation token fence");
        (resolved, publication)
    };
    let admission = snapback
        .admission
        .admit_for_mode(AuthMode::Sessions)
        .expect("admit service live owner");
    InvocationGate::prepare_admitted_authority(
        InvocationSource::LiveInitialQuery,
        AuthMode::Sessions,
        ServerProfile::Test,
        admission,
        &WireAuthorityFields::default(),
        ResolvedAppAuthority::from_scoped_token(resolved),
        None,
    )
    .expect("prepare service live authority")
    .with_service_publication(service_publication)
}

#[test]
fn retained_service_live_revalidates_only_its_matched_grant_entry() {
    let (schema, mut predecessor_functions) = sessions_activation_pair('b', false);
    predecessor_functions
        .functions
        .push(FunctionDefinition::new(
            "unrelatedLive",
            FunctionKind::LiveQuery,
            predecessor_functions.functions[0].runtime.clone(),
        ));
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions);
    let connection = install_test_invalidation(&mut snapback);
    let authority = scoped_live_authority(&mut snapback);
    let subscribed = snapback
        .subscribe_live_prepared_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "matched-scope-live".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(93)),
                supersedes: None,
                resume_from_token: None,
            },
            authority.clone(),
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection.clone()),
                effect_fence: None,
            },
        )
        .expect("subscribe under the listItems entry");
    let retained = snapback
        .subscriptions
        .get(&subscribed.subscription_id)
        .expect("retained subscription")
        .authority
        .clone();
    assert_eq!(
        retained
            .matched_grant_scope()
            .expect("service live retains its exact entry")
            .function_id(),
        "fn:listItems"
    );
    let unrelated = snapback
        .subscribe_live_prepared_with_invalidation(
            "unrelatedLive",
            LiveSubscribeInput {
                connection_id: "matched-scope-live".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(94)),
                supersedes: None,
                resume_from_token: None,
            },
            authority,
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("subscribe under the unrelatedLive entry");
    let unrelated_retained = snapback
        .subscriptions
        .get(&unrelated.subscription_id)
        .expect("retained unrelated subscription")
        .authority
        .clone();
    assert_eq!(
        unrelated_retained
            .matched_grant_scope()
            .expect("second service live retains its exact entry")
            .function_id(),
        "fn:unrelatedLive"
    );

    snapback
        .auth_database_mut()
        .auth_catalog()
        .tombstone_scope_basis_for_test("fn:unrelatedLive", "liveQuery", false)
        .expect("tombstone unrelated grant entry");
    let unrelated_admission = snapback
        .admission
        .admit_for_mode(AuthMode::Sessions)
        .expect("fresh unrelated rerun admission");
    let unrelated_error = snapback
        .prepare_live_rerun_authority(&unrelated_retained, unrelated_admission)
        .expect_err("the tombstoned B entry terminates B");
    assert_eq!(
        unrelated_error.diagnostic.code,
        "SNAPBACK_AUTH_GRANT_SCOPE_DENIED"
    );

    let admission = snapback
        .admission
        .admit_for_mode(AuthMode::Sessions)
        .expect("fresh rerun admission");
    let rerun = snapback
        .prepare_live_rerun_authority(&retained, admission)
        .expect("unrelated scope tombstone does not end listItems");
    let mut inserted = BTreeMap::new();
    inserted.insert(
        "value".to_owned(),
        ValueExpr::Literal(json!("visible-after-b-tombstone")),
    );
    snapback
        .db
        .mutation_writes()
        .execute_mutation(
            &MutationPlan {
                owner_write_checks: Vec::new(),
                steps: vec![MutationStep::Insert {
                    table: "items".to_owned(),
                    values: inserted,
                    bind_id_as: None,
                }],
                return_value: Some(ReturnValue::ChangedCount),
            },
            &HandlerInput::default(),
        )
        .expect("commit a data update after B terminates");
    let rerun = snapback
        .invoke_query_with_dependencies_prepared("listItems", HandlerInput::default(), rerun)
        .expect("A remains live and reruns after B terminates");
    assert!(
        rerun
            .output
            .rows
            .iter()
            .any(|row| { row["value"] == json!("visible-after-b-tombstone") })
    );

    snapback
        .auth_database_mut()
        .auth_catalog()
        .tombstone_scope_basis_for_test("fn:listItems", "liveQuery", false)
        .expect("tombstone matched grant entry");
    let admission = snapback
        .admission
        .admit_for_mode(AuthMode::Sessions)
        .expect("fresh terminal rerun admission");
    let error = snapback
        .prepare_live_rerun_authority(&retained, admission)
        .expect_err("matched scope tombstone ends listItems");
    assert_eq!(error.diagnostic.code, "SNAPBACK_AUTH_GRANT_SCOPE_DENIED");
}

#[test]
fn same_mode_sessions_activation_projects_live_successor_before_reopening() {
    let (schema, predecessor_functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions);

    let connection = install_test_invalidation(&mut snapback);
    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "activation-live".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(90)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("subscribe under predecessor deployment");
    assert_eq!(subscribed.snapshot.as_ref().unwrap().rows.len(), 1);
    assert!(
        drain_live_stream_through_test_sink(&mut snapback, "activation-live").is_empty(),
        "the activation test starts with an empty delivery queue"
    );
    let predecessor_authorization = snapback
        .auth_invalidation
        .as_ref()
        .expect("installed invalidation state")
        .obligations
        .expectation()
        .authorization
        .clone();

    let (_, mut successor_functions) = sessions_activation_pair('d', true);
    successor_functions.functions[0].authority_creating = true;
    let successor_bundle = successor_functions.bundle_hash.clone();
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions),
            None,
        )
        .expect("preflight one-half successor through cached complete pair");
    let controller = snapback.admission.clone();
    let transition = controller
        .begin_transition()
        .expect("close and drain predecessor admission");
    let (committed, state, reopened) = transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            let state = committed.state().clone();
            Ok((committed, state))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("commit and project successor activation");

    assert_eq!(committed.state().clone(), state);
    assert_eq!(
        snapback
            .auth_database_mut()
            .current_auth_scope_basis("fn:listItems", &FunctionKind::LiveQuery, true)
            .expect("read committed authority-creating basis"),
        Some(1)
    );
    assert_eq!(
        snapback
            .auth_database_mut()
            .current_auth_scope_basis("fn:listItems", &FunctionKind::LiveQuery, false)
            .expect("old marker shape is terminal"),
        None
    );
    assert_eq!(
        state.active_deployment.unwrap().bundle_hash,
        successor_bundle.unwrap()
    );
    assert!(reopened.accepting);
    assert_eq!(reopened.in_flight, 0);
    let durable_authorization = snapback
        .auth_database_mut()
        .authorization_version()
        .expect("durable successor authorization");
    let projected_authorization = snapback
        .auth_invalidation
        .as_ref()
        .expect("installed invalidation state")
        .obligations
        .expectation()
        .authorization
        .clone();
    assert_eq!(projected_authorization, durable_authorization);
    assert_eq!(
        projected_authorization.epoch,
        predecessor_authorization.epoch + 1
    );

    // @ref LLP 0094#0c8-sessions-live-update-envelope-and-delivery-multiplicity —
    // retained authorization truth is projected at the delivery boundary;
    // the physical outbox intentionally carries no duplicate snapshot.
    let successor_admission = controller
        .admit_for_mode(AuthMode::Sessions)
        .expect("successor admission projects retained authorization truth");
    let frames = project_authorization_frames_through_test_sink(
        &mut snapback,
        "activation-live",
        &successor_admission,
    );
    let successor = frames
        .iter()
        .filter_map(|frame| serde_json::from_str::<Value>(frame).ok())
        .find(|frame| {
            frame["kind"] == "authorization_invalidation" && frame.get("snapshot").is_some()
        })
        .expect("activation projects a successor snapshot before admission reopens");
    assert_eq!(successor["snapshot"]["rows"], json!([]));
    assert_eq!(
        successor["obligation"]["witness"]["authorization"]["epoch"],
        projected_authorization.epoch
    );
    assert!(
        frames
            .iter()
            .all(|frame| !frame.contains("\"kind\":\"live_delta\"")),
        "deployment authorization changes never escape as an unfenced live delta"
    );
}

#[test]
fn sessions_generation_assertion_refuses_deploy_races_and_live_predecessors() {
    let (schema, mut predecessor_functions) = sessions_activation_pair('b', false);
    predecessor_functions.functions[0].authority_independent = true;
    predecessor_functions.functions[0].auth_requirement =
        Some(crate::manifest::AuthRequirement::Public);
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions.clone());
    let connection = install_test_invalidation(&mut snapback);
    let predecessor_generation = snapback
        .function_invocation_facts(AuthMode::Sessions)
        .expect("derive predecessor generation")
        .expect("sessions answers generation facts")
        .active_generation;
    let subscribe_input = |connection_id: &str| LiveSubscribeInput {
        connection_id: connection_id.to_owned(),
        input: HandlerInput::default(),
        authorization_namespace: None,
        supersedes: None,
        resume_from_token: None,
    };
    let invalidation = || LiveInvalidationAdmission {
        session_mode: true,
        connection: Some(connection.clone()),
        effect_fence: None,
    };

    let predecessor = snapback
        .subscribe_live_with_invalidation_generation(
            "listItems",
            subscribe_input("generation-bound-live"),
            invalidation(),
            Some(&predecessor_generation),
        )
        .expect("subscribe under the discovered predecessor generation");
    assert_eq!(
        predecessor
            .facts
            .expect("sessions subscribe echoes server facts")
            .active_generation,
        predecessor_generation
    );
    assert!(drain_live_stream_through_test_sink(&mut snapback, "generation-bound-live").is_empty());

    let (_, mut successor_functions) = sessions_activation_pair('d', true);
    successor_functions.functions[0].authority_independent = true;
    successor_functions.functions[0].auth_requirement =
        Some(crate::manifest::AuthRequirement::Public);
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions.clone()),
            None,
        )
        .expect("preflight successor generation");
    let transition = snapback
        .admission
        .clone()
        .begin_transition()
        .expect("close predecessor admission");
    transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            Ok(((), committed.state().clone()))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("activate successor generation");

    let frames = drain_live_stream_through_test_sink(&mut snapback, "generation-bound-live");
    assert!(frames.iter().any(|frame| {
        serde_json::from_str::<Value>(frame).is_ok_and(|frame| {
            frame["kind"] == "resync_required"
                && frame["reason"] == "SNAPBACK_ARTIFACT_IDENTITY_MISMATCH"
                && frame["subscription_id"] == predecessor.subscription_id
                && frame["clear_retained"] == true
        })
    }));

    let stale = snapback
        .subscribe_live_with_invalidation_generation(
            "listItems",
            subscribe_input("generation-stale-call"),
            invalidation(),
            Some(&predecessor_generation),
        )
        .expect_err("dispatch after a racing deploy refuses the stale generation");
    assert_eq!(stale.diagnostic.code, "SNAPBACK_ARTIFACT_IDENTITY_MISMATCH");
    assert_eq!(stale.diagnostic.details["subcause"], "generation");

    let successor_generation = snapback
        .function_invocation_facts(AuthMode::Sessions)
        .expect("derive successor generation")
        .expect("sessions answers generation facts")
        .active_generation;
    assert_ne!(successor_generation, predecessor_generation);
    snapback
        .subscribe_live_with_invalidation_generation(
            "listItems",
            subscribe_input("generation-refetched-call"),
            invalidation(),
            Some(&successor_generation),
        )
        .expect("refetching artifacts permits the successor call");
    snapback
        .subscribe_live_with_invalidation(
            "listItems",
            subscribe_input("generation-legacy-call"),
            invalidation(),
        )
        .expect("an unasserted legacy caller remains unchecked");

    successor_functions.bundle_hash = Some(format!("{}{}", FUNCTION_V1_PREFIX, "e".repeat(64)));
    successor_functions.functions.clear();
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions),
            None,
        )
        .expect("preflight removal generation");
    let transition = snapback.admission.clone().begin_transition().unwrap();
    transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            Ok(((), committed.state().clone()))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("activate function removal");
    let removed = snapback
        .subscribe_live_with_invalidation_generation(
            "listItems",
            subscribe_input("generation-removed-call"),
            invalidation(),
            Some(&successor_generation),
        )
        .expect_err("removed function keeps its distinct selection refusal");
    assert_eq!(removed.diagnostic.code, "SNAPBACK_UNKNOWN_FUNCTION");
}

// Regression for issues/20260801-0137-a3-live-subscriber-wedges-watch-reload.md:
// the served provision path runs the same-mode commit inside the managed
// Local write scope, where every live publication effect guard retains a
// clone of the transition's private projection root in the after-Local
// owner batch. That batch flushes only after the commit closure returns,
// so with one attached live subscriber the committed-carrier check saw
// its own projection root as a foreign in-flight admission and failed —
// wedging every watch-reload schema evolution in permanent
// SNAPBACK_AUTH_MODE_PENDING. This drives the exact production ordering.
#[test]
fn same_mode_activation_with_live_subscriber_survives_after_local_owner_retention() {
    let (schema, predecessor_functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions);

    let connection = install_test_invalidation(&mut snapback);
    snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "activation-live-retained".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(91)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("subscribe under predecessor deployment");

    let (_, mut successor_functions) = sessions_activation_pair('d', true);
    successor_functions.functions[0].authority_creating = true;
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions),
            None,
        )
        .expect("preflight successor pair");
    let controller = snapback.admission.clone();
    let transition = controller
        .begin_transition()
        .expect("close and drain predecessor admission");

    // Mirror the served write lane: reservation + Local write scope, with
    // the after-Local owner batch (which holds clones of the projection
    // root) flushing only after the commit closure returns.
    let committed = snapback
        .try_with_direct_authorization_write(
            crate::storage::AuthorizationCommitPreflight::AllProtectedRooms,
            move |snapback| {
                transition.commit_and_project_mode_state(|projection_admission| {
                    let committed = snapback.commit_auth_provision_classified(
                        prepared,
                        "test",
                        Some(projection_admission),
                    )?;
                    let state = committed.state().clone();
                    Ok((committed, state))
                })
            },
        )
        .expect("reserve the authorization write lane")
        .require_finalized()
        .expect("finalize the authorization write lane")
        .expect(
            "a live subscriber's retained publication admission must not wedge the \
                 same-mode activation",
        );

    let (_, _, reopened) = committed
        .publish_successor()
        .expect("publish successor after the after-Local owners flushed");
    assert!(reopened.accepting);
    assert_eq!(reopened.in_flight, 0);
    assert_eq!(
        controller
            .admit_for_mode(AuthMode::Sessions)
            .expect("admission reopens for app data after the evolution")
            .admission_epoch(),
        reopened.admission_epoch
    );
}

#[test]
fn same_mode_activation_terminally_deletes_live_service_scope_tombstones() {
    let (schema, predecessor_functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions);
    let connection = install_test_invalidation(&mut snapback);
    let authority = scoped_live_authority(&mut snapback);
    let subscribed = snapback
        .subscribe_live_prepared_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "activation-service-live".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(94)),
                supersedes: None,
                resume_from_token: None,
            },
            authority,
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("subscribe service owner under predecessor scope basis");
    assert!(subscribed.authorization_scope.is_some());
    assert!(
        drain_live_stream_through_test_sink(&mut snapback, "activation-service-live").is_empty()
    );

    let (_, mut successor_functions) = sessions_activation_pair('d', true);
    successor_functions.functions[0].authority_creating = true;
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions),
            None,
        )
        .expect("preflight successor that tombstones the retained scope shape");
    let transition = snapback
        .admission
        .clone()
        .begin_transition()
        .expect("close predecessor admission");
    transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            Ok(((), committed.state().clone()))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("commit scope tombstone and terminal live projection");

    let frames = drain_live_stream_through_test_sink(&mut snapback, "activation-service-live");
    let terminal = frames
        .iter()
        .filter_map(|frame| serde_json::from_str::<Value>(frame).ok())
        .find(|frame| {
            frame["kind"] == "authorization_invalidation"
                && frame["resolution"]["kind"] == "terminalDelete"
        })
        .expect("scope tombstone projects an immediate terminal delete");
    assert_eq!(terminal["obligation"]["maxDisposition"], "delete");
    assert!(
        terminal.get("snapshot").is_none(),
        "a terminal scope cannot publish a successor snapshot"
    );
    assert_eq!(
        snapback
            .auth_database_mut()
            .current_auth_scope_basis("fn:listItems", &FunctionKind::LiveQuery, false)
            .expect("read predecessor scope basis"),
        None
    );
}

#[test]
fn real_sessions_activation_keeps_removed_function_basis_terminal_across_readd() {
    let (schema, predecessor_functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions.clone());
    install_test_invalidation(&mut snapback);
    assert_eq!(
        snapback
            .auth_database_mut()
            .current_auth_scope_basis("fn:listItems", &FunctionKind::LiveQuery, false)
            .unwrap(),
        Some(0)
    );
    let initial_authorization = snapback
        .auth_database_mut()
        .authorization_version()
        .unwrap();

    let mut removed = predecessor_functions.clone();
    removed.bundle_hash = Some(format!("{FUNCTION_V1_PREFIX}{}", "e".repeat(64)));
    removed.functions.clear();
    let prepared = snapback
        .prepare_auth_provision(EnsureAppMode::Sessions, None, Some(removed), None)
        .unwrap();
    let transition = snapback.admission.clone().begin_transition().unwrap();
    transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            Ok(((), committed.state().clone()))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("remove function through real sessions activation");
    assert_eq!(
        snapback
            .auth_database_mut()
            .current_auth_scope_basis("fn:listItems", &FunctionKind::LiveQuery, false)
            .unwrap(),
        None
    );
    let removed_authorization = snapback
        .auth_database_mut()
        .authorization_version()
        .unwrap();
    assert_eq!(removed_authorization.epoch, initial_authorization.epoch + 1);

    let mut readded = predecessor_functions;
    readded.bundle_hash = Some(format!("{FUNCTION_V1_PREFIX}{}", "f".repeat(64)));
    let prepared = snapback
        .prepare_auth_provision(EnsureAppMode::Sessions, None, Some(readded), None)
        .unwrap();
    let transition = snapback.admission.clone().begin_transition().unwrap();
    transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            Ok(((), committed.state().clone()))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("re-add function through real sessions activation");
    assert_eq!(
        snapback
            .auth_database_mut()
            .current_auth_scope_basis("fn:listItems", &FunctionKind::LiveQuery, false)
            .unwrap(),
        Some(1),
        "re-add resumes at the removal tombstone generation"
    );
    let readded_authorization = snapback
        .auth_database_mut()
        .authorization_version()
        .unwrap();
    assert_eq!(readded_authorization.epoch, initial_authorization.epoch + 2);
}

#[test]
fn same_mode_sessions_activation_projection_error_stays_closed() {
    let (schema, predecessor_functions) = sessions_activation_pair('b', false);
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions);
    let connection = install_test_invalidation(&mut snapback);
    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "activation-exhausted".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(91)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("subscribe auth-scoped predecessor");
    snapback
        .auth_invalidation
        .as_mut()
        .expect("installed invalidation state")
        .next_cause_sequence = crate::auth::invalidation::MAX_PROTOCOL_COUNTER;

    let (_, successor_functions) = sessions_activation_pair('e', true);
    let successor_bundle = successor_functions.bundle_hash.clone().unwrap();
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions),
            None,
        )
        .expect("preflight successor");
    let controller = snapback.admission.clone();
    let transition = controller.begin_transition().expect("close predecessor");
    let error = transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            let state = committed.state().clone();
            Ok((committed, state))
        })
        .expect_err("projection exhaustion must fail the activation");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_AUTH_INVALIDATION_CAUSE_EXHAUSTED"
    );
    assert!(!controller.snapshot().accepting);
    assert!(
        snapback
            .subscriptions
            .contains_key(&subscribed.subscription_id)
    );
    assert_eq!(
        snapback
            .auth_database_mut()
            .auth_mode_snapshot()
            .expect("durable successor")
            .state
            .active_deployment
            .expect("successor deployment")
            .bundle_hash,
        successor_bundle
    );
}

#[test]
fn activation_terminally_resyncs_unscoped_live_queries_changed_or_removed() {
    let (schema, mut predecessor_functions) = sessions_activation_pair('b', false);
    let independent = |name: &str| {
        let mut function = FunctionDefinition::new(
            name,
            FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
                table_visibility: None,
                table: "items".to_owned(),
                filters: Vec::new(),
                order: Vec::new(),
                limit: None,
                membership_filters: Vec::new(),
                indexed_by: None,
            })),
        );
        function.authority_independent = true;
        function.auth_requirement = Some(crate::manifest::AuthRequirement::Public);
        function
    };
    predecessor_functions.functions = vec![
        independent("independentChanged"),
        independent("independentRemoved"),
    ];
    let mut snapback = settled_sessions_activation_snapback(schema, predecessor_functions.clone());
    let connection = install_test_invalidation(&mut snapback);
    let changed_fence = crate::ephemeral::ConnectionEffectFence::anonymous(
        "activation-incarnation",
        "activation-changed-grant",
    );
    let removed_fence = crate::ephemeral::ConnectionEffectFence::anonymous(
        "activation-incarnation",
        "activation-removed-grant",
    );
    let subscribe = |snapback: &mut LocalSnapback,
                     name: &str,
                     connection_id: &str,
                     effect_fence: crate::ephemeral::ConnectionEffectFence| {
        snapback
            .subscribe_live_with_invalidation(
                name,
                LiveSubscribeInput {
                    connection_id: connection_id.to_owned(),
                    input: HandlerInput::default(),
                    authorization_namespace: None,
                    supersedes: None,
                    resume_from_token: None,
                },
                LiveInvalidationAdmission {
                    session_mode: true,
                    connection: Some(connection.clone()),
                    effect_fence: Some(effect_fence),
                },
            )
            .expect("subscribe authority-independent predecessor")
    };
    let changed = subscribe(
        &mut snapback,
        "independentChanged",
        "activation-independent-changed",
        changed_fence.clone(),
    );
    let removed = subscribe(
        &mut snapback,
        "independentRemoved",
        "activation-independent-removed",
        removed_fence.clone(),
    );
    assert!(
        snapback
            .subscriptions
            .values()
            .all(|subscription| subscription.authorization.is_none())
    );
    drain_live_stream_through_fenced_test_sink(
        &snapback,
        "activation-independent-changed",
        &changed_fence,
    );
    drain_live_stream_through_fenced_test_sink(
        &snapback,
        "activation-independent-removed",
        &removed_fence,
    );
    let changed_subscription = snapback
        .subscriptions
        .get(&changed.subscription_id)
        .expect("changed predecessor remains live")
        .clone();
    snapback.enqueue_subscription_durable(
        &changed_subscription,
        serde_json::to_vec(&crate::live_wire::LiveEnvelope::LiveReplace {
            network_profile: None,
            subscription_id: changed.subscription_id.clone(),
            function: "independentChanged".to_owned(),
            version: 1,
            rows: vec![json!({ "value": "queued-predecessor" })],
            resume: None,
        })
        .expect("serialize queued predecessor frame"),
    );

    let mut protected = FunctionDefinition::new(
        "independentChanged",
        FunctionKind::LiveQuery,
        FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
            table_visibility: None,
            table: "items".to_owned(),
            filters: Vec::new(),
            order: Vec::new(),
            limit: None,
            membership_filters: Vec::new(),
            indexed_by: None,
        })),
    );
    protected.auth_requirement = Some(crate::manifest::AuthRequirement::Authenticated);
    let mut successor_functions = predecessor_functions;
    successor_functions.bundle_hash = Some(format!("{}{}", FUNCTION_V1_PREFIX, "f".repeat(64)));
    successor_functions.functions = vec![protected];
    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            Some(successor_functions),
            None,
        )
        .expect("preflight protected successor");
    let controller = snapback.admission.clone();
    let transition = controller.begin_transition().expect("close predecessor");
    transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            let state = committed.state().clone();
            Ok((committed, state))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("activate protected successor");

    assert!(
        !snapback
            .subscriptions
            .contains_key(&changed.subscription_id)
    );
    assert!(
        !snapback
            .subscriptions
            .contains_key(&removed.subscription_id)
    );
    let changed_frames = drain_live_stream_through_fenced_test_sink(
        &snapback,
        "activation-independent-changed",
        &changed_fence,
    );
    assert!(changed_frames.iter().all(|frame| {
        serde_json::from_str::<Value>(frame).is_ok_and(|frame| frame["kind"] != "live_replace")
    }));
    assert!(changed_frames.iter().any(|frame| {
        serde_json::from_str::<Value>(frame).is_ok_and(|frame| {
            frame["kind"] == "resync_required"
                && frame["reason"] == "outbox_overflow"
                && frame["subscription_id"].is_null()
                && frame["clear_retained"] == true
        })
    }));

    let removed_frames = drain_live_stream_through_fenced_test_sink(
        &snapback,
        "activation-independent-removed",
        &removed_fence,
    );
    assert!(removed_frames.iter().any(|frame| {
        serde_json::from_str::<Value>(frame).is_ok_and(|frame| {
            frame["kind"] == "resync_required"
                && frame["reason"] == "auth_deployment_activated"
                && frame["subscription_id"] == removed.subscription_id
                && frame["clear_retained"] == true
        })
    }));
}

#[test]
fn data_only_same_mode_seed_refreshes_auth_scoped_live_before_reopening() {
    let (mut schema, mut functions) = sessions_activation_pair('b', false);
    schema.tables.push(TableManifest {
        name: "freshItems".to_owned(),
        fields: vec![FieldManifest {
            name: "value".to_owned(),
            field_type: FieldType::String,
            optional: false,
        }],
        indexes: Vec::new(),
        syncable: true,
        permission_backing: false,
        permission_fields: None,
        search_indexes: Vec::new(),
        vector_indexes: Vec::new(),
        search_live_limits: None,
        membership: None,
        authority_profile: None,
        asset_sharing: None,
        visibility: None,
        history: None,
    });
    let function = functions
        .functions
        .first_mut()
        .expect("activation live function");
    function.runtime = FunctionRuntime::HostPlan(HandlerPlan::Query(QueryPlan {
        table_visibility: None,
        table: "freshItems".to_owned(),
        filters: Vec::new(),
        order: Vec::new(),
        limit: None,
        membership_filters: Vec::new(),
        indexed_by: None,
    }));
    let mut snapback = settled_sessions_activation_snapback(schema, functions);
    let connection = install_test_invalidation(&mut snapback);
    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "activation-data-seed".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(92)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("subscribe empty auth-scoped result");
    assert!(subscribed.snapshot.as_ref().unwrap().rows.is_empty());
    drain_live_stream_through_test_sink(&mut snapback, "activation-data-seed");
    let predecessor_authorization = snapback
        .auth_invalidation
        .as_ref()
        .expect("installed invalidation state")
        .obligations
        .expectation()
        .authorization
        .clone();

    let prepared = snapback
        .prepare_auth_provision(
            EnsureAppMode::Sessions,
            None,
            None,
            Some(SeedData {
                tables: BTreeMap::from([(
                    "freshItems".to_owned(),
                    vec![Map::from_iter([(
                        "value".to_owned(),
                        json!("seed-visible"),
                    )])],
                )]),
            }),
        )
        .expect("preflight data-only seed against cached pair");
    let controller = snapback.admission.clone();
    let transition = controller.begin_transition().expect("close predecessor");
    let (committed, _, reopened) = transition
        .commit_and_project_mode_state(|projection_admission| {
            let committed = snapback.commit_auth_provision_classified(
                prepared,
                "test",
                Some(projection_admission),
            )?;
            let state = committed.state().clone();
            Ok((committed, state))
        })
        .and_then(|committed| committed.publish_successor())
        .expect("seed and refresh under closed activation");
    assert_eq!(committed.into_outcome().seed, "seeded");
    assert!(reopened.accepting);
    assert_eq!(
        snapback
            .auth_invalidation
            .as_ref()
            .expect("installed invalidation state")
            .obligations
            .expectation()
            .authorization,
        predecessor_authorization,
        "ordinary seed rows do not fabricate an authorization epoch"
    );
    // @ref LLP 0094#0c8-sessions-live-update-envelope-and-delivery-multiplicity —
    // the data-only successor snapshot is retained projection truth, not a
    // second physical outbox copy.
    let successor_admission = controller
        .admit_for_mode(AuthMode::Sessions)
        .expect("successor admission projects the seeded snapshot");
    let frames = project_authorization_frames_through_test_sink(
        &mut snapback,
        "activation-data-seed",
        &successor_admission,
    );
    assert!(frames.iter().any(|frame| {
        serde_json::from_str::<Value>(frame).is_ok_and(|frame| {
            frame["kind"] == "authorization_invalidation"
                && frame["snapshot"]["rows"]
                    .as_array()
                    .is_some_and(|rows| rows.len() == 1)
        })
    }));
}

const SCHEMA_RELOAD_SOURCE: &str = r#"
globalThis.__snapbackHandlers = {
  async insertOld(ctx) {
    return await ctx.db.insert('items', { value: 'old-schema' });
  },
  async readNewTable(ctx) {
    return (await ctx.db.query('new_items').collect()).length;
  }
};
"#;

fn settled_sessions_state() -> AuthModeStateRecord {
    let digest = |prefix: &str, byte: char| format!("{prefix}{}", byte.to_string().repeat(64));
    let deployment = DeploymentIdentity {
        schema_version: "snapback.v1".to_owned(),
        auth_mode: AuthMode::Sessions,
        app_id: "app".to_owned(),
        schema_hash: digest(SCHEMA_V1_PREFIX, 'a'),
        bundle_hash: digest(FUNCTION_V1_PREFIX, 'b'),
        inputs_hash: digest(INPUTS_V1_PREFIX, 'c'),
    };
    let mut state = AuthModeStateRecord::initial_dev(Some(deployment.clone()));
    state.transition_generation = 4;
    state.active = AuthMode::Sessions;
    state.desired = AuthMode::Sessions;
    state.sessions_ever_activated = true;
    state.active_deployment = Some(deployment);
    state
        .validate_shape()
        .expect("valid settled Sessions state");
    state
}

fn install_cron_gate(mut snapback: LocalSnapback) -> LocalSnapback {
    let manifest = FunctionManifest {
        functions: vec![FunctionDefinition::new(
            "cronAction",
            FunctionKind::Action,
            FunctionRuntime::HostPlan(HandlerPlan::Action(ActionPlan {
                steps: Vec::new(),
                return_value: None,
            })),
        )],
        cron_jobs: vec![CronJobDefinition {
            name: "gatedCron".to_owned(),
            schedule: CronSchedule {
                every_ms: Some(60_000),
                cron: None,
            },
            action: "cronAction".to_owned(),
            enabled: true,
            activation: CronActivationPolicy::default(),
            jitter_policy: CronJitterPolicy {
                enabled: false,
                max_offset_ms: 0,
            },
            overlap_policy: CronOverlapPolicy::NoOverlap,
            retry_policy: CronRetryPolicy {
                mode: CronRetryMode::NextTick,
            },
            required_capabilities: Vec::new(),
            target_wakeup: None,
            source_span: None,
        }],
        ..FunctionManifest::default()
    };
    let diagnostics = snapback.load_functions(manifest);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "cron gate fixture must load: {diagnostics:?}"
    );
    snapback
}

fn cron_gate_snapback() -> LocalSnapback {
    install_cron_gate(LocalSnapback::memory().expect("memory cron gate fixture"))
}

#[test]
fn failed_cron_keeps_attached_diagnostic_without_standalone_duplicate() {
    let directory = tempfile::tempdir().expect("failed cron telemetry directory");
    let database_path = directory.path().join("failed-cron.sqlite3");
    let mut snapback =
        install_cron_gate(LocalSnapback::open(&database_path).expect("failed cron fixture"));
    let claim = snapback
        .claim_manual_cron_run("gatedCron", 10)
        .expect("claim failed cron fixture");
    let record = snapback
        .finish_cron_claim(
            claim,
            now_millis(),
            Err(crate::diagnostic::Diagnostic::error(
                "SNAPBACK_CRON_TEST_FAILURE",
                "cron",
                "closed fixture failure",
            )),
        )
        .expect("publish failed cron terminal");
    assert_eq!(record.outcome, crate::cron::CronRunOutcome::Failed);
    assert!(
        snapback
            .recent_diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code == "SNAPBACK_CRON_TEST_FAILURE")
    );
    snapback
        .telemetry
        .force_flush()
        .expect("flush failed cron telemetry");
    assert_eq!(
        snapback
            .telemetry
            .event_outcomes_for_test("job_run", "gatedCron", "joined"),
        vec![(Some(500), Some("SNAPBACK_CRON_TEST_FAILURE".to_owned()))]
    );
    assert_eq!(
        snapback.telemetry.event_count_for_test(
            "diagnostic",
            "SNAPBACK_CRON_TEST_FAILURE",
            "point"
        ),
        0,
    );
}

#[test]
fn stream_requiring_artifact_is_refused_against_the_served_instance_manifest() {
    // @ref LLP 0076#target-contract — the outbound-disabled negative
    // admission witness: with egress off in THIS process, the served
    // instance manifest does not support bounded_response_stream_v1 and
    // the loader refuses the artifact before any handler can run.
    assert!(
        std::env::var("SNAPBACK_OUTBOUND_ACTIONS").is_err(),
        "lib tests run with egress disabled"
    );
    let mut action = FunctionDefinition::new(
        "streamRequiring",
        FunctionKind::Action,
        FunctionRuntime::IbexModule(IbexModule {
            source: "globalThis.__snapbackHandlers = { async streamRequiring() { return null; } };"
                .to_owned(),
            export: "streamRequiring".to_owned(),
        }),
    );
    action.required_capabilities = vec!["bounded_response_stream_v1".to_owned()];
    let mut snapback = LocalSnapback::memory().expect("memory instance");
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![action],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics.iter().any(|diagnostic| {
            diagnostic.code == "SNAPBACK_CAPABILITY_UNSUPPORTED"
                && diagnostic.severity == crate::diagnostic::DiagnosticSeverity::Error
        }),
        "egress-disabled admission must refuse: {diagnostics:?}"
    );
    // Nothing was installed: the function is unknown to the instance.
    let run = snapback.run_function("streamRequiring", HandlerInput::default());
    assert!(!run.ok, "refused artifact must not be invocable");
}

#[test]
fn raw_dev_function_loader_rejects_sessions_half_before_publication() {
    let mut snapback = LocalSnapback::memory().unwrap();
    let before = snapback.functions.clone();
    let manifest = FunctionManifest {
        schema_version: crate::manifest::SNAPBACK_SESSIONS_SCHEMA_VERSION.to_owned(),
        ..FunctionManifest::default()
    };
    let error = snapback
        .load_functions_in_settled_dev(manifest)
        .unwrap_err();
    assert_eq!(error.diagnostic.code, "SNAPBACK_CAPABILITY_UNSUPPORTED");
    assert_eq!(snapback.functions, before);
}

#[test]
fn closed_admission_cannot_mutate_or_persist_scheduled_or_manual_cron_claim() {
    let mut snapback = cron_gate_snapback();
    let before = snapback.cron.persisted_value().unwrap();
    let writes = snapback.cron_state_writes();
    let guard = snapback.admission.begin_transition().unwrap();

    let Err(scheduled_error) = snapback.claim_due_cron_runs(0) else {
        panic!("closed scheduled claim must fail");
    };
    assert_eq!(
        scheduled_error.diagnostic.code,
        "SNAPBACK_AUTH_MODE_PENDING"
    );
    let Err(manual_error) = snapback.claim_manual_cron_run("gatedCron", 0) else {
        panic!("closed manual claim must fail");
    };
    assert_eq!(manual_error.diagnostic.code, "SNAPBACK_AUTH_MODE_PENDING");
    assert_eq!(snapback.cron.persisted_value().unwrap(), before);
    assert_eq!(snapback.cron_state_writes(), writes);
    drop(guard);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn admitted_cron_claim_may_finish_while_transition_drains() {
    let mut snapback = cron_gate_snapback();
    let claim = snapback
        .claim_manual_cron_run("gatedCron", 10)
        .expect("admitted manual claim");
    let controller = snapback.admission.clone();
    let (closed_tx, closed_rx) = tokio::sync::oneshot::channel();
    let transition = tokio::spawn(async move {
        controller
            .begin_transition_async(move || {
                let _ = closed_tx.send(());
                Ok(())
            })
            .await
    });
    closed_rx.await.expect("transition published close");
    assert!(!snapback.admission.snapshot().accepting);

    let record = snapback
        .finish_cron_claim(claim, super::now_millis(), Ok(json!({ "ok": true })))
        .expect("old admitted claim linearizes finish before retirement");
    assert_eq!(record.outcome, crate::cron::CronRunOutcome::Succeeded);
    let guard = transition
        .await
        .expect("transition task")
        .expect("claim drained");
    guard.abort_and_reopen().expect("reopen after test drain");
}

#[test]
fn timeout_retirement_suppresses_cron_finish_and_result_ledger_publication() {
    let directory = tempfile::tempdir().expect("cron telemetry fixture directory");
    let database_path = directory.path().join("cron-telemetry.sqlite3");
    let mut snapback = install_cron_gate(
        LocalSnapback::open(&database_path).expect("file-backed cron gate fixture"),
    );
    let claim = snapback
        .claim_manual_cron_run("gatedCron", 20)
        .expect("admitted manual claim");
    let before = snapback.cron.persisted_value().unwrap();
    let writes = snapback.cron_state_writes();
    let error = snapback
        .admission
        .retire_current_epoch_for_test()
        .unwrap_err();
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_AUTH_MODE_QUIESCENCE_TIMEOUT"
    );

    assert_eq!(
        snapback
            .finish_cron_claim(claim, super::now_millis(), Ok(json!({ "ok": true })))
            .unwrap_err()
            .diagnostic
            .code,
        "SNAPBACK_AUTH_MODE_PENDING"
    );
    assert_eq!(snapback.cron.persisted_value().unwrap(), before);
    assert_eq!(snapback.cron_state_writes(), writes);
    snapback
        .telemetry
        .force_flush()
        .expect("flush rejected cron terminal");
    let terminal =
        physical_telemetry_events_for_test(&snapback.telemetry, Some("job_run"), Some("gatedCron"))
            .into_iter()
            .next_back()
            .expect("cron publication guard terminal observation");
    assert_eq!(
        (
            terminal.phase.as_str(),
            terminal.status,
            terminal.code.as_deref()
        ),
        ("joined", Some(500), Some("SNAPBACK_AUTH_MODE_PENDING"))
    );
}

