// @ref LLP 0157#sbsb2-plaintext-and-budget — establishment uses the
// exact 6,099-byte compact body, class-specific root tables, and the
// closed integer/string/id/boolean templates before any application read.
#[test]
fn snapshot_batch_v2_budget_pins_closed_templates_at_6099_and_refuses_6100() {
    let (mut schema, functions, plan) = snapshot_batch_v2_publication_fixture(1, 1);
    schema
        .tables
        .iter_mut()
        .find(|table| table.name == "children")
        .and_then(|table| table.fields.iter_mut().find(|field| field.name == "label"))
        .expect("bounded id order field")
        .field_type = FieldType::Id {
        table: "parents".to_owned(),
    };
    let mut snapback = LocalSnapback::memory().expect("v2 budget store");
    snapback
        .apply_schema(schema)
        .expect("apply v2 budget schema");
    let function = functions
        .functions
        .iter()
        .find(|function| function.name == "mixedView")
        .expect("mixed function");
    let identity =
        crate::manifest::snapshot_batch_identity_v2(function, &plan).expect("v2 budget identity");
    let db = DbRead::Live(&snapback.db);
    let bounded = match &plan.nodes[0] {
        crate::manifest::SnapshotBatchNodeV2::BoundedChildren(node) => node,
        _ => unreachable!("bounded first node"),
    };
    let relational = match &plan.nodes[1] {
        crate::manifest::SnapshotBatchNodeV2::RelationalQuery(node) => node,
        _ => unreachable!("relational second node"),
    };
    assert_eq!(
        super::snapshot_batch_max_boundary_for(&db, &bounded.child_table, &bounded.order)
            .expect("bounded closed templates"),
        vec![
            Value::from(-9_007_199_254_740_991_i64),
            Value::String("\u{0}".repeat(32)),
            Value::Bool(false),
        ]
    );
    assert_eq!(
        super::snapshot_batch_max_boundary_for(&db, &relational.root, &relational.order)
            .expect("relational closed string template"),
        vec![Value::String("\u{0}".repeat(32))]
    );

    let authority_partition = format!("sha256:{}", "a".repeat(64));
    let parents = ["parent-a".to_owned()];
    let empty = json!({"parentId":"parent-a","padding":""});
    let base = super::snapshot_batch_v2_max_plaintext_len(
        &db,
        &plan,
        &identity,
        "generation-maximum-spelling",
        "app",
        "database",
        "stream",
        &function.id,
        &empty,
        &authority_partition,
        &parents,
    )
    .expect("v2 base maximum");
    let padding = crate::snapshot_batch_cursor_v2::MAX_PLAINTEXT_BYTES
        .checked_sub(base)
        .expect("v2 fixture starts below budget");
    let at_limit = json!({"parentId":"parent-a","padding":"x".repeat(padding)});
    assert_eq!(
        super::snapshot_batch_v2_max_plaintext_len(
            &db,
            &plan,
            &identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &at_limit,
            &authority_partition,
            &parents,
        )
        .expect("exact v2 maximum"),
        6_099
    );
    super::enforce_snapshot_batch_v2_cursor_budget(
        &db,
        &plan,
        &identity,
        "generation-maximum-spelling",
        "app",
        "database",
        "stream",
        &function.id,
        &at_limit,
        &authority_partition,
        &parents,
    )
    .expect("6,099 bytes admits");
    let over = json!({"parentId":"parent-a","padding":"x".repeat(padding + 1)});
    assert_eq!(
        super::snapshot_batch_v2_max_plaintext_len(
            &db,
            &plan,
            &identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &over,
            &authority_partition,
            &parents,
        )
        .expect("one byte over v2 maximum"),
        6_100
    );
    assert_eq!(
        super::enforce_snapshot_batch_v2_cursor_budget(
            &db,
            &plan,
            &identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &over,
            &authority_partition,
            &parents,
        )
        .expect_err("6,100 bytes refuses")
        .diagnostic
        .code,
        "SNAPBACK_SNAPSHOT_BATCH_CURSOR_BUDGET_EXCEEDED"
    );

    let mut unbounded = plan;
    let crate::manifest::SnapshotBatchNodeV2::RelationalQuery(relational) = &mut unbounded.nodes[1]
    else {
        unreachable!("relational node")
    };
    relational.order[0].max_encoded_bytes = None;
    let unbounded_identity = crate::manifest::snapshot_batch_identity_v2(function, &unbounded)
        .expect("unbounded v2 structural identity");
    assert_eq!(
        super::enforce_snapshot_batch_v2_cursor_budget(
            &db,
            &unbounded,
            &unbounded_identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &empty,
            &authority_partition,
            &parents,
        )
        .expect_err("unbounded relational order refuses before reads")
        .diagnostic
        .code,
        "SNAPBACK_SNAPSHOT_BATCH_CURSOR_BUDGET_EXCEEDED"
    );
}

#[test]
fn snapshot_batch_v2_pins_mixed_nodes_across_a_sibling_commit() {
    let dir = tempfile::tempdir().expect("v2 snapshot directory");
    let path = dir.path().join("snapshot-batch-v2.sqlite3");
    let (schema, functions, _) = snapshot_batch_v2_publication_fixture(2, 2);
    let mut reader = LocalSnapback::open(&path).expect("v2 snapshot reader");
    reader.apply_schema(schema).expect("apply mixed schema");
    let diagnostics = reader.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error)
    );
    seed_snapshot_batch_v2_fixture(&mut reader, "private-v2-sibling");

    let (reached_tx, reached_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let _hook =
        crate::storage::set_storage_read_snapshot_debug_hook(&reader.db, reached_tx, release_rx);
    let lane = reader.read_lane();
    let writer = std::thread::spawn(move || {
        reached_rx
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("v2 reader pins predecessor snapshot");
        reader
            .invoke_mutation(
                "addChild",
                HandlerInput {
                    args: json!({
                        "parentId":"parent-a", "position":5, "label":"concurrent-v2",
                        "active":false, "externalKey":"snapshot-v2-concurrent"
                    }),
                    auth: AuthInput {
                        user_id: Some("user-a".to_owned()),
                        ..AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
            )
            .expect("bounded commit through the serving writer");
        reader
            .seed(crate::manifest::SeedData {
                tables: BTreeMap::from([(
                    "books".to_owned(),
                    vec![
                        json!({
                            "_id":"book-concurrent", "title":"aardvark",
                            "authorSlug":"ada", "ownerId":"user-a"
                        })
                        .as_object()
                        .cloned()
                        .expect("concurrent book"),
                    ],
                )]),
            })
            .expect("relational commit through the serving writer");
        release_tx.send(()).expect("release v2 pinned reader");
    });
    let input = HandlerInput {
        args: json!({"parentId":"parent-a"}),
        auth: AuthInput {
            user_id: Some("user-a".to_owned()),
            ..AuthInput::default()
        },
        ..HandlerInput::default()
    };
    let predecessor = lane
        .invoke_query("mixedView", input.clone())
        .expect("v2 pinned predecessor");
    writer.join().expect("v2 sibling writer joins");
    let predecessor_nodes = predecessor.rows[0]["nodes"]
        .as_array()
        .expect("mixed predecessor tuple");
    for index in [0, 2] {
        assert!(
            predecessor_nodes[index]["children"]
                .as_array()
                .expect("bounded children")
                .iter()
                .all(|child| child["label"] != "concurrent-v2")
        );
    }
    assert_eq!(predecessor_nodes[1][0]["title"], "alpha");

    let successor = lane
        .invoke_query("mixedView", input)
        .expect("v2 successor snapshot");
    assert!(successor.version > predecessor.version);
    let successor_nodes = successor.rows[0]["nodes"]
        .as_array()
        .expect("mixed successor tuple");
    for index in [0, 2] {
        assert_eq!(
            successor_nodes[index]["children"][0]["label"],
            "concurrent-v2"
        );
    }
    assert_eq!(successor_nodes[1][0]["title"], "aardvark");
}

#[test]
fn snapshot_batch_v2_all_relational_executor_uses_one_sbsb2_cursor() {
    use crate::manifest::{
        FunctionArgsContract, ResultObjectFieldContract, ResultValueContract, SnapshotBatchNodeV2,
        SnapshotBatchPlanV2,
    };
    let mut snapback = LocalSnapback::memory().expect("v2 executor shell");
    let (schema, fixture_functions) = relational_live_fixture_functions(1);
    snapback.apply_schema(schema).expect("apply v2 test schema");
    snapback
        .seed(crate::manifest::SeedData {
            tables: BTreeMap::from([
                (
                    "books".to_owned(),
                    vec![
                        json!({"_id":"b1","title":"alpha","authorSlug":"ada","ownerId":"user-a"}),
                        json!({"_id":"b2","title":"beta","authorSlug":"grace","ownerId":"user-a"}),
                    ]
                    .into_iter()
                    .map(|row| row.as_object().cloned().expect("book row"))
                    .collect(),
                ),
                (
                    "authors".to_owned(),
                    vec![
                        json!({"_id":"a1","slug":"ada","name":"Ada"}),
                        json!({"_id":"a2","slug":"grace","name":"Grace"}),
                    ]
                    .into_iter()
                    .map(|row| row.as_object().cloned().expect("author row"))
                    .collect(),
                ),
            ]),
        })
        .expect("seed v2 test rows");
    let mut relational = match &fixture_functions.functions[0].runtime {
        FunctionRuntime::HostPlan(HandlerPlan::RelationalQuery(plan)) => plan.clone(),
        _ => panic!("relational fixture plan"),
    };
    relational.order[0].max_encoded_bytes = Some(32);
    let plan = SnapshotBatchPlanV2 {
        profile: "snapshot-batch.v2".to_owned(),
        nodes: vec![
            SnapshotBatchNodeV2::RelationalQuery(relational.clone()),
            SnapshotBatchNodeV2::RelationalQuery(relational),
        ],
        normalized_composite_plan: Value::Null,
        plan_hash: String::new(),
    };
    let mut function = FunctionDefinition::new(
        "relationalBatch",
        FunctionKind::Query,
        FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(plan.clone())),
    );
    function.args_contract = Some(FunctionArgsContract {
        fields: vec![ResultObjectFieldContract {
            name: "cursor".to_owned(),
            required: false,
            value: ResultValueContract::String { max_bytes: 8_192 },
        }],
    });
    let identity = crate::manifest::snapshot_batch_identity_v2(&function, &plan)
        .expect("all-relational v2 identity");
    let FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(sealed)) = &mut function.runtime
    else {
        unreachable!("v2 plan")
    };
    sealed.normalized_composite_plan = identity.normalized_composite_plan;
    sealed.plan_hash = identity.plan_hash;

    let input = |user_id: Option<&str>, cursor: Option<&str>| {
        let mut args = json!({});
        if let Some(cursor) = cursor {
            args["cursor"] = json!(cursor);
        }
        HandlerInput {
            args,
            auth: AuthInput {
                user_id: user_id.map(ToOwned::to_owned),
                ..AuthInput::default()
            },
            ..HandlerInput::default()
        }
    };
    let invoke = |snapback: &LocalSnapback,
                  function: &FunctionDefinition,
                  input: HandlerInput|
     -> SnapbackResult<QueryOutput> {
        let authority = InvocationGate::prepare_admitted_dev_input(
            InvocationSource::LocalQuery,
            ServerProfile::Dev,
            &input,
            snapback.admission.admit_dev().expect("admit v2 test input"),
        )
        .expect("prepare v2 test authority");
        let prepared = InvocationGate::prepare_function(authority, function)
            .expect("bind v2 function authority");
        super::execute_snapshot_batch_v2(
            function,
            match &function.runtime {
                FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(plan)) => plan,
                _ => unreachable!("v2 plan"),
            },
            &DbRead::Live(&snapback.db),
            &input,
            &prepared,
            Some(super::RelationalCursorAuthority {
                app_id: "snapshot-batch-v2-test-app",
                keyring: &snapback.resume_keyring,
                schema_hash: None,
                function_bundle_hash: None,
                function_publication_generation: 0,
                target_profile: Some(crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX),
            }),
        )
        .map(|invocation| invocation.output)
    };

    let first = invoke(&snapback, &function, input(Some("user-a"), None))
        .expect("execute first v2 relational batch");
    assert_eq!(first.rows[0]["kind"], "visible");
    let first_nodes = first.rows[0]["nodes"].as_array().expect("v2 tuple");
    assert_eq!(first_nodes.len(), 2);
    assert!(first_nodes.iter().all(|node| node.as_array().is_some()));
    let cursor = first.rows[0]["continuation"]
        .as_str()
        .expect("coordinated v2 continuation")
        .to_owned();
    assert!(cursor.starts_with("sbsb2."));
    let database_id = DbRead::Live(&snapback.db)
        .search_database_identity()
        .expect("database identity");
    let body = crate::snapshot_batch_cursor_v2::decode(
        &cursor,
        &snapback
            .resume_keyring
            .read()
            .expect("keyring")
            .snapshot_batch_cursor_v2_materials(now_millis()),
        "snapshot-batch-v2-test-app",
        &database_id,
        crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
        now_millis(),
    )
    .expect("decode executor cursor");
    assert!(body.parent_groups.is_empty());
    assert!(body.nodes.iter().all(|node| matches!(
        node.state,
        crate::snapshot_batch_cursor_v2::NodeState::RelationalBoundary { .. }
    )));

    let second = invoke(&snapback, &function, input(Some("user-a"), Some(&cursor)))
        .expect("execute resumed v2 relational batch");
    assert_eq!(second.rows[0]["kind"], "visible");
    assert!(second.rows[0]["continuation"].is_string());

    let zero_rows = invoke(&snapback, &function, input(Some("user-c"), None))
        .expect("a visible all-relational empty page is not absence");
    assert_eq!(
        zero_rows.rows,
        vec![json!({"kind":"visible","nodes":[[],[]],"continuation":null})]
    );
    let refused = invoke(&snapback, &function, input(None, None))
        .expect_err("relational invocation refusal must escape the batch envelope");
    assert_eq!(refused.diagnostic.code, "SNAPBACK_AUTH_USER_MISSING");

    let mut zero_plan = plan;
    for node in &mut zero_plan.nodes {
        let SnapshotBatchNodeV2::RelationalQuery(node) = node else {
            unreachable!("all-relational zero-take tuple")
        };
        node.take = 0;
    }
    let mut zero_function = FunctionDefinition::new(
        "relationalBatchZero",
        FunctionKind::Query,
        FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(zero_plan.clone())),
    );
    zero_function.args_contract = function.args_contract.clone();
    let zero_identity = crate::manifest::snapshot_batch_identity_v2(&zero_function, &zero_plan)
        .expect("zero-take identity");
    assert_eq!(zero_identity.node_examined_entry_ceilings, vec![0, 0]);
    assert_eq!(zero_identity.node_joined_lookup_ceilings, vec![0, 0]);
    assert_eq!(zero_identity.parent_authorization_group_count, 0);
    let FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(sealed)) =
        &mut zero_function.runtime
    else {
        unreachable!("zero-take v2 plan")
    };
    sealed.normalized_composite_plan = zero_identity.normalized_composite_plan;
    sealed.plan_hash = zero_identity.plan_hash;
    let zero = invoke(&snapback, &zero_function, input(Some("user-a"), None))
        .expect("take zero consumes no relational work");
    assert_eq!(
        zero.rows,
        vec![json!({"kind":"visible","nodes":[[],[]],"continuation":null})]
    );
}

// @ref LLP 0135#5-executable-acceptance — executable Relay-shaped proof: three
// bounded nodes, one parent authorization group, one coordinated `sbsb1`
// continuation, sealed absence, exact resume, and whole-batch live replace.
#[test]
fn snapshot_batch_three_node_cursor_sealing_and_live_acceptance() {
    let (mut schema, mut functions, _plan) = snapshot_batch_publication_fixture(3, 2);
    schema.app_id = "snapshot-batch-proof-app".to_owned();
    schema.schema_hash = Some("sha256:snapshot-batch-proof-schema".to_owned());
    schema.inputs_hash = Some("sha256:snapshot-batch-proof-inputs".to_owned());
    functions.app_id = schema.app_id.clone();
    functions.schema_version = schema.schema_version.clone();
    functions.bundle_hash = Some("sha256:snapshot-batch-proof-functions".to_owned());
    functions.inputs_hash = schema.inputs_hash.clone();
    let expected_generation = ArtifactGeneration {
        schema_version: schema.schema_version.clone(),
        app_id: schema.app_id.clone(),
        schema_hash: schema.schema_hash.clone().expect("schema identity"),
        bundle_hash: functions.bundle_hash.clone().expect("function identity"),
        inputs_hash: schema.inputs_hash.clone().expect("input identity"),
    };

    let mut snapback = LocalSnapback::memory().expect("snapshot batch store");
    snapback.apply_schema(schema).expect("apply schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "snapshot batch fixture must activate: {diagnostics:?}",
    );
    let database_id = snapback.db.data_version_stream().expect("data stream");
    let activation = crate::completeness::TrustedCompositionActivationV1::prepare(
        database_id,
        "snapshot-batch-proof-deployment",
        crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
        "dev",
        expected_generation,
        snapback
            .proof_keyring
            .read()
            .expect("proof keyring")
            .manifest(),
    )
    .expect("prepare trusted activation");
    snapback
        .install_trusted_composition_activation(activation)
        .expect("install trusted activation");
    seed_bounded_publication_fixture(&mut snapback, "private");
    let input = |parent: &str, cursor: Option<&str>| {
        let mut args = json!({"parentId": parent});
        if let Some(cursor) = cursor {
            args["cursor"] = json!(cursor);
        }
        HandlerInput {
            args,
            auth: AuthInput {
                user_id: Some("user-a".to_owned()),
                ..AuthInput::default()
            },
            ..HandlerInput::default()
        }
    };
    let namespace = QueryNamespace {
        client_store_id: "snapshot-batch-proof-store".to_owned(),
        query_key: "qmk1.2pHUpZC2tE1XKzuxDTpdB_d7Sck3pN0ZHzs4CPiQXME".to_owned(),
        query_instance_id: 23,
    };
    let first_input = input("parent-a", None);
    let first_authority = InvocationGate::prepare_admitted_dev_input(
        InvocationSource::LocalQuery,
        ServerProfile::Dev,
        &first_input,
        snapback
            .admission
            .admit_dev()
            .expect("admit first finite page"),
    )
    .expect("prepare first finite authority");
    let first = snapback
        .invoke_finite_query_prepared_generation(
            "boardView",
            first_input,
            first_authority,
            None,
            Some(&namespace),
            &[],
        )
        .expect("first composite page");
    let first_proof = first
        .completeness_proof
        .clone()
        .expect("first continuation proof");
    assert!(first.page_set_manifest.is_none());
    let first_row = &first.output.rows[0];
    assert_eq!(first_row["kind"], "visible");
    let nodes = first_row["nodes"].as_array().expect("node tuple");
    assert_eq!(nodes.len(), 3);
    assert!(nodes.iter().all(|node| node.get("continuation").is_none()));
    let cursor = first_row["continuation"]
        .as_str()
        .expect("coordinated continuation")
        .to_owned();
    assert!(cursor.starts_with("sbsb1."));
    let mut tampered_prior = first_proof.clone();
    tampered_prior.signature.replace_range(
        0..1,
        if tampered_prior.signature.starts_with('A') {
            "B"
        } else {
            "A"
        },
    );
    let refused_input = input("parent-a", Some(&cursor));
    let refused_authority = InvocationGate::prepare_admitted_dev_input(
        InvocationSource::LocalQuery,
        ServerProfile::Dev,
        &refused_input,
        snapback
            .admission
            .admit_dev()
            .expect("admit refused continuation"),
    )
    .expect("prepare refused continuation authority");
    let refused = snapback
        .invoke_finite_query_prepared_generation(
            "boardView",
            refused_input,
            refused_authority,
            None,
            Some(&namespace),
            &[tampered_prior],
        )
        .expect_err("tampered prior proof must refuse the whole carrier");
    assert_eq!(
        refused.diagnostic.code,
        "SNAPBACK_COMPLETENESS_PROOF_ISSUANCE_FAILED"
    );
    let second_input = input("parent-a", Some(&cursor));
    let second_authority = InvocationGate::prepare_admitted_dev_input(
        InvocationSource::LocalQuery,
        ServerProfile::Dev,
        &second_input,
        snapback
            .admission
            .admit_dev()
            .expect("admit continuation page"),
    )
    .expect("prepare continuation authority");
    let second = snapback
        .invoke_finite_query_prepared_generation(
            "boardView",
            second_input,
            second_authority,
            None,
            Some(&namespace),
            std::slice::from_ref(&first_proof),
        )
        .expect("second composite page");
    let second_proof = second
        .completeness_proof
        .clone()
        .expect("terminal continuation proof");
    let manifest = second
        .page_set_manifest
        .clone()
        .expect("atomic terminal page-set manifest");
    assert_eq!(
        manifest,
        crate::completeness::PageSetManifestV1::compose(&[first_proof, second_proof])
            .expect("compose server page set"),
    );
    assert!(second.output.rows[0]["continuation"].is_null());
    for node in second.output.rows[0]["nodes"]
        .as_array()
        .expect("node tuple")
    {
        let ids = node["children"]
            .as_array()
            .expect("children")
            .iter()
            .map(|child| child["_id"].clone())
            .collect::<Vec<_>>();
        assert_eq!(ids, vec![json!("child-20-b"), json!("child-30")]);
    }
    let malformed_absent = snapback
        .invoke_query("boardView", input("parent-b", Some("sbsb1.malformed")))
        .expect("invisible parent seals before cursor validation");
    assert_eq!(
        malformed_absent.rows,
        vec![json!({"kind":"absent","nodes":null,"continuation":null})],
    );
    let malformed = snapback
        .invoke_query("boardView", input("parent-a", Some("sbsb1.malformed")))
        .expect_err("visible parent validates cursor");
    assert_eq!(
        malformed.diagnostic.code,
        "SNAPBACK_SNAPSHOT_BATCH_CURSOR_INVALID"
    );

    let subscribed = snapback
        .subscribe_live(
            "boardView",
            LiveSubscribeInput {
                connection_id: "conn-snapshot-batch".to_owned(),
                input: input("parent-a", None),
                authorization_namespace: None,
                supersedes: None,
                resume_from_token: None,
            },
        )
        .expect("cursor-free composite live subscription");
    assert_eq!(subscribed.snapshot.unwrap().rows[0]["kind"], "visible");
    snapback
        .invoke_mutation(
            "addChild",
            HandlerInput {
                args: json!({
                    "parentId":"parent-a", "position":5, "label":"live",
                    "active":false, "externalKey":"batch-live"
                }),
                auth: AuthInput {
                    user_id: Some("user-a".to_owned()),
                    ..AuthInput::default()
                },
                ..HandlerInput::default()
            },
        )
        .expect("insert child");
    let frames = rqs_drained_envelopes(&mut snapback, "conn-snapshot-batch");
    assert!(!frames.is_empty());
    assert!(frames.iter().all(|frame| frame["kind"] == "live_replace"));
    let live_cursor_refusal = snapback
        .subscribe_live(
            "boardView",
            LiveSubscribeInput {
                connection_id: "conn-snapshot-cursor".to_owned(),
                input: input("parent-a", Some(&cursor)),
                authorization_namespace: None,
                supersedes: None,
                resume_from_token: None,
            },
        )
        .expect_err("cursor-bearing composite live subscription refuses");
    assert_eq!(
        live_cursor_refusal.diagnostic.code,
        "SNAPBACK_SNAPSHOT_BATCH_LIVE_CURSOR_UNSUPPORTED",
    );
}

#[test]
fn snapshot_batch_cursor_refusal_and_restart_matrix_is_closed() {
    fn remint(
        original: &crate::snapshot_batch_cursor::Body,
        root: &[u8; 32],
        mutate: impl FnOnce(&mut crate::snapshot_batch_cursor::Body),
    ) -> String {
        let mut body = original.clone();
        mutate(&mut body);
        crate::snapshot_batch_cursor::mint(root, &body).expect("remint cursor fixture")
    }

    let (schema, functions, _) = snapshot_batch_publication_fixture(3, 2);
    let mut snapback = LocalSnapback::memory().expect("cursor matrix store");
    snapback.apply_schema(schema).expect("apply schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "cursor matrix fixture activates: {diagnostics:?}",
    );
    seed_bounded_publication_fixture(&mut snapback, "private");
    let first = snapback
        .invoke_query("boardView", bounded_input("parent-a", None))
        .expect("first batch page");
    let cursor = first.rows[0]["continuation"]
        .as_str()
        .expect("coordinated cursor");
    let now = now_millis();
    let database_id = DbRead::Live(&snapback.db)
        .search_database_identity()
        .expect("database identity");
    let (roots, root) = {
        let keyring = snapback
            .resume_keyring
            .read()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let roots = keyring.snapshot_batch_cursor_materials(now);
        let (_, root) = keyring.active_current().expect("active cursor key");
        (roots, root)
    };
    let body = crate::snapshot_batch_cursor::decode(
        cursor,
        &roots,
        "relation-publication",
        &database_id,
        super::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
        now,
    )
    .expect("decode issued cursor");

    let invalid = vec![
        remint(&body, &root, |body| body.app_id = "other-app".to_owned()),
        remint(&body, &root, |body| {
            body.plan_hash = format!("sha256:{}", "0".repeat(64));
        }),
        remint(&body, &root, |body| {
            body.parent_groups[0].parent_id = "parent-c".to_owned();
        }),
        remint(&body, &root, |body| {
            body.authority_partition = format!("sha256:{}", "1".repeat(64));
        }),
        remint(&body, &root, |body| {
            let crate::snapshot_batch_cursor::NodeState::Boundary { boundary, .. } =
                &mut body.nodes[0].state
            else {
                panic!("first node boundary")
            };
            boundary[0] = json!("not-an-integer");
        }),
        cursor.replacen("sbsb1.", "sbbc1.", 1),
    ];
    for wire in invalid {
        let error = snapback
            .invoke_query("boardView", bounded_input("parent-a", Some(&wire)))
            .expect_err("invalid cursor matrix member refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_SNAPSHOT_BATCH_CURSOR_INVALID"
        );
    }

    for wire in [
        remint(&body, &root, |body| {
            body.parent_groups[0].parent_version += 1;
        }),
        remint(&body, &root, |body| {
            body.stream_epoch = "different-stream".to_owned();
        }),
    ] {
        let error = snapback
            .invoke_query("boardView", bounded_input("parent-a", Some(&wire)))
            .expect_err("restart cursor matrix member refuses");
        assert_eq!(
            error.diagnostic.code,
            "SNAPBACK_SNAPSHOT_BATCH_RESTART_REQUIRED",
        );
    }
}

#[test]
fn snapshot_batch_pins_every_node_to_one_snapshot_across_a_sibling_commit() {
    let dir = tempfile::tempdir().expect("snapshot directory");
    let path = dir.path().join("snapshot-batch.sqlite3");
    let (schema, functions, _) = snapshot_batch_publication_fixture(3, 2);
    let mut reader = LocalSnapback::open(&path).expect("snapshot reader");
    reader.apply_schema(schema).expect("apply schema");
    let diagnostics = reader.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "snapshot fixture activates: {diagnostics:?}",
    );
    seed_bounded_publication_fixture(&mut reader, "private");

    let (reached_tx, reached_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let _hook =
        crate::storage::set_storage_read_snapshot_debug_hook(&reader.db, reached_tx, release_rx);
    let lane = reader.read_lane();
    let writer = std::thread::spawn(move || {
        reached_rx
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("reader pins its predecessor snapshot");
        reader
            .invoke_mutation(
                "addChild",
                HandlerInput {
                    args: json!({
                        "parentId":"parent-a", "position":5, "label":"concurrent",
                        "active":false, "externalKey":"snapshot-concurrent"
                    }),
                    auth: AuthInput {
                        user_id: Some("user-a".to_owned()),
                        ..AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
            )
            .expect("serving-writer commit while reader is pinned");
        release_tx.send(()).expect("release pinned reader");
    });
    let input = HandlerInput {
        args: json!({"parentId":"parent-a"}),
        auth: AuthInput {
            user_id: Some("user-a".to_owned()),
            ..AuthInput::default()
        },
        ..HandlerInput::default()
    };
    let predecessor = lane
        .invoke_query("boardView", input.clone())
        .expect("pinned predecessor batch");
    writer.join().expect("sibling writer joins");
    for node in predecessor.rows[0]["nodes"].as_array().expect("node tuple") {
        assert!(
            node["children"]
                .as_array()
                .expect("children")
                .iter()
                .all(|child| child["label"] != "concurrent"),
            "no node may observe the between-evaluation sibling commit",
        );
    }
    let successor = lane
        .invoke_query("boardView", input)
        .expect("successor batch");
    assert!(successor.version > predecessor.version);
    for node in successor.rows[0]["nodes"].as_array().expect("node tuple") {
        assert_eq!(node["children"][0]["label"], "concurrent");
    }
}

#[test]
fn snapshot_batch_eight_node_budget_uses_declared_serialized_widths() {
    let (schema, functions, plan) = snapshot_batch_publication_fixture(8, 2);
    let mut snapback = LocalSnapback::memory().expect("budget store");
    snapback.apply_schema(schema).expect("apply schema");
    let function = functions
        .functions
        .iter()
        .find(|function| function.name == "boardView")
        .expect("batch function");
    let identity =
        crate::manifest::snapshot_batch_identity_v1(function, &plan).expect("eight-node identity");
    let args = json!({"parentId":"parent-a"});
    enforce_snapshot_batch_cursor_budget(
        &DbRead::Live(&snapback.db),
        &plan,
        &identity,
        "generation-maximum-spelling",
        "app",
        "database",
        "stream",
        &function.id,
        &args,
        &format!("sha256:{}", "a".repeat(64)),
        &["parent-a".to_owned()],
    )
    .expect("eight bounded nodes fit their declared compact-JSON budget");

    let mut oversized = plan;
    for node in &mut oversized.nodes {
        node.order
            .iter_mut()
            .find(|entry| entry.field == "label")
            .expect("string order")
            .max_encoded_bytes = Some(6_000);
    }
    let oversized_identity = crate::manifest::snapshot_batch_identity_v1(function, &oversized)
        .expect("oversized identity remains structurally valid");
    assert_eq!(
        enforce_snapshot_batch_cursor_budget(
            &DbRead::Live(&snapback.db),
            &oversized,
            &oversized_identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &args,
            &format!("sha256:{}", "a".repeat(64)),
            &["parent-a".to_owned()],
        )
        .expect_err("serialized worst case must refuse before parent reads")
        .diagnostic
        .code,
        "SNAPBACK_SNAPSHOT_BATCH_CURSOR_BUDGET_EXCEEDED",
    );

    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "eight-node fixture activates: {diagnostics:?}",
    );
    seed_bounded_publication_fixture(&mut snapback, "private");
    let first = snapback
        .invoke_query("boardView", bounded_input("parent-a", None))
        .expect("eight-node first page");
    let cursor = first.rows[0]["continuation"]
        .as_str()
        .unwrap_or_else(|| panic!("eight-node coordinated cursor: {first:?}"));
    assert!(cursor.starts_with("sbsb1."));
    assert!(cursor.len() <= crate::snapshot_batch_cursor::MAX_WIRE_BYTES);
    let resumed = snapback
        .invoke_query("boardView", bounded_input("parent-a", Some(cursor)))
        .expect("eight-node cursor round trip");
    assert_eq!(
        resumed.rows[0]["nodes"]
            .as_array()
            .expect("node tuple")
            .len(),
        8,
    );
}

#[test]
fn snapshot_batch_budget_pins_scalar_widths_at_6099_and_refuses_6100() {
    let (mut schema, functions, plan) = snapshot_batch_publication_fixture(8, 2);
    let id_order_field = schema
        .tables
        .iter_mut()
        .find(|table| table.name == "children")
        .and_then(|table| table.fields.iter_mut().find(|field| field.name == "label"))
        .expect("bounded id order field");
    id_order_field.field_type = FieldType::Id {
        table: "parents".to_owned(),
    };

    let bounds = order_field_bounds_from_functions(&functions, &schema)
        .expect("id order fields accept the shared write-enforced bound");
    assert_eq!(
        bounds.get(&("children".to_owned(), "label".to_owned())),
        Some(&16),
    );

    let mut snapback = LocalSnapback::memory().expect("budget store");
    snapback
        .apply_schema(schema)
        .expect("apply id-order schema");
    let function = functions
        .functions
        .iter()
        .find(|function| function.name == "boardView")
        .expect("batch function");
    let identity =
        crate::manifest::snapshot_batch_identity_v1(function, &plan).expect("eight-node identity");
    let db = DbRead::Live(&snapback.db);
    assert_eq!(
        snapshot_batch_max_boundary(&db, &plan.nodes[0]).expect("closed scalar widths"),
        vec![
            Value::from(-9_007_199_254_740_991_i64),
            Value::String("\u{0}".repeat(16)),
            Value::Bool(false),
        ],
        "integer, bounded id, and boolean use LLP 0157's exact templates",
    );

    let authority_partition = format!("sha256:{}", "a".repeat(64));
    let parent_ids = ["parent-a".to_owned()];
    let empty_padding_args = json!({"parentId":"parent-a", "padding":""});
    let empty_padding_len = snapshot_batch_max_plaintext_len(
        &db,
        &plan,
        &identity,
        "generation-maximum-spelling",
        "app",
        "database",
        "stream",
        &function.id,
        &empty_padding_args,
        &authority_partition,
        &parent_ids,
    )
    .expect("bounded id template leaves room for exact-boundary padding");
    let padding_len = crate::snapshot_batch_cursor::MAX_PLAINTEXT_BYTES
        .checked_sub(empty_padding_len)
        .expect("fixture begins below the plaintext ceiling");

    let at_limit_args = json!({
        "parentId":"parent-a",
        "padding":"x".repeat(padding_len),
    });
    assert_eq!(
        snapshot_batch_max_plaintext_len(
            &db,
            &plan,
            &identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &at_limit_args,
            &authority_partition,
            &parent_ids,
        )
        .expect("serialize exact 6,099-byte template"),
        6_099,
    );
    enforce_snapshot_batch_cursor_budget(
        &db,
        &plan,
        &identity,
        "generation-maximum-spelling",
        "app",
        "database",
        "stream",
        &function.id,
        &at_limit_args,
        &authority_partition,
        &parent_ids,
    )
    .expect("6,099-byte template is admitted");

    let over_limit_args = json!({
        "parentId":"parent-a",
        "padding":"x".repeat(padding_len + 1),
    });
    assert_eq!(
        snapshot_batch_max_plaintext_len(
            &db,
            &plan,
            &identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &over_limit_args,
            &authority_partition,
            &parent_ids,
        )
        .expect("serialize exact 6,100-byte template"),
        6_100,
    );
    assert_eq!(
        enforce_snapshot_batch_cursor_budget(
            &db,
            &plan,
            &identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &over_limit_args,
            &authority_partition,
            &parent_ids,
        )
        .expect_err("6,100-byte template must refuse before parent reads")
        .diagnostic
        .code,
        "SNAPBACK_SNAPSHOT_BATCH_CURSOR_BUDGET_EXCEEDED",
    );

    let mut unbounded_id = plan;
    for node in &mut unbounded_id.nodes {
        node.order
            .iter_mut()
            .find(|order| order.field == "label")
            .expect("id order")
            .max_encoded_bytes = None;
    }
    let unbounded_identity = crate::manifest::snapshot_batch_identity_v1(function, &unbounded_id)
        .expect("unbounded id identity remains structurally valid");
    assert_eq!(
        enforce_snapshot_batch_cursor_budget(
            &db,
            &unbounded_id,
            &unbounded_identity,
            "generation-maximum-spelling",
            "app",
            "database",
            "stream",
            &function.id,
            &empty_padding_args,
            &authority_partition,
            &parent_ids,
        )
        .expect_err("id order fields without declared bounds fail closed")
        .diagnostic
        .code,
        "SNAPBACK_SNAPSHOT_BATCH_CURSOR_BUDGET_EXCEEDED",
    );
}

fn seed_bounded_publication_fixture(snapback: &mut LocalSnapback, foreign_secret: &str) {
    let has_row_owner = snapback
        .db
        .schema()
        .table("children")
        .is_some_and(|table| table.fields.iter().any(|field| field.name == "rowOwner"));
    let row = |value: Value| {
        let mut row = value.as_object().cloned().expect("seed object");
        if has_row_owner && row.contains_key("parentId") {
            let owner = if row.get("parentId") == Some(&json!("parent-b")) {
                "user-b"
            } else {
                "user-a"
            };
            row.insert("rowOwner".to_owned(), json!(owner));
        }
        row
    };
    let parent_rows = vec![
        row(json!({
            "_id": "parent-a", "owner": "user-a", "title": "visible"
        })),
        row(json!({
            "_id": "parent-b", "owner": "user-b", "title": foreign_secret
        })),
        row(json!({
            "_id": "parent-c", "owner": "user-a", "title": "other visible"
        })),
    ];
    let child_rows = vec![
        row(json!({
            "_id": "child-10", "parentId": "parent-a",
            "position": 10, "label": "é", "active": false,
            "externalKey": "shared"
        })),
        row(json!({
            "_id": "child-20-a", "parentId": "parent-a",
            "position": 20, "label": "a", "active": false,
            "externalKey": "twenty-a"
        })),
        row(json!({
            "_id": "child-20-b", "parentId": "parent-a",
            "position": 20, "label": "a", "active": true,
            "externalKey": "twenty-b"
        })),
        row(json!({
            "_id": "child-30", "parentId": "parent-a",
            "position": 30, "label": "z", "active": false,
            "externalKey": "thirty"
        })),
        row(json!({
            "_id": "foreign-child", "parentId": "parent-b",
            "position": 1, "label": foreign_secret, "active": true,
            "externalKey": "shared"
        })),
        row(json!({
            "_id": "other-visible-child", "parentId": "parent-c",
            "position": 1, "label": "other", "active": true,
            "externalKey": "other"
        })),
    ];
    let public_parent_rows = parent_rows
        .iter()
        .cloned()
        .map(|mut row| {
            row.remove("owner");
            row
        })
        .collect();
    let public_child_rows = child_rows
        .iter()
        .cloned()
        .map(|mut row| {
            row.remove("rowOwner");
            row
        })
        .collect();
    snapback
        .seed(crate::manifest::SeedData {
            tables: BTreeMap::from([
                ("parents".to_owned(), parent_rows),
                ("children".to_owned(), child_rows),
                ("publicParents".to_owned(), public_parent_rows),
                ("publicChildren".to_owned(), public_child_rows),
            ]),
        })
        .expect("seed bounded publication fixture");
}

fn bounded_input(parent: &str, cursor: Option<&str>) -> HandlerInput {
    let mut args = json!({ "parentId": parent });
    if let Some(cursor) = cursor {
        args["cursor"] = json!(cursor);
    }
    HandlerInput {
        args,
        auth: AuthInput {
            user_id: Some("user-a".to_owned()),
            ..AuthInput::default()
        },
        ..HandlerInput::default()
    }
}

// @ref LLP 0231#d3--composed-into-the-plan-sized-by-a-plan-class-model — the
// standalone bounded carrier and every snapshot-batch node carry the exact
// child-table policy; the runtime intersects it with through-parent scope.
#[test]
fn bounded_children_and_snapshot_batch_compose_declared_child_visibility() {
    let (schema, functions, _) = snapshot_batch_publication_fixture(2, 16);
    // @ref LLP 0264#d3-owner-inserts-are-host-stamped — rowOwner is a
    // dedicated host-stamped policy field in the base fixture; label remains
    // authored test data.

    let mut snapback = LocalSnapback::memory().expect("policy-composed bounded store");
    snapback
        .apply_schema(schema)
        .expect("apply composed schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "policy-composed functions activate: {diagnostics:?}",
    );
    seed_bounded_publication_fixture(&mut snapback, "foreign-secret");
    for (id, position, label) in [
        ("visible-policy-child", 91, "user-a"),
        ("hidden-policy-child", 92, "user-b"),
    ] {
        snapback
            .invoke_mutation(
                "addChild",
                HandlerInput {
                    args: json!({
                        "parentId": "parent-a",
                        "position": position,
                        "label": label,
                        "active": false,
                        "externalKey": id,
                    }),
                    auth: AuthInput {
                        user_id: Some(label.to_owned()),
                        ..AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
            )
            .expect("seed policy child through relation-aware mutation");
    }

    let bounded = snapback
        .invoke_query("parentChildren", bounded_input("parent-a", None))
        .expect("bounded composed read");
    let bounded_labels = bounded.rows[0]["children"]
        .as_array()
        .expect("bounded children")
        .iter()
        .map(|row| row["label"].as_str().expect("child label"))
        .collect::<Vec<_>>();
    assert!(bounded_labels.contains(&"user-a"));
    assert!(!bounded_labels.contains(&"user-b"));

    let snapshot = snapback
        .invoke_query("boardView", bounded_input("parent-a", None))
        .expect("snapshot composed read");
    let nodes = snapshot.rows[0]["nodes"]
        .as_array()
        .expect("snapshot nodes");
    assert_eq!(nodes.len(), 2);
    for node in nodes {
        let labels = node["children"]
            .as_array()
            .expect("node children")
            .iter()
            .map(|row| row["label"].as_str().expect("child label"))
            .collect::<Vec<_>>();
        assert!(labels.contains(&"user-a"));
        assert!(!labels.contains(&"user-b"));
    }
}

// @ref LLP 0110#81-bounded-children — paired stores differing only in
// unauthorized bytes are publicly identical. The partitioned unique key
// admits the same value in another scope/incarnation but refuses a
// duplicate inside the authorized scope.
#[test]
fn bounded_children_paired_store_noninterference_and_partitioned_uniqueness() {
    let build =
        |secret: &str| {
            let (schema, functions) = bounded_children_publication_fixture(16);
            let mut snapback = LocalSnapback::memory().expect("paired relation store");
            snapback
                .apply_schema(schema)
                .expect("apply relation schema");
            let diagnostics = snapback.load_functions(functions);
            assert!(
                diagnostics.iter().all(|diagnostic| diagnostic.severity
                    != crate::diagnostic::DiagnosticSeverity::Error),
                "{diagnostics:?}"
            );
            seed_bounded_publication_fixture(&mut snapback, secret);
            snapback
        };
    let mut left = build("left-private");
    let right = build("right-private");
    let visible_left = left
        .invoke_query("parentChildren", bounded_input("parent-a", None))
        .expect("left visible");
    let visible_right = right
        .invoke_query("parentChildren", bounded_input("parent-a", None))
        .expect("right visible");
    assert_eq!(
        serde_json::to_vec(&visible_left).unwrap(),
        serde_json::to_vec(&visible_right).unwrap(),
        "unauthorized bytes do not perturb result/status/transport payload"
    );
    for cursor in [None, Some("sbbc1.malformed")] {
        let left_absent = left
            .invoke_query("parentChildren", bounded_input("parent-b", cursor))
            .expect("left invisible collapses to absent");
        let right_absent = right
            .invoke_query("parentChildren", bounded_input("missing", cursor))
            .expect("right missing collapses to absent");
        assert_eq!(
            serde_json::to_vec(&left_absent).unwrap(),
            serde_json::to_vec(&right_absent).unwrap()
        );
    }

    // `shared` already exists under parent-a and parent-b. The scoped
    // unique key admits the cross-owner pair, but another parent-a value
    // is a typed conflict and leaves no row.
    let before = left
        .db
        .query_reads_read()
        .scan_table("children", 32, 0)
        .unwrap()
        .total;
    let error = left
        .invoke_mutation(
            "addChild",
            HandlerInput {
                args: json!({
                    "parentId": "parent-a", "position": 99, "label": "dup",
                    "active": false, "externalKey": "shared"
                }),
                auth: AuthInput {
                    user_id: Some("user-a".to_owned()),
                    ..AuthInput::default()
                },
                ..HandlerInput::default()
            },
        )
        .expect_err("same-scope unique value must refuse");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_UNIQUE_CONSTRAINT_VIOLATION"
    );
    assert_eq!(
        left.db
            .query_reads_read()
            .scan_table("children", 32, 0)
            .unwrap()
            .total,
        before
    );
}

// @ref LLP 0110#sbbc1-cursor-protocol-and-restart-precedence — the local
// persisted executor uses canonical multi-type boundary order plus `_id`,
// follows the documented concurrent insert/delete/move rules, restarts
// after a parent version change, hides deleted parents, and publishes only
// authoritative live_replace frames.
#[test]
fn bounded_children_cursor_concurrency_deletion_and_live_replacement() {
    let (schema, functions) = bounded_children_publication_fixture(2);
    let mut snapback = LocalSnapback::memory().expect("bounded cursor store");
    snapback
        .apply_schema(schema)
        .expect("apply relation schema");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "{diagnostics:?}"
    );
    seed_bounded_publication_fixture(&mut snapback, "foreign");

    let page1 = snapback
        .invoke_query("parentChildren", bounded_input("parent-a", None))
        .expect("first bounded page");
    let row1 = &page1.rows[0];
    assert_eq!(row1["kind"], "visible");
    assert_eq!(
        row1["children"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["_id"].clone())
            .collect::<Vec<_>>(),
        vec![json!("child-10"), json!("child-20-a")],
        "integer, binary string, boolean, then UTF-8 id totalize the boundary"
    );
    let cursor = row1["continuation"]
        .as_str()
        .expect("full page continuation")
        .to_owned();
    assert!(cursor.starts_with("sbbc1."));

    for (function, input, label) in [
        (
            "parentChildren",
            bounded_input("parent-a", Some("sbbc1.malformed")),
            "malformed",
        ),
        (
            "otherParentChildren",
            bounded_input("parent-a", Some(&cursor)),
            "cross-function",
        ),
        (
            "parentChildren",
            bounded_input("parent-c", Some(&cursor)),
            "cross-parent",
        ),
    ] {
        let error = match snapback.invoke_query(function, input) {
            Ok(output) => panic!("{label} cursor unexpectedly produced {output:?}"),
            Err(error) => error,
        };
        assert_eq!(
            error.diagnostic.code, "SNAPBACK_BOUNDED_CHILDREN_CURSOR_INVALID",
            "{label}"
        );
    }

    let public_anonymous = HandlerInput {
        args: json!({ "parentId": "parent-a" }),
        ..HandlerInput::default()
    };
    let public_cursor = snapback
        .invoke_query("publicParentChildren", public_anonymous)
        .expect("anonymous public first page")
        .rows[0]["continuation"]
        .as_str()
        .expect("public continuation")
        .to_owned();
    let cross_partition = snapback
        .invoke_query(
            "publicParentChildren",
            bounded_input("parent-a", Some(&public_cursor)),
        )
        .expect_err("public cursor is bound to anonymous/authenticated partition");
    assert_eq!(
        cross_partition.diagnostic.code,
        "SNAPBACK_BOUNDED_CHILDREN_CURSOR_INVALID"
    );

    let (other_schema, other_functions) = bounded_children_publication_fixture(2);
    let mut other_database =
        LocalSnapback::memory().expect("cross-deployment bounded cursor store");
    other_database
        .apply_schema(other_schema)
        .expect("apply cross-deployment schema");
    let other_diagnostics = other_database.load_functions(other_functions);
    assert!(
        other_diagnostics
            .iter()
            .all(|diagnostic| diagnostic.severity != crate::diagnostic::DiagnosticSeverity::Error)
    );
    seed_bounded_publication_fixture(&mut other_database, "foreign");
    let cross_deployment = other_database
        .invoke_query("parentChildren", bounded_input("parent-a", Some(&cursor)))
        .expect_err("cursor never crosses database/key custody");
    assert_eq!(
        cross_deployment.diagnostic.code,
        "SNAPBACK_BOUNDED_CHILDREN_CURSOR_INVALID"
    );

    let mutate = |snapback: &mut LocalSnapback, name: &str, args: Value| {
        snapback
            .invoke_mutation(
                name,
                HandlerInput {
                    args,
                    auth: AuthInput {
                        user_id: Some("user-a".to_owned()),
                        ..AuthInput::default()
                    },
                    ..HandlerInput::default()
                },
            )
            .unwrap_or_else(|error| panic!("{name}: {error:?}"))
    };
    mutate(
        &mut snapback,
        "addChild",
        json!({
            "parentId": "parent-a", "position": 25, "label": "after",
            "active": false, "externalKey": "inserted-after"
        }),
    );
    mutate(
        &mut snapback,
        "addChild",
        json!({
            "parentId": "parent-a", "position": 15, "label": "before",
            "active": false, "externalKey": "inserted-before"
        }),
    );
    mutate(&mut snapback, "deleteChild", json!({ "id": "child-30" }));
    mutate(
        &mut snapback,
        "moveChild",
        json!({ "id": "child-10", "value": 40 }),
    );
    let page2 = snapback
        .invoke_query("parentChildren", bounded_input("parent-a", Some(&cursor)))
        .expect("concurrent successor page");
    let keys = page2.rows[0]["children"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row["externalKey"].clone())
        .collect::<Vec<_>>();
    assert_eq!(
        keys,
        vec![json!("twenty-b"), json!("inserted-after")],
        "insert after the boundary appears; insert before does not; delete \
             disappears; a moved row is permitted to reappear on a later page"
    );

    mutate(
        &mut snapback,
        "renameParent",
        json!({ "id": "parent-a", "value": "renamed" }),
    );
    let restart = snapback
        .invoke_query("parentChildren", bounded_input("parent-a", Some(&cursor)))
        .expect_err("parent projection/version change restarts continuation");
    assert_eq!(
        restart.diagnostic.code,
        "SNAPBACK_BOUNDED_CHILDREN_PARENT_RESTART_REQUIRED"
    );

    let subscribed = snapback
        .subscribe_live(
            "parentChildren",
            LiveSubscribeInput {
                connection_id: "conn-bounded".to_owned(),
                input: bounded_input("parent-a", None),
                authorization_namespace: None,
                supersedes: None,
                resume_from_token: None,
            },
        )
        .expect("first-page live subscription");
    assert_eq!(
        subscribed.snapshot.as_ref().unwrap().rows[0]["kind"],
        "visible"
    );
    for (name, args) in [
        (
            "addChild",
            json!({
                "parentId": "parent-a", "position": 5, "label": "live",
                "active": false, "externalKey": "live-insert"
            }),
        ),
        ("moveChild", json!({ "id": "child-20-b", "value": 50 })),
        ("deleteChild", json!({ "id": "child-20-b" })),
    ] {
        mutate(&mut snapback, name, args);
        let frames = rqs_drained_envelopes(&mut snapback, "conn-bounded");
        assert!(!frames.is_empty(), "{name} must resnapshot");
        assert!(
            frames.iter().all(|frame| frame["kind"] == "live_replace"),
            "{name} may not claim live_delta"
        );
    }
    mutate(&mut snapback, "deleteParent", json!({ "id": "parent-a" }));
    let frames = rqs_drained_envelopes(&mut snapback, "conn-bounded");
    assert_eq!(frames.last().unwrap()["kind"], "live_replace");
    assert_eq!(frames.last().unwrap()["rows"][0]["kind"], "absent");
    let after_delete = snapback
        .invoke_query("parentChildren", bounded_input("parent-a", Some(&cursor)))
        .expect("deleted parent suppresses cursor validation");
    assert_eq!(after_delete.rows[0]["kind"], "absent");

    let error = snapback
        .subscribe_live(
            "parentChildren",
            LiveSubscribeInput {
                connection_id: "conn-cursor".to_owned(),
                input: bounded_input("parent-b", Some(&cursor)),
                authorization_namespace: None,
                supersedes: None,
                resume_from_token: None,
            },
        )
        .expect_err("cursor-bearing live subscribe refuses before storage");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_BOUNDED_CHILDREN_LIVE_CURSOR_UNSUPPORTED"
    );
}

// @ref LLP 0065#1-fact-classes — the runtime checks observed
//   operations are a subset of the admitted EffectCeilingV1 and fails
//   closed on mismatch: a doctored artifact that under-declares its
//   ceiling refuses activation, and the exact generated ceiling passes.
#[test]
fn effect_ceiling_subset_check_fails_closed_on_mismatch() {
    use crate::manifest::{EffectCeiling, EffectCeilingRead, EffectCeilingWrite};
    let (schema, functions) = relational_live_fixture_functions(10);
    let mut add_book = functions.functions[1].clone();
    assert_eq!(add_book.name, "addBook");

    // The exact ceiling the walker emits for addBook: one insert into books,
    // no reads or host ops, and the owner insert's host-stamped principal.
    add_book.effect_ceiling = Some(EffectCeiling {
        version: "EffectCeilingV1".to_owned(),
        basis: "static".to_owned(),
        reads: Vec::new(),
        writes: vec![EffectCeilingWrite {
            table: "books".to_owned(),
            operations: vec!["insert".to_owned()],
        }],
        host_operations: Vec::new(),
        authorization_inputs: vec!["authUserId".to_owned()],
    });
    let mut snapback = LocalSnapback::memory().expect("memory ceiling fixture");
    snapback
        .apply_schema(schema.clone())
        .expect("apply ceiling schema");
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![add_book.clone()],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "the exact ceiling must activate: {diagnostics:?}"
    );

    // Fault: the same plan with an under-declared ceiling (writes a
    // table the ceiling does not admit) refuses activation.
    let mut doctored = add_book;
    doctored.effect_ceiling = Some(EffectCeiling {
        version: "EffectCeilingV1".to_owned(),
        basis: "static".to_owned(),
        reads: Vec::new(),
        writes: vec![EffectCeilingWrite {
            table: "authors".to_owned(),
            operations: vec!["insert".to_owned()],
        }],
        host_operations: Vec::new(),
        authorization_inputs: vec!["authUserId".to_owned()],
    });
    let mut snapback = LocalSnapback::memory().expect("memory fault fixture");
    snapback
        .apply_schema(schema.clone())
        .expect("apply fault schema");
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![doctored],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics.iter().any(|d| {
            d.code == "SNAPBACK_FUNCTION_EFFECT_CEILING_EXCEEDED"
                || d.message
                    .contains("SNAPBACK_FUNCTION_EFFECT_CEILING_EXCEEDED")
        }),
        "an out-of-ceiling write must refuse activation: {diagnostics:?}"
    );

    // The same subset rule covers authorization inputs: an owner-filtered
    // relational read observing AuthUserId refuses under a ceiling that
    // omits it.
    let mut relational = functions.functions[0].clone();
    relational.effect_ceiling = Some(EffectCeiling {
        version: "EffectCeilingV1".to_owned(),
        basis: "static".to_owned(),
        reads: vec![
            EffectCeilingRead {
                table: "books".to_owned(),
                access: "query".to_owned(),
                index: Some("by_owner_title".to_owned()),
            },
            EffectCeilingRead {
                table: "authors".to_owned(),
                access: "query".to_owned(),
                index: Some("by_slug".to_owned()),
            },
        ],
        writes: Vec::new(),
        host_operations: Vec::new(),
        authorization_inputs: Vec::new(),
    });
    let mut snapback = LocalSnapback::memory().expect("memory auth-input fixture");
    snapback
        .apply_schema(schema)
        .expect("apply auth-input schema");
    let diagnostics = snapback.load_functions(FunctionManifest {
        functions: vec![relational],
        ..FunctionManifest::default()
    });
    assert!(
        diagnostics.iter().any(|d| {
            d.code == "SNAPBACK_FUNCTION_EFFECT_CEILING_EXCEEDED"
                || d.message
                    .contains("SNAPBACK_FUNCTION_EFFECT_CEILING_EXCEEDED")
        }),
        "an undeclared authorization input must refuse activation: {diagnostics:?}"
    );
}

// The Rust subset check and codegen's EffectCeilingV1 walker must stay
//   mirror images: every committed generated manifest activates without
//   a ceiling-exceeded refusal. A divergence in either direction fails
//   here before it ships.
#[test]
fn generated_demo_manifests_pass_the_effect_ceiling_subset_check() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    for demo in [
        "demos/competitive-checkpoint/snapback/generated",
        "demos/todo-v2/snapback/generated",
        "demos/todo/snapback/generated",
    ] {
        let read = |file: &str| {
            std::fs::read_to_string(root.join(demo).join(file))
                .unwrap_or_else(|error| panic!("read {demo}/{file}: {error}"))
        };
        let schema: SchemaManifest = serde_json::from_str(&read("schema.manifest.json"))
            .unwrap_or_else(|error| panic!("parse {demo} schema: {error}"));
        let functions: FunctionManifest = serde_json::from_str(&read("functions.manifest.json"))
            .unwrap_or_else(|error| panic!("parse {demo} functions: {error}"));
        let mut snapback = LocalSnapback::memory().expect("memory demo fixture");
        let _ = snapback.apply_schema(schema);
        let diagnostics = snapback.load_functions(functions);
        assert!(
            diagnostics.iter().all(|d| {
                d.code != "SNAPBACK_FUNCTION_EFFECT_CEILING_EXCEEDED"
                    && !d
                        .message
                        .contains("SNAPBACK_FUNCTION_EFFECT_CEILING_EXCEEDED")
            }),
            "{demo}: generated ceilings must satisfy the runtime subset \
                 check: {diagnostics:?}"
        );
    }
}

// @ref LLP 0065#3-common-pattern-contracts — the same-subject two-app
//   domain negative: cursors are bound to the application authority
//   domain, so a continuation minted by one app instance is refused by
//   another even for the same subject, plan shape, and function name.
#[test]
fn standard_pattern_cursor_never_crosses_the_app_domain() {
    let build = |app_id: &str| {
        let (schema, functions) = relational_live_fixture_functions(1);
        let mut manifest = FunctionManifest {
            functions: functions.functions,
            ..FunctionManifest::default()
        };
        manifest.app_id = app_id.to_owned();
        let mut snapback = LocalSnapback::memory().expect("memory app fixture");
        snapback.apply_schema(schema).expect("apply app schema");
        let diagnostics = snapback.load_functions(manifest);
        assert!(
            diagnostics
                .iter()
                .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
            "app fixture must activate: {diagnostics:?}"
        );
        let row = |fields: Value| fields.as_object().cloned().expect("seed row");
        snapback
                .seed(crate::manifest::SeedData {
                    tables: BTreeMap::from([
                        (
                            "books".to_owned(),
                            vec![
                                row(json!({ "title": "alpha", "authorSlug": "ada", "ownerId": "user-a" })),
                                row(json!({ "title": "beta", "authorSlug": "ada", "ownerId": "user-a" })),
                            ],
                        ),
                        (
                            "authors".to_owned(),
                            vec![row(json!({ "slug": "ada", "name": "Ada" }))],
                        ),
                    ]),
                })
                .expect("seed app rows");
        snapback
    };
    let input = |args: Value| HandlerInput {
        args,
        auth: AuthInput {
            user_id: Some("user-a".to_owned()),
            ..AuthInput::default()
        },
        ..HandlerInput::default()
    };
    let app_a = build("app-a");
    let app_b = build("app-b");
    let page = app_a
        .invoke_query("booksWithAuthors", input(json!({})))
        .expect("app-a first page");
    let cursor = page.cursor.expect("app-a continuation");
    // Same subject, same function name, same plan shape — different
    // application authority domain: refused, never repositioned.
    let error = app_b
        .invoke_query(
            "booksWithAuthors",
            input(json!({ "cursor": cursor.clone() })),
        )
        .expect_err("cross-app cursor must refuse");
    assert_eq!(error.diagnostic.code, "SNAPBACK_RELATIONAL_CURSOR_INVALID");
    // And the home app still accepts it.
    let resumed = app_a
        .invoke_query("booksWithAuthors", input(json!({ "cursor": cursor })))
        .expect("home app resumes");
    assert_eq!(resumed.rows, vec![json!({ "title": "beta" })]);
}

