#[test]
fn live_subscription_observations_join_once_and_record_disconnect_cause() {
    let directory = tempfile::tempdir().expect("live telemetry fixture directory");
    let database_path = directory.path().join("live-telemetry.sqlite3");
    let mut snapback = live_limit_snapback();
    snapback.telemetry = crate::telemetry::Telemetry::open_for_database(
        &database_path,
        "01900000-0000-7000-8000-000000000001",
        crate::telemetry::TelemetryConfig::default(),
    )
    .expect("file-backed live telemetry");

    let unsubscribed = snapback
        .subscribe_live("listItems", live_limit_input("live-unsubscribe", json!({})))
        .expect("subscribe first live observation");
    snapback
        .telemetry
        .force_flush()
        .expect("flush admission before completion");
    let admitted =
        physical_telemetry_events_for_test(&snapback.telemetry, Some("live_subscribe"), None);
    let admission_only = admitted
        .iter()
        .filter(|event| event.phase == "admission")
        .count();
    let premature_terminal = admitted
        .iter()
        .filter(|event| event.phase == "terminal")
        .count();
    assert_eq!((admission_only, premature_terminal), (1, 0));

    snapback
        .unsubscribe_live(
            "listItems",
            LiveUnsubscribeInput {
                subscription_id: unsubscribed.subscription_id,
                connection_id: "live-unsubscribe".to_owned(),
                auth: Default::default(),
            },
        )
        .expect("explicit unsubscribe terminal");
    snapback
        .subscribe_live("listItems", live_limit_input("live-disconnect", json!({})))
        .expect("subscribe disconnect observation");
    snapback.disconnect_topology_for_transport("live-disconnect", 1);
    snapback
        .telemetry
        .force_flush()
        .expect("flush live terminals");

    let rows =
        physical_telemetry_events_for_test(&snapback.telemetry, Some("live_subscribe"), None);
    let mut by_observation = BTreeMap::<String, Vec<_>>::new();
    for row in rows {
        by_observation
            .entry(row.observation.clone())
            .or_default()
            .push(row);
    }
    assert_eq!(by_observation.len(), 2);
    let mut causes = BTreeSet::new();
    for records in by_observation.values() {
        assert_eq!(records.len(), 2, "one admission and one terminal");
        assert_eq!(records[0].phase, "admission");
        assert_eq!(records[1].phase, "terminal");
        assert_eq!(
            records[0].generation, records[1].generation,
            "generation is admission-bound"
        );
        assert_eq!(
            records[0].correlation, records[1].correlation,
            "correlation remains connection-bound"
        );
        let details = records[1].details.as_ref().expect("terminal cause details");
        causes.insert(details["cause"].as_str().unwrap().to_owned());
        if records[0].correlation.as_deref() == Some("live-unsubscribe") {
            assert!(
                records[1].recorded_ts_ms > records[0].recorded_ts_ms,
                "a later flush timestamps completion after admission"
            );
        }
    }
    assert_eq!(
        causes,
        BTreeSet::from(["disconnected".to_owned(), "unsubscribed".to_owned()])
    );
}

#[test]
fn live_resume_retires_predecessor_before_successor_admission() {
    let directory = tempfile::tempdir().expect("resume telemetry fixture directory");
    let database_path = directory.path().join("resume-telemetry.sqlite3");
    let mut snapback = live_limit_snapback();
    snapback.telemetry = crate::telemetry::Telemetry::open_for_database(
        &database_path,
        "01900000-0000-7000-8000-000000000001",
        crate::telemetry::TelemetryConfig::default(),
    )
    .expect("file-backed resume telemetry");
    let subscribed = snapback
        .subscribe_live("listItems", live_limit_input("resume-before", json!({})))
        .expect("initial live subscription");
    snapback
        .resume_live(
            "listItems",
            LiveResumeInput {
                subscription_id: subscribed.subscription_id.clone(),
                connection_id: "resume-after".to_owned(),
                auth: AuthInput::default(),
                recorded_permission_epochs: subscribed.permission_epochs,
            },
        )
        .expect("authoritative retained resume");
    snapback
        .unsubscribe_live(
            "listItems",
            LiveUnsubscribeInput {
                subscription_id: subscribed.subscription_id,
                connection_id: "resume-after".to_owned(),
                auth: AuthInput::default(),
            },
        )
        .expect("finish resumed successor");
    snapback
        .telemetry
        .force_flush()
        .expect("flush resume spans");
    let rows =
        physical_telemetry_events_for_test(&snapback.telemetry, Some("live_subscribe"), None);
    assert_eq!(rows.len(), 4);
    assert_eq!(
        rows.iter()
            .map(|row| (row.phase.as_str(), row.correlation.as_deref()))
            .collect::<Vec<_>>(),
        vec![
            ("admission", Some("resume-before")),
            ("terminal", Some("resume-before")),
            ("admission", Some("resume-after")),
            ("terminal", Some("resume-after")),
        ],
        "the resume commit retires the predecessor before admitting its successor"
    );
    assert_eq!(rows[0].observation, rows[1].observation);
    assert_eq!(rows[2].observation, rows[3].observation);
    assert_ne!(rows[0].observation, rows[2].observation);
    let predecessor = rows[1].details.as_ref().unwrap();
    let successor = rows[3].details.as_ref().unwrap();
    assert_eq!(predecessor["cause"], "resumed");
    assert_eq!(successor["cause"], "unsubscribed");
}

fn install_test_invalidation(snapback: &mut LocalSnapback) -> AuthorizationInvalidationConnection {
    let (authorization, version_stream, boot_sequence) = snapback
        .auth_database_mut()
        .reserve_invalidation_boot_issuer()
        .expect("reserve test issuer");
    let issuer_id = crate::auth::invalidation::IssuerId::fresh(
        authorization.incarnation.clone(),
        boot_sequence,
    )
    .expect("test issuer id");
    let authenticator =
        crate::auth::invalidation::IssuerAuthenticator::new("test-protocol-key", [0x5a; 32])
            .expect("test authenticator");
    let authenticated = authenticator
        .authenticate(issuer_id, "test-target", "test-app")
        .expect("authenticate test issuer");
    let issuer = LiveInvalidationIssuer::with_authenticator(
        authenticated,
        authenticator,
        "test-target",
        "test-app",
    )
    .expect("live test issuer");
    let descriptor = AuthorizationInvalidationConnection {
        protocol_version: crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION,
        issuer_id: issuer.authenticated().issuer_id.clone(),
        connection_generation: issuer
            .reserve_connection_generation()
            .expect("test connection generation"),
        authorization: authorization.clone(),
        version_stream: version_stream.clone(),
        issuer_retirement: None,
    };
    snapback
        .install_auth_invalidation(issuer, authorization, version_stream)
        .expect("install test invalidation");
    descriptor
}

