#[test]
fn session_live_requires_installed_and_negotiated_invalidation() {
    let mut snapback = live_limit_snapback();
    let input = LiveSubscribeInput {
        connection_id: "session-capability".to_owned(),
        input: HandlerInput::default(),
        authorization_namespace: Some(test_authorization_namespace(1)),
        supersedes: None,
        resume_from_token: None,
    };
    let unavailable = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            input.clone(),
            LiveInvalidationAdmission {
                session_mode: true,
                ..LiveInvalidationAdmission::default()
            },
        )
        .expect_err("missing server invalidation is unavailable");
    assert_eq!(
        unavailable.diagnostic.code,
        "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE"
    );

    let connection = install_test_invalidation(&mut snapback);
    let unsupported = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            input.clone(),
            LiveInvalidationAdmission {
                session_mode: true,
                ..LiveInvalidationAdmission::default()
            },
        )
        .expect_err("legacy session client is refused");
    assert_eq!(
        unsupported.diagnostic.code,
        "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED"
    );
    assert!(
        unsupported
            .diagnostic
            .message
            .contains("authInvalidationProtocol: 1"),
        "the refusal must name the exact connection-open repair"
    );

    let missing_namespace = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                authorization_namespace: None,
                ..input.clone()
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection.clone()),
                effect_fence: None,
            },
        )
        .expect_err("auth-scoped live requires an explicit query namespace");
    assert_eq!(
        missing_namespace.diagnostic.code,
        "SNAPBACK_AUTH_INVALIDATION_NAMESPACE_REQUIRED"
    );
    for member in ["clientStoreId", "queryKey", "queryInstanceId"] {
        assert!(
            missing_namespace.diagnostic.message.contains(member),
            "namespace refusal must name `{member}`"
        );
    }

    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            input,
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("negotiated session subscription");
    assert!(matches!(
        subscribed.authorization_scope,
        Some(ScopeId::Subscription { .. })
    ));
}

// @ref LLP 0080#4-live-and-retained-capability — the obligation-fault
//   e2e: a shrinking replacement on an owner-visible relational
//   subscription is obligation-backed, so a lost delivery cannot leave
//   forbidden rows visible — the level-triggered obligation reprojects
//   until the exact ACK discharges it, and no live_delta ever escapes.
#[test]
fn relational_shrinking_replacement_is_obligation_backed_and_recovered() {
    let (schema, mut functions) = relational_live_fixture_functions(10);
    functions.functions.push(FunctionDefinition::new(
        "deleteBook",
        FunctionKind::Mutation,
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(MutationPlan {
            owner_write_checks: vec![OwnerWriteCheckV1 {
                step_index: 0,
                absent: OwnerWriteAbsentDispositionV1::NoEffect,
            }],
            steps: vec![MutationStep::Delete {
                table: "books".to_owned(),
                id: ValueExpr::Arg("id".to_owned()),
            }],
            return_value: None,
        })),
    ));
    let mut snapback = LocalSnapback::memory().expect("memory shrink fixture");
    snapback.apply_schema(schema).expect("apply shrink schema");
    snapback
        .auth_database_mut()
        .activate_current_auth_catalog()
        .expect("install shrink fixture auth catalog");
    let diagnostics = snapback.load_functions(functions);
    assert!(
        diagnostics
            .iter()
            .all(|d| d.severity != crate::diagnostic::DiagnosticSeverity::Error),
        "shrink fixture must activate: {diagnostics:?}"
    );
    snapback
        .invoke_mutation(
            "addAuthor",
            HandlerInput {
                args: json!({ "slug": "ada", "name": "Ada" }),
                ..HandlerInput::default()
            },
        )
        .expect("insert author");
    snapback
        .invoke_mutation(
            "addBook",
            HandlerInput {
                args: json!({ "title": "alpha", "slug": "ada" }),
                auth: AuthInput {
                    user_id: Some("user-a".to_owned()),
                    ..AuthInput::default()
                },
                ..HandlerInput::default()
            },
        )
        .expect("insert book");
    let book_id = snapback
        .db
        .query_reads_read()
        .query(
            &QueryPlan {
                table_visibility: Some(TableVisibilityV1::Owner {
                    field: "ownerId".to_owned(),
                }),
                table: "books".to_owned(),
                filters: Vec::new(),
                membership_filters: Vec::new(),
                order: Vec::new(),
                limit: None,
                indexed_by: None,
            },
            &HandlerInput {
                auth: AuthInput {
                    user_id: Some("user-a".to_owned()),
                    ..AuthInput::default()
                },
                ..HandlerInput::default()
            },
        )
        .expect("read book id")
        .rows[0]["_id"]
        .as_str()
        .expect("book id")
        .to_owned();

    let connection = install_test_invalidation(&mut snapback);
    insert_live_test_session(
        &mut snapback,
        "user-a",
        "sess-shrink",
        "authinst-shrink",
        45,
    );
    let admission = managed_session_admission();
    let owner_input = HandlerInput {
        auth: AuthInput {
            user_id: Some("user-a".to_owned()),
            ..AuthInput::default()
        },
        ..HandlerInput::default()
    };
    // An owner-visible plan needs a real Session authority under the
    // session-mode admission (the anonymous test default would refuse
    // with AUTH_USER_MISSING).
    let session_authority = |source| {
        crate::auth::invocation::InvocationGate::prepare_authority(
            source,
            AuthMode::Sessions,
            crate::contract_types::ServerProfile::Test,
            1,
            1,
            &crate::auth::invocation::WireAuthorityFields::default(),
            crate::auth::invocation::ResolvedAppAuthority::Session {
                user_id: "user-a".to_owned(),
                session_id: "sess-shrink".to_owned(),
                provider: "test".to_owned(),
                generation: 1,
                authority_instance_id: "authinst-shrink".to_owned(),
                session_not_after_ms: u64::MAX / 2,
                provider_not_after_ms: None,
                rehearsal_provenance: None,
            },
        )
        .expect("prepare session authority")
    };
    let subscribed = snapback
        .subscribe_live_prepared_with_invalidation(
            "booksWithAuthors",
            LiveSubscribeInput {
                connection_id: "rel-shrink".to_owned(),
                input: owner_input,
                authorization_namespace: Some(test_authorization_namespace(7)),
                supersedes: None,
                resume_from_token: None,
            },
            session_authority(crate::auth::invocation::InvocationSource::LiveInitialQuery),
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection.clone()),
                effect_fence: None,
            },
        )
        .expect("owner-visible relational auth-scoped subscription");
    assert_eq!(
        subscribed.snapshot.expect("initial snapshot").rows,
        vec![json!({ "title": "alpha" })],
    );
    assert!(drain_live_stream_through_test_sink(&mut snapback, "rel-shrink").is_empty());

    // The shrinking commit: the only visible root is deleted.
    snapback
        .invoke_mutation_with_authority(
            "deleteBook",
            HandlerInput {
                args: json!({ "id": book_id }),
                ..HandlerInput::default()
            },
            session_authority(crate::auth::invocation::InvocationSource::HttpMutation),
        )
        .expect("delete the visible book");
    let messages =
        project_authorization_frames_through_test_sink(&mut snapback, "rel-shrink", &admission);
    let frame = messages
        .iter()
        .filter_map(|message| serde_json::from_str::<Value>(message).ok())
        .find(|message| message["kind"] == "authorization_invalidation")
        .expect("obligation-backed shrinking replacement frame");
    assert_eq!(frame["obligation"]["maxDisposition"], "quarantine");
    assert_eq!(frame["resolution"]["kind"], "snapshot");
    assert_eq!(frame["snapshot"]["rows"], json!([]));
    assert!(
        messages
            .iter()
            .all(|message| !message.contains("\"kind\":\"live_delta\"")),
        "a relational shrink must never escape as best-effort live_delta"
    );

    // The fault: the replacement is treated as lost — no ACK arrives.
    // Recovery is the obligation machinery, not best-effort delivery:
    // reprojection re-emits the level-triggered obligation, the managed
    // rerun re-delivers the atomic snapshot, and only the exact ACK
    // discharges it.
    snapback
        .reproject_authorization_invalidations("rel-shrink", &admission)
        .expect("reproject after lost delivery");
    let hint = drain_live_stream_through_test_sink(&mut snapback, "rel-shrink")
        .into_iter()
        .filter_map(|message| serde_json::from_str::<Value>(&message).ok())
        .find(|message| message["kind"] == "authorization_invalidation")
        .expect("level-triggered obligation survives the lost delivery");
    assert!(
        hint.get("resolution").is_none() && hint.get("snapshot").is_none(),
        "a snapshot resolution is never projected without its atomic rows"
    );
    let rerun = snapback
        .authorization_invalidation_frames("rel-shrink", &admission)
        .expect("managed rerun");
    let rerun =
        serde_json::from_slice::<Value>(&rerun.first().expect("fresh snapshot frame").payload)
            .expect("rerun frame JSON");
    assert_eq!(rerun["snapshot"]["rows"], json!([]));
    let ack_token = rerun["resolution"]["ackToken"]
        .as_str()
        .expect("ack token")
        .to_owned();
    let ack = snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: "rel-shrink".to_owned(),
                ack_token,
            },
            connection,
            &admission,
        )
        .expect("exact ack");
    assert_eq!(ack.outcome, "discharged");
    assert!(
        snapback
            .authorization_invalidation_frames("rel-shrink", &admission)
            .expect("post-ack frames")
            .is_empty(),
        "the exact ACK discharges the obligation"
    );
}

// @ref LLP 0200#26-quarantine-recovery-lifecycle — RESUBSCRIBE triggers a fresh
// authority resolution but does not reopen ordinary data delivery while
// its quarantine obligation remains unresolved.
#[test]
fn quarantined_resubscribe_stays_fail_closed_until_accepted_authority_proof() {
    let mut snapback = live_limit_snapback();
    let schema = snapback.db.schema().clone();
    let function = snapback
        .functions
        .functions
        .iter_mut()
        .find(|function| function.name == "listItemsByValue")
        .expect("value-filtered live fixture");
    install_schema_documents_contract(function, &schema, "items");
    snapback
        .invoke_mutation(
            "insertItem",
            HandlerInput {
                args: json!({ "value": "retained" }),
                ..HandlerInput::default()
            },
        )
        .expect("seed retained row");

    let connection = install_test_invalidation(&mut snapback);
    let admission = managed_session_admission();
    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItemsByValue",
            LiveSubscribeInput {
                connection_id: "quarantine-resubscribe".to_owned(),
                input: HandlerInput {
                    args: json!({ "value": "retained" }),
                    ..HandlerInput::default()
                },
                authorization_namespace: Some(test_authorization_namespace(201)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection.clone()),
                effect_fence: None,
            },
        )
        .expect("auth-scoped value subscription");
    let scope = subscribed
        .authorization_scope
        .clone()
        .expect("subscription scope");
    assert!(
        drain_live_stream_through_test_sink(&mut snapback, "quarantine-resubscribe").is_empty()
    );

    // Force the RESUBSCRIBE-triggered re-resolution to fail and exhaust
    // its durable automatic retry episode.
    snapback
        .subscriptions
        .get_mut(&subscribed.subscription_id)
        .expect("retained subscription")
        .input
        .args = json!({});
    let error = snapback
        .resume_live_prepared_with_invalidation(
            "listItemsByValue",
            LiveResumeInput {
                subscription_id: subscribed.subscription_id.clone(),
                connection_id: "quarantine-resubscribe".to_owned(),
                auth: AuthInput::default(),
                recorded_permission_epochs: subscribed.permission_epochs.clone(),
            },
            test_session_authority(InvocationSource::LiveResume),
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection.clone()),
                effect_fence: None,
            },
        )
        .expect_err("invalid retained args fail re-resolution");
    assert!(matches!(
        error.diagnostic.code.as_str(),
        "SNAPBACK_ARG_MISSING" | "SNAPBACK_AUTH_RETRY_EXHAUSTED"
    ));
    assert!(
        snapback
            .auth_invalidation
            .as_ref()
            .expect("invalidation state")
            .obligations
            .pending(&scope)
            .is_some_and(|obligation| {
                obligation.max_disposition >= InvalidationDisposition::Quarantine
            })
    );
    assert_eq!(snapback.live_authority_stats.quarantine_entries, 1);
    assert_eq!(snapback.live_authority_stats.quarantine_exits, 0);
    let failure_hints =
        drain_live_stream_through_test_sink(&mut snapback, "quarantine-resubscribe");
    assert!(failure_hints.iter().all(|frame| {
        serde_json::from_str::<Value>(frame)
            .is_ok_and(|frame| frame["kind"] == "authorization_invalidation")
    }));

    // Repair the retained input, then cause a positive delta. The
    // pre-transition authority still cannot publish ordinary data while
    // the quarantine obligation is pending.
    snapback
        .subscriptions
        .get_mut(&subscribed.subscription_id)
        .expect("retained subscription")
        .input
        .args = json!({ "value": "retained" });
    invoke_test_session_mutation(
        &mut snapback,
        "insertItem",
        HandlerInput {
            args: json!({ "value": "retained" }),
            ..HandlerInput::default()
        },
    )
    .expect("matching insert while quarantined");
    let blocked = drain_live_stream_through_test_sink(&mut snapback, "quarantine-resubscribe")
        .into_iter()
        .filter_map(|frame| serde_json::from_str::<Value>(&frame).ok())
        .collect::<Vec<_>>();
    assert!(blocked.iter().all(|frame| {
        !matches!(
            frame["kind"].as_str(),
            Some("live_delta" | "live_replace" | "current_as_of")
        )
    }));
    assert!(
        snapback
            .auth_invalidation
            .as_ref()
            .expect("invalidation state")
            .obligations
            .pending(&scope)
            .is_some()
    );
    assert_eq!(snapback.live_authority_stats.quarantine_entries, 1);
    assert_eq!(snapback.live_authority_stats.quarantine_exits, 0);

    // @ref LLP 0053#invalidation-is-an-obligation-not-a-message — an
    // exhausted retry episode reopens only through an explicit,
    // authority-checked manual retry.
    let retry = snapback
        .manual_retry_authorization_invalidation(
            AuthorizationInvalidationManualRetryInput {
                connection_id: "quarantine-resubscribe".to_owned(),
                subscription_id: subscribed.subscription_id.clone(),
                manual_retry_id: "quarantine-resubscribe-retry-1".to_owned(),
            },
            connection.clone(),
            test_session_authority(InvocationSource::InvalidationAcknowledgement),
        )
        .expect("manual retry resolves repaired input");
    assert_eq!(retry.outcome, "resolved");
    // @ref LLP 0094#0c8-sessions-live-update-envelope-and-delivery-multiplicity —
    // manual retry wakes the retained obligation; the accepted snapshot is
    // projected directly instead of duplicated into the physical outbox.
    let resolution = project_authorization_frames_through_test_sink(
        &mut snapback,
        "quarantine-resubscribe",
        &admission,
    )
    .into_iter()
    .filter_map(|frame| serde_json::from_str::<Value>(&frame).ok())
    .find(|frame| frame["kind"] == "authorization_invalidation" && frame.get("snapshot").is_some())
    .expect("accepted resolution snapshot");
    assert_eq!(resolution["snapshot"]["rows"].as_array().unwrap().len(), 2);
    let ack_token = resolution["resolution"]["ackToken"]
        .as_str()
        .expect("resolution ack token")
        .to_owned();
    assert_eq!(snapback.live_authority_stats.quarantine_exits, 0);

    let ack = snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: "quarantine-resubscribe".to_owned(),
                ack_token,
            },
            connection,
            &admission,
        )
        .expect("exact accepted-resolution ACK");
    assert_eq!(ack.outcome, "discharged");
    assert_eq!(snapback.live_authority_stats.quarantine_entries, 1);
    assert_eq!(snapback.live_authority_stats.quarantine_exits, 1);

    invoke_test_session_mutation(
        &mut snapback,
        "insertItem",
        HandlerInput {
            args: json!({ "value": "retained" }),
            ..HandlerInput::default()
        },
    )
    .expect("matching insert after accepted authority proof");
    let recovered = drain_live_stream_through_test_sink(&mut snapback, "quarantine-resubscribe")
        .into_iter()
        .filter_map(|frame| serde_json::from_str::<Value>(&frame).ok())
        .collect::<Vec<_>>();
    assert!(
        recovered.iter().any(|frame| frame["kind"] == "live_delta"),
        "ordinary data delivery resumes only after exact accepted-proof ACK: {recovered:?}"
    );
}

#[test]
fn auth_scoped_removal_is_atomic_obligation_and_exact_ack() {
    let mut snapback = live_limit_snapback();
    snapback
        .invoke_mutation(
            "insertItem",
            HandlerInput {
                args: json!({ "value": "visible" }),
                ..HandlerInput::default()
            },
        )
        .expect("insert visible row");
    let row_id = snapback
        .invoke_query("listItems", HandlerInput::default())
        .expect("query inserted row")
        .rows[0]["_id"]
        .as_str()
        .expect("row id")
        .to_owned();
    let connection = install_test_invalidation(&mut snapback);
    let admission = managed_session_admission();
    let subscribed = snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "session-remove".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(2)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection.clone()),
                effect_fence: None,
            },
        )
        .expect("auth-scoped subscription");
    assert!(drain_live_stream_through_test_sink(&mut snapback, "session-remove").is_empty());

    invoke_test_session_mutation(
        &mut snapback,
        "deleteItem",
        HandlerInput {
            args: json!({ "id": row_id }),
            ..HandlerInput::default()
        },
    )
    .expect("delete visible row");
    let messages =
        project_authorization_frames_through_test_sink(&mut snapback, "session-remove", &admission);
    let frame = messages
        .iter()
        .filter_map(|message| serde_json::from_str::<Value>(message).ok())
        .find(|message| message["kind"] == "authorization_invalidation")
        .expect("obligation-backed removal frame");
    assert_eq!(frame["obligation"]["maxDisposition"], "quarantine");
    assert_eq!(frame["resolution"]["kind"], "snapshot");
    assert_eq!(frame["snapshot"]["rows"], json!([]));
    assert!(
        messages
            .iter()
            .all(|message| !message.contains("\"kind\":\"live_delta\"")),
        "negative auth delta must not escape as best-effort live_delta"
    );
    snapback
        .reproject_authorization_invalidations("session-remove", &admission)
        .expect("reproject pending truth");
    let hint = drain_live_stream_through_test_sink(&mut snapback, "session-remove")
        .into_iter()
        .filter_map(|message| serde_json::from_str::<Value>(&message).ok())
        .find(|message| message["kind"] == "authorization_invalidation")
        .expect("level-triggered obligation hint");
    assert!(
        hint.get("resolution").is_none() && hint.get("snapshot").is_none(),
        "a snapshot resolution must never be projected without its atomic rows"
    );
    let rerun = snapback
        .authorization_invalidation_frames("session-remove", &admission)
        .expect("managed admission reruns pending authorization");
    let rerun = serde_json::from_slice::<Value>(
        &rerun
            .first()
            .expect("managed drain emits the fresh snapshot")
            .payload,
    )
    .expect("managed drain frame JSON");
    assert_eq!(rerun["snapshot"]["rows"], json!([]));
    let ack_token = rerun["resolution"]["ackToken"]
        .as_str()
        .expect("managed rerun ack token")
        .to_owned();
    let ack = snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: "session-remove".to_owned(),
                ack_token: ack_token.clone(),
            },
            connection.clone(),
            &admission,
        )
        .expect("exact ack");
    assert_eq!(ack.outcome, "discharged");
    let duplicate = snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: "session-remove".to_owned(),
                ack_token,
            },
            connection,
            &admission,
        )
        .expect("duplicate ack");
    assert_eq!(duplicate.outcome, "duplicate");
    assert!(
        snapback
            .authorization_invalidation_frames("session-remove", &admission)
            .expect("drain invalidation frames")
            .is_empty(),
        "successful exact ACK discharges the level-triggered projection"
    );
    assert_eq!(
        subscribed
            .authorization_scope
            .expect("subscription scope")
            .validate(),
        Ok(())
    );
}

// @ref LLP 0053#invalidation-is-an-obligation-not-a-message — a later
//   satisfying snapshot may supersede an unacknowledged resolution, but
//   its distinct frame must advance the exact per-scope ACK identity.
#[test]
fn mutation_fanout_resolution_supersession_never_reuses_frame_key() {
    let mut snapback = live_limit_snapback();
    let connection = install_test_invalidation(&mut snapback);
    let admission = test_session_admission();
    snapback
        .subscribe_live_with_invalidation(
            "listItemsByValue",
            LiveSubscribeInput {
                connection_id: "session-overlap".to_owned(),
                input: HandlerInput {
                    args: json!({ "value": "target" }),
                    ..HandlerInput::default()
                },
                authorization_namespace: Some(QueryNamespace {
                    client_store_id: "store_overlap".to_owned(),
                    query_key: "listItemsByValue:{target}".to_owned(),
                    query_instance_id: 3,
                }),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("auth-scoped filtered subscription");
    assert!(drain_live_stream_through_test_sink(&mut snapback, "session-overlap").is_empty());

    invoke_test_session_mutation(
        &mut snapback,
        "insertItem",
        HandlerInput {
            args: json!({ "value": "target" }),
            ..HandlerInput::default()
        },
    )
    .expect("matching mutation raises and resolves one obligation");
    let first = project_authorization_frames_through_test_sink(
        &mut snapback,
        "session-overlap",
        &admission,
    )
    .into_iter()
    .filter_map(|message| serde_json::from_str::<Value>(&message).ok())
    .find(|message| message["kind"] == "authorization_invalidation")
    .expect("first unacknowledged resolution frame");

    // This commit is disjoint from the filtered query, so fan-out leaves
    // the prior obligation pending. The next level-triggered drain still
    // re-evaluates it at the new store version, overlapping the first
    // unacknowledged resolution exactly as the hot-cycle workload does.
    invoke_test_session_mutation(
        &mut snapback,
        "insertItem",
        HandlerInput {
            args: json!({ "value": "other" }),
            ..HandlerInput::default()
        },
    )
    .expect("disjoint mutation advances the store under the pending obligation");
    assert!(
        drain_live_stream_through_test_sink(&mut snapback, "session-overlap").is_empty(),
        "the disjoint mutation itself must not mint another obligation cause",
    );
    let second_message = snapback
        .authorization_invalidation_frames("session-overlap", &admission)
        .expect("reproject pending resolution")
        .into_iter()
        .next()
        .expect("superseding resolution frame");
    let second =
        serde_json::from_slice::<Value>(&second_message.payload).expect("second frame JSON");

    assert_ne!(
        first["resolution"]["ackToken"], second["resolution"]["ackToken"],
        "distinct resolution frames require distinct acknowledgement tokens",
    );
    assert!(
        second["resolution"]["revision"].as_u64().unwrap()
            > first["resolution"]["revision"].as_u64().unwrap(),
        "distinct resolution frames must not reuse one scope revision",
    );
    assert_ne!(first["snapshot"]["version"], second["snapshot"]["version"]);
    let redelivery = snapback
        .authorization_invalidation_frames("session-overlap", &admission)
        .expect("re-fire current resolution")
        .into_iter()
        .next()
        .expect("current resolution remains pending");
    assert_eq!(
        redelivery.payload, second_message.payload,
        "the same resolution re-fires byte-identically",
    );
}

#[test]
fn overflow_root_waits_for_every_auth_scoped_child() {
    let mut snapback = live_limit_snapback();
    snapback
        .invoke_mutation(
            "insertItem",
            HandlerInput {
                args: json!({ "value": "visible" }),
                ..HandlerInput::default()
            },
        )
        .expect("insert visible row");
    let row_id = snapback
        .invoke_query("listItems", HandlerInput::default())
        .expect("query row")
        .rows[0]["_id"]
        .as_str()
        .expect("row id")
        .to_owned();
    let connection = install_test_invalidation(&mut snapback);
    let admission = test_session_admission();
    for instance in [10, 11] {
        snapback
            .subscribe_live_with_invalidation(
                "listItems",
                LiveSubscribeInput {
                    connection_id: "session-overflow".to_owned(),
                    input: HandlerInput::default(),
                    authorization_namespace: Some(test_authorization_namespace(instance)),
                    supersedes: None,
                    resume_from_token: None,
                },
                LiveInvalidationAdmission {
                    session_mode: true,
                    connection: Some(connection.clone()),
                    effect_fence: None,
                },
            )
            .expect("auth-scoped subscription");
    }
    for _ in 0..1_024 {
        snapback
            .ephemeral
            .enqueue_durable("session-overflow", b"{}".to_vec());
    }
    let deletion = invoke_test_session_mutation(
        &mut snapback,
        "deleteItem",
        HandlerInput {
            args: json!({ "id": row_id }),
            ..HandlerInput::default()
        },
    )
    .expect("delete raises retained authorization obligations");
    // @ref LLP 0094#0c8-sessions-live-update-envelope-and-delivery-multiplicity —
    // auth snapshots no longer overflow the physical outbox. Cross the physical
    // bound with unrelated durable traffic, then project the resulting LLP 0053
    // connection root from retained state.
    let overflowed = snapback
        .ephemeral
        .enqueue_durable("session-overflow", b"{}".to_vec());
    assert!(
        overflowed.overflowed_now,
        "fixture must cross the queue bound"
    );
    snapback
        .raise_connection_overflow("session-overflow", deletion.version)
        .expect("physical overflow raises the retained connection root");
    let overflow = snapback.drain_live_stream("session-overflow");
    let overflow_sentinel_observed = overflow
        .iter()
        .any(|frame| frame.contains("outbox_overflow"));
    assert!(
        overflow_sentinel_observed,
        "bounded queue must expose its overflow sentinel"
    );

    let frames = snapback
        .authorization_invalidation_frames("session-overflow", &admission)
        .expect("drain overflow invalidations");
    assert_eq!(frames.len(), 2, "one exact child per auth-scoped query");
    let tokens = frames
        .iter()
        .map(|frame| serde_json::from_slice::<Value>(&frame.payload).expect("frame JSON"))
        .map(|frame| {
            frame["resolution"]["ackToken"]
                .as_str()
                .expect("resolution token")
                .to_owned()
        })
        .collect::<Vec<_>>();
    snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: "session-overflow".to_owned(),
                ack_token: tokens[0].clone(),
            },
            connection.clone(),
            &admission,
        )
        .expect("first child ack");
    let remaining_after_first_ack = snapback
        .authorization_invalidation_frames("session-overflow", &admission)
        .expect("drain remaining invalidation")
        .len();
    assert_eq!(
        remaining_after_first_ack, 1,
        "one query ACK cannot clear its sibling or the projection root"
    );
    snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: "session-overflow".to_owned(),
                ack_token: tokens[1].clone(),
            },
            connection,
            &admission,
        )
        .expect("second child ack");
    let remaining_after_all_acks = snapback
        .authorization_invalidation_frames("session-overflow", &admission)
        .expect("drain discharged invalidations")
        .len();
    assert_eq!(
        remaining_after_all_acks, 0,
        "root clears only after every current child discharges"
    );
    println!(
        "SNAPBACK_AUTH_ACCEPTANCE_OVERFLOW_RECEIPT={}",
        json!({
            "overflowSentinelObserved": overflow_sentinel_observed,
            "authScopedChildren": tokens.len(),
            "remainingAfterFirstAck": remaining_after_first_ack,
            "remainingAfterAllAcks": remaining_after_all_acks,
        })
    );
}

#[test]
fn aggregate_projection_handoff_is_a_bounded_prefix_and_suffix_stays_pending() {
    let connection_id = "session-projection-prefix";
    let (mut snapback, connection) = two_pending_projection_fixture(connection_id);
    let admission = test_session_admission();
    let full = snapback
        .authorization_invalidation_frames(connection_id, &admission)
        .expect("measure complete pending projection set");
    assert_eq!(full.len(), 2);
    let first_estimate = crate::ephemeral::estimated_durable_handoff_bytes(&full[0]);
    let limit = crate::ephemeral::OUTBOX_HANDOFF_BATCH_OVERHEAD.saturating_add(first_estimate);

    let prefix = snapback
        .authorization_invalidation_frames_with_handoff_limit(connection_id, &admission, limit)
        .expect("bounded projection prefix");
    assert_eq!(prefix.len(), 1, "the second projection is deferred");
    let retained_estimate = prefix.iter().fold(
        crate::ephemeral::OUTBOX_HANDOFF_BATCH_OVERHEAD,
        |total, frame| {
            total.saturating_add(crate::ephemeral::estimated_durable_handoff_bytes(frame))
        },
    );
    assert!(retained_estimate <= limit);
    let projected = serde_json::from_slice::<Value>(&prefix[0].payload).expect("frame JSON");
    let first_token = projected["resolution"]["ackToken"]
        .as_str()
        .expect("first resolution token")
        .to_owned();
    snapback
        .acknowledge_authorization_invalidation(
            AuthorizationInvalidationAckInput {
                connection_id: connection_id.to_owned(),
                ack_token: first_token,
            },
            connection,
            &admission,
        )
        .expect("discharge the emitted prefix");

    let suffix = snapback
        .authorization_invalidation_frames_with_handoff_limit(connection_id, &admission, limit)
        .expect("deferred suffix regenerates");
    assert_eq!(suffix.len(), 1, "the deferred sibling remains pending");
}

#[test]
fn one_projection_over_handoff_limit_fails_closed_and_remains_pending() {
    let connection_id = "session-projection-oversized";
    let (mut snapback, _connection) = two_pending_projection_fixture(connection_id);
    let admission = test_session_admission();
    let full = snapback
        .authorization_invalidation_frames(connection_id, &admission)
        .expect("measure pending projection");
    let first_estimate = crate::ephemeral::estimated_durable_handoff_bytes(&full[0]);
    let too_small = crate::ephemeral::OUTBOX_HANDOFF_BATCH_OVERHEAD
        .saturating_add(first_estimate)
        .saturating_sub(1);
    let error = snapback
        .authorization_invalidation_frames_with_handoff_limit(connection_id, &admission, too_small)
        .expect_err("one unsplittable projection must fail closed");
    assert_eq!(
        error.diagnostic.code,
        "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE"
    );
    assert_eq!(
        snapback
            .authorization_invalidation_frames(connection_id, &admission)
            .expect("failed projection remains level-triggered")
            .len(),
        2
    );
}

#[test]
fn permission_backing_event_quarantines_even_a_positive_delta() {
    let mut snapback = live_limit_snapback();
    snapback
        .apply_schema(SchemaManifest {
            schema_hash: Some("permission-backing-live-schema".to_owned()),
            tables: vec![TableManifest {
                name: "items".to_owned(),
                fields: vec![FieldManifest {
                    name: "value".to_owned(),
                    field_type: FieldType::String,
                    optional: false,
                }],
                indexes: vec![IndexManifest {
                    name: "by_value".to_owned(),
                    fields: vec!["value".to_owned()],
                    unique: false,
                    where_applicable: false,
                }],
                syncable: true,
                permission_backing: true,
                permission_fields: None,
                search_indexes: Vec::new(),
                vector_indexes: Vec::new(),
                search_live_limits: None,
                membership: None,
                authority_profile: None,
                asset_sharing: None,
                visibility: None,
                history: None,
            }],
            ..SchemaManifest::default()
        })
        .expect("mark permission-backing table");
    let connection = install_test_invalidation(&mut snapback);
    let initial_epoch = snapback
        .auth_invalidation
        .as_ref()
        .expect("invalidation state")
        .obligations
        .expectation()
        .authorization
        .epoch;
    snapback
        .subscribe_live_with_invalidation(
            "listItems",
            LiveSubscribeInput {
                connection_id: "session-permission-event".to_owned(),
                input: HandlerInput::default(),
                authorization_namespace: Some(test_authorization_namespace(20)),
                supersedes: None,
                resume_from_token: None,
            },
            LiveInvalidationAdmission {
                session_mode: true,
                connection: Some(connection),
                effect_fence: None,
            },
        )
        .expect("auth-scoped subscription");
    invoke_test_session_mutation(
        &mut snapback,
        "insertItem",
        HandlerInput {
            args: json!({ "value": "newly-visible" }),
            ..HandlerInput::default()
        },
    )
    .expect("permission-backing insert");
    let messages = snapback.drain_live_stream("session-permission-event");
    let frame = messages
        .iter()
        .filter_map(|message| serde_json::from_str::<Value>(message).ok())
        .find(|message| message["kind"] == "authorization_invalidation")
        .expect("coarse authorization obligation");
    assert_eq!(frame["obligation"]["maxDisposition"], "quarantine");
    assert_eq!(
        frame["obligation"]["witness"]["authorization"]["epoch"],
        initial_epoch + 1
    );
    assert!(
        messages
            .iter()
            .all(|message| !message.contains("\"kind\":\"live_delta\"")),
        "coarse authorization events override positive-delta best effort"
    );
    let blast_radius = &snapback.live_delivery.authorization_blast_radius;
    assert_eq!(blast_radius.global.version_advances, 1);
    assert_eq!(blast_radius.global.quarantined_subscriptions, 1);
    assert_eq!(blast_radius.global.resnapshots, 1);
    assert!(blast_radius.membership_declarations.is_empty());
}

#[test]
fn blast_radius_counters_attribute_each_membership_declaration_and_global_total() {
    let mut stats = AuthorizationBlastRadiusStats::default();
    let declarations = ["board-members".to_owned(), "org-members".to_owned()];
    stats.for_event(&declarations, |counters| {
        counters.version_advances += 1;
        counters.quarantined_subscriptions += 3;
        counters.resnapshots += 2;
    });

    assert_eq!(stats.global.version_advances, 1);
    assert_eq!(stats.global.quarantined_subscriptions, 3);
    assert_eq!(stats.global.resnapshots, 2);
    assert_eq!(stats.membership_declarations.len(), 2);
    for declaration in declarations {
        assert_eq!(stats.membership_declarations[&declaration], stats.global);
    }
}

